            #region 檢查101收料的資料是否已經存到dbo.WHGRD
            //=========================================================================================================================
            ////////////Summary by Smose Liao 20091012/////////////////////////////////////////////////////////////////////////////////
            /// <summary>
            /// 檢查101收料的資料是否已經存到dbo.WHGRD
            /// </summary> 
            /// <param name="strMatnr">料號。</param>
            /// <param name="strInsmk">庫別。</param>
            /// <param name="strMatnr">單據號碼。</param>
            /// <param name="strCharg">版本。</param>
            /// <param name="strDacod">DateCode。</param>
            /// <returns>
            /// bool。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageIn objStorageIn =new QCI.QWMS.StorageIn(strConnectionString,strMandt,strWerks,strLgort,strMblnr,strProgid,strCrnam);
            ///  bool  bolReturn = objStorageIn.QueryDataExistsInStorageGR(string strMatnr, string strInsmk, string strMblnr, string strCharg, string strDacod);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////	
            public bool QueryDataExistsInStorageGR(string strMatnr, string strInsmk, string strMblnr, string strCharg, string strDacod)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryDataExistsInStorageGR";
                this.ControlMethodParm = "(" + strMblnr + "," + strInsmk + "," + strMblnr + "," + strCharg + "," + strDacod + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhgrd objWhgrd = new DataWhgrd(UserData);

                //string strSQL = "Select * from WHGRD where MANDT='" + MANDT + "' and WERKS='" + WERKS + "' and LGORT='" + LGORT + "' and MATNR='" + strMatnr + "' and INSMK='" + strInsmk + "' and MBLNR='" + strMblnr + "' and CHARG='" + strCharg + "' and SERNO = '" + strSerNo + "'";
                alColumns.Add("*");
                alConditions.Add(" MANDT='" + MANDT + "'");
                alConditions.Add(" COMCD='" + COMCD + "'");
                alConditions.Add(" WERKS='" + WERKS + "'");
                alConditions.Add(" LGORT='" + LGORT + "'");
                alConditions.Add(" INSMK='" + strInsmk + "'");
                alConditions.Add(" MBLNR='" + strMblnr + "'");
                alConditions.Add(" CHARG='" + strCharg + "'");
                alConditions.Add(" DACOD='" + strDacod + "'");

                try
                {
                    dtData = objWhgrd.EntityQuery(alColumns, alConditions, false);
                }

                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                if (dtData.Rows.Count > 0)
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }
            #endregion

            #region  查询EC单是否存在表ECInfo,存在就不插入，不存在就在EC系统里找，如果还是不存在就是无EC单信息。 //by Blank 2015/05/25
            public DataTable CheckECIFexist(string vbeln)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "CheckECIFexist";
                this.ControlMethodParm = "vbeln";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                string strSQL = "";

                strSQL = "EXEC SP_GetECInfoFromQEC '" + vbeln + "'";
                try
                {
                    ControlHandleDB();
                    bool values = ControlSqlAccess.ExecSql(strSQL);

                    if (values)
                    {
                        string strSQL2 = "Select * from ECInfo where VBELN='" + vbeln + "'";
                        ControlHandleDB();
                        DataTable ECInfo = ControlSqlAccess.GetDataTable(strSQL2);
                        ControlSqlAccess.CloseConnection();
                        return ECInfo;
                    }
                    else
                    {
                        ControlSqlAccess.CloseConnection();
                        return null;
                    }

                }

                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

            }
