            public bool InsertECBox(DataTable dtECBox)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "InsertECBox";
                this.ControlMethodParm = "dtECBox";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
