                    ControlHandleError("000", "", "");
                }
                string strSQL = "";
                ArrayList arrSQL = new ArrayList();
                for (int i = 0; i < dtECBox.Rows.Count; i++)
                {
                    strSQL = "insert into ECBOX VALUES('" + dtECBox.Rows[i]["MANDT"].ToString() + "','" + dtECBox.Rows[i]["COMCD"].ToString() + "','" + dtECBox.Rows[i]["WERKS"].ToString() + "','" + dtECBox.Rows[i]["LGORT"].ToString() + "','" + dtECBox.Rows[i]["ECNum"].ToString() + "','" + dtECBox.Rows[i]["BOXID"].ToString() + "','" + dtECBox.Rows[i]["PartNo"].ToString() + "','" + dtECBox.Rows[i]["GNum"].ToString() + "','" + dtECBox.Rows[i]["SNum"].ToString() + "','" + dtECBox.Rows[i]["TotalNum"].ToString() + "','N','" + UserData.UserId.ToString() + "',getdate(),'" + dtECBox.Rows[i]["LotCode"].ToString() + "')";
                    arrSQL.Add(strSQL);
                }
                try
                {
                    ControlHandleDB();
