            #region 查詢101收料存到dbo.WHGRD的數量
            //====================================================================================
            ////////////Summary by Smose Liao 20091012////////////////////////////////////////////
            /// <summary>
            /// 查詢101收料存到dbo.WHGRD的數量
            /// </summary> 
            /// <param name="strMblnr">單據號碼。</param>
            /// <param name="strInsmk">庫別。</param>
            /// <param name="strCharg">版本。</param>
            /// <param name="strDacod">DateCode。</param>
            /// <returns>
            /// int。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort,strMblnr,strProgid,strCrnam);
            ///  int  bolReturn = objStorageData.QueryGrdQty(string strMblnr, string strInsmk, string strCharg, string strDacod);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////	
            public int QueryGrdQty(string strMblnr, string strInsmk, string strCharg, string strDacod)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryGrdQty";
                this.ControlMethodParm = "(" + strMblnr + "," + strInsmk + "," + strCharg + "," + strDacod + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                int intMenge = 0;
                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhgrd objWhgrd = new DataWhgrd(UserData);

                //string strSQL = "Select MENGE from WHGRD where MANDT= '" + MANDT + "' and WERKS = '" + WERKS + "' and LGORT = '" + LGORT + "' and MBLNR = '" + strMblnr + "' and INSMK= '" + strInsmk + "' and CHARG = '" + strCharg + "'  and DACOD = '" + strDacod + "'";
                alColumns.Add("MENGE");
                alConditions.Add(" MANDT='" + MANDT + "'");
                alConditions.Add(" COMCD='" + COMCD + "'");
                alConditions.Add(" WERKS='" + WERKS + "'");
                alConditions.Add(" LGORT='" + LGORT + "'");
                alConditions.Add(" INSMK='" + strInsmk + "'");
                alConditions.Add(" MBLNR='" + strMblnr + "'");
                alConditions.Add(" CHARG='" + strCharg + "'");

                //假加strDacod不等於空值，才當where條件  Smose Liao 20091019
                if (strDacod != "")
                {
                    //sbSql.AppendFormat("AND Dacod='{0}' ", strDacod);
                    alConditions.Add(" Dacod='" + strDacod + "'");
                }

                try
                {
                    //intMenge = Convert.ToInt32(ControlSqlAccess.GetFieldValue(sbSql.ToString()).ToString());
                    try
                    {
                        dtData = objWhgrd.EntityQuery(alColumns, alConditions, false);
                    }
                    catch (Exception ex)  //假如查不到資料的話
                    {
                        intMenge = 0;
                    }

                    //若已存WHGRD.Menge的數量查不到，則回傳0  Smose Liao 20091028 
                    if (dtData.Rows.Count > 0)
                    {
                        for (int i = 0; i < dtData.Rows.Count; i++)
                        {
                            intMenge += Convert.ToInt32(dtData.Rows[i]["Menge"].ToString());
                        }
                    }
                }

                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return intMenge;
            }

