            /// <summary>
            /// 連線入庫by DateCode / 連線出庫by DateCode(取得當天日期的入庫單/出庫單的單號)
            /// </summary> 
            /// <param name="CTRLID">入庫/出庫。</param>
            /// <param name="CTRLNM">識別。</param>
            /// <returns>
            /// DataSet。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.GetGrrno();
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////
            public string GetGrrno(string Ctrlid, string Ctrlnm)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "GetGrrno";
                this.ControlMethodParm = "(" + Ctrlid + "," + Ctrlnm + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                string Grrno = "";
                string Serno = "";
                StringBuilder sbSql = new StringBuilder();
                //strSQL = "SELECT SERNO FROM SERNUM WHERE SYSNAM='QWMS' AND SERNAM = '" + Ctrlid + "' and SERIID = '" + Ctrlnm + "' AND CYEAR = SUBSTRING(Convert(varchar(8),GETDATE(),112),1,4) AND CMONTH = SUBSTRING(Convert(varchar(8),GETDATE(),112),5,2) AND CDAY = SUBSTRING(Convert(varchar(8),GETDATE(),112),7,2)";
                sbSql.Append("Select SERNO FROM SERNUM where  ");
                sbSql.AppendFormat("SYSNAM='QWMS' ", "");
                sbSql.AppendFormat("AND SERNAM='{0}' ", Ctrlid);
                sbSql.AppendFormat("AND SERIID='{0}' ", Ctrlnm);
                sbSql.AppendFormat("AND CYEAR = SUBSTRING(Convert(varchar(8),GETDATE(),112),1,4) ", "");
                sbSql.AppendFormat("AND CMONTH = SUBSTRING(Convert(varchar(8),GETDATE(),112),5,2) ", "");
                sbSql.AppendFormat("AND CDAY = SUBSTRING(Convert(varchar(8),GETDATE(),112),7,2) ", "");

                try
                {
                    //Serno = this.objSQLAccess.GetFieldValue(strSQL).ToString();
                    //ControlHandleDB();
                    SqlAccess sqlAccess = new SqlAccess(CommonInfo.Instance.DBCode);
                    Serno = sqlAccess.GetFieldValue(sbSql.ToString());
                    sqlAccess.CloseConnection();

                    if (Serno.Length < 3)
                    {
                        //前面加兩碼0
                        Grrno = Convert.ToString("00") + Serno;
                    }
                    else
                    {
                        Grrno = Serno;
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return Grrno;
            }


