            /// <summary>
            /// 取得序號
            /// </summary> 
            /// <param name="CTRLID">SMT/FINAL。</param>
            /// <param name="CTRLNM">識別：SimulationDoc(祥天計畫)；AddSimulationDoc(QCI_TH20)。</param>
            /// <returns>
            /// String。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.GetSerno(Ctrlid, Ctrlnm);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////
            public string GetSerno(string Ctrlid, string Ctrlnm)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "GetSerno";
                this.ControlMethodParm = "(" + Ctrlid + "," + Ctrlnm + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                string strDate = "";
                string strSerno = "";
                StringBuilder sbSql = new StringBuilder();

                sbSql.Append("Select CONVERT(varchar(12) , getdate(), 112 )");

                ControlHandleDB();
                strDate = ControlSqlAccess.GetFieldValue(sbSql.ToString());
                ControlSqlAccess.CloseConnection();

                sbSql.Remove(0, sbSql.Length);
                sbSql.Append("Select SERNO FROM SERNUM where  ");
                sbSql.AppendFormat("SYSNAM='QWMS' ", "");
                sbSql.AppendFormat("AND SERNAM='{0}' ", Ctrlid);
                sbSql.AppendFormat("AND SERIID='{0}' ", Ctrlnm);
                sbSql.AppendFormat("AND CYEAR='{0}' ", strDate.Substring(0, 4));
                //sbSql.AppendFormat("AND CMONTH='{0}' ", strDate.Substring(4,2));
                //sbSql.AppendFormat("AND CDAY='{0}' ", strDate.Substring(6,2));

                //By廠區取得虛擬單據的流水號(累加SMT & FINAL的流水號直到隔年)  by Smose Liao 20100907
                sbSql.AppendFormat("AND CMONTH='01' ", "");
                sbSql.AppendFormat("AND CDAY='01' ", "");

                try
                {
                    ControlHandleDB();
                    strSerno = ControlSqlAccess.GetFieldValue(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return strSerno;
            }
