            /// <summary>
            /// 查詢WHDNW的虛擬單據資料(透過Group id)
            /// </summary> 
            /// <param name="varOutType">SMT/FINAL。</param>
            /// <param name="varGrpid">Group id。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QuerySimulationData(varOutType,varGrpid);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////////
            public DataTable QuerySimulationData(string varOutType, string varGrpid)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QuerySimulationData";
                this.ControlMethodParm = "(" + varOutType + "," + varGrpid + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhdwn objWhdwn = new DataWhdwn(UserData);
                StringBuilder sbSql = new StringBuilder();
                string strFromTable = string.Empty;
                string strOderBy = "";

                alColumns.Add("*");
                strFromTable = "WHDWN inner join WHPAT on WHDWN.MATNR = WHPAT.MATNR ";
                alConditions.Add("(MANDT= '" + MANDT + "')");
                alConditions.Add("(COMCD= '" + COMCD + "')");
                alConditions.Add("(WERKS= '" + WERKS + "')");
                alConditions.Add("(LGORT= '" + LGORT + "')");
                alConditions.Add("(INTID= '" + varGrpid + "')");

                switch (varOutType)
                {
                    case "SMT":
                        alConditions.Add("(BWART= '311')");
                        sbSql.Append(objWhdwn.ControlGetQuerySql(strFromTable, alColumns, alConditions, false));
                        strOderBy = "MBLNR, ZEILE, MATNR";
                        break;

                    case "FINAL":
                        alConditions.Add("(BWART= '261')");
                        sbSql.Append(objWhdwn.ControlGetQuerySql(strFromTable, alColumns, alConditions, false));
                        strOderBy = "MBLNR, MATNR, ARBPL";
                        break;
                }

                try
                {
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();

                    if (dtData.Rows.Count > 0)
                    {
                        dtData = CommonInfo.SortDataTable(dtData, strOderBy);
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return dtData;
            }
            #endregion


            #region 查詢WHDNW的虛擬單據資料(透過單據號碼與料號)
            //====================================================================================
            ////////////Summary by Smose Liao 20100303////////////////////////////////////////////
            /// <summary>
            /// 查詢WHDNW的虛擬單據資料(透過單據號碼與料號)
            /// </summary> 
            /// <param name="dtData">DataTable。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QuerySimulationDocData(dtData);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            //////////////////////////////////////////////////////////////////////////////////////
            public DataTable QuerySimulationDocData(DataTable dtData)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QuerySimulationDocData";
                this.ControlMethodParm = "(' ')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                ArrayList arySQL = new ArrayList();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataTable dtQuery = new DataTable();
                DataTable dtReturn = new DataTable();
                DataWhdwn objWhdwn = new DataWhdwn(UserData);
                string strFromTable = string.Empty;

                for (int i = 0; i < dtData.Rows.Count; i++)
                {
                    alColumns.Clear();
                    alConditions.Clear();
                    objWhdwn.ResetField();

                    alColumns.Add("*");
                    strFromTable = "WHDWN inner join WHPAT on WHDWN.MATNR = WHPAT.MATNR ";
                    alConditions.Add("(MANDT= '" + MANDT + "')");
                    alConditions.Add("(COMCD= '" + COMCD + "')");
                    alConditions.Add("(WERKS= '" + (dtData.Rows[i]["WERKS"].ToString()) + "')");
                    alConditions.Add("(WHDWN.MATNR= '" + (dtData.Rows[i]["MATNR"].ToString()) + "')");
                    alConditions.Add("(MBLNR LIKE '" + (dtData.Rows[i]["MBLNR"].ToString()) + "%')");
                    alConditions.Add("(ZEILE= '" + (dtData.Rows[i]["ZEILE"].ToString()) + "')");
                    alConditions.Add("(BWART= '" + (dtData.Rows[i]["BWART"].ToString()) + "')");

                    arySQL.Add(objWhdwn.ControlGetQuerySql(strFromTable, alColumns, alConditions, false));
                }

                try
                {
                    dtReturn = dtData.Clone();
                    dtReturn.Columns.Add("MAKTX");  //料號描述
                    for (int i = 0; i < dtData.Rows.Count; i++)
                    {
                        ControlHandleDB();
                        dtQuery = ControlSqlAccess.GetDataTable(arySQL[i].ToString());
                        ControlSqlAccess.CloseConnection();

                        dtReturn.ImportRow(dtQuery.Rows[0]);
                    }

                    dtReturn = CommonInfo.SortDataTable(dtReturn, "MBLNR, ZEILE, MATNR");
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return dtReturn;
            }
            #endregion


