            ///////////////////////////////////////////////////////////////////////////////////////////
            public DataSet QueryOffLineOutData(string strIsmrg, string strMrgid, DataTable dtOutSource)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryOffLineOutData";
