            #region  離線出庫QueryOffLineOutData(找出離線出庫在庫存中可以出庫的數量, 如strIsmrg為Y則只搜尋有連板編號的資料)(加入限定vendor code的功能)
            //=========================================================================================================
            ////////////Summary by Rock Tzeng//////////////////////////////////////////////////////////////////////////
            /// <summary>
            /// 離線出庫 1.	找出離線出庫在庫存中可以出庫的數量, 如strIsmrg為Y則只搜尋有連板編號的資料2.	DataSet包括: OutSource及Storage兩個Table
            ///加入限定vendor code的功能
            /// </summary> 
            /// <param name="strIsmrg">是否連板入庫。</param>
            /// <param name="strMrgid">連板編號。</param>
            /// <param name="dtOutSource">出庫資料。</param>
            /// <param name="strLifnr">Vendor Code。</param>
            /// <returns>
            /// DataSet。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QueryOffLineOutData(strIsmrg,strMrgid,dtOutSource);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            ////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public DataSet QueryOffLineOutData(string strIsmrg, string strMrgid, DataTable dtOutSource, string strLifnr)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryOffLineOutData";
                this.ControlMethodParm = "(" + strIsmrg + "," + strMrgid + "," + strLifnr + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtStorage = new DataTable();
                DataRow drRow;
                //string strSQL = "";
                string strSqlWhere = "";
                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhitm objWhitm = new DataWhitm(UserData);

                if (strIsmrg == "Y")
                {
                    strSqlWhere = " MRGID <> '' and MRGID= '" + strMrgid + "'";
                }
                else
                {
                    strSqlWhere = " MRGID= ''";
                }

                for (int i = 0; i < dtOutSource.Rows.Count; i++)
                {
                    int intSourceMenge = int.Parse(dtOutSource.Rows[i]["MENGE"].ToString());

                    //strSQL = "Select MANDT, WERKS, LGORT, LOCAT, '" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR, '" + dtOutSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE, MBLNR as OMBLNR, MATNR, INSMK, CHARG, (MENGE-REQTY) as MENGE, 0 as ALQTY, MRGID,'" +
                    //    dtOutSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL, '" + dtOutSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL, '" + dtOutSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP, EBELN, LIFNR, RMAK1, INDAT, KDMAT from WHITM where MANDT= '" + dtOutSource.Rows[i]["MANDT"].ToString() +
                    //    "' and WERKS = '" + dtOutSource.Rows[i]["WERKS"].ToString() + "' and LGORT= '" + dtOutSource.Rows[i]["LGORT"].ToString() + "' and MATNR= '" + dtOutSource.Rows[i]["MATNR"].ToString() + "' and INSMK= '" + dtOutSource.Rows[i]["INSMK"].ToString() + "' and CHARG= '" +
                    //    dtOutSource.Rows[i]["CHARG"].ToString() + "'" + strSqlWhere + "  and LIFNR= '" + strLifnr.Trim() + "'   order by INDAT, LOCAT,CRDAT";
                    alColumns.Clear();
                    alConditions.Clear();
                    objWhitm.ResetField();
                    alColumns.Add(" MANDT, COMCD,WERKS, LGORT, LOCAT, '" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR, '" + dtOutSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE, MBLNR as OMBLNR, MATNR, INSMK, CHARG, (MENGE-REQTY) as MENGE, 0 as ALQTY, MRGID");
                    alColumns.Add(" '" + dtOutSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL, '" + dtOutSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL, '" + dtOutSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP, EBELN, LIFNR, RMAK1, INDAT, KDMAT,DACOD, ExpiryDate AS EXPDAT, TASKID ");
                    alConditions.Add(" MANDT = '" + dtOutSource.Rows[i]["MANDT"].ToString() + "'");
                    alConditions.Add(" COMCD = '" + dtOutSource.Rows[i]["COMCD"].ToString() + "'");
                    alConditions.Add(" WERKS = '" + dtOutSource.Rows[i]["WERKS"].ToString() + "'");
                    alConditions.Add(" LGORT = '" + dtOutSource.Rows[i]["LGORT"].ToString() + "'");
                    alConditions.Add(" MATNR = '" + dtOutSource.Rows[i]["MATNR"].ToString() + "'");
                    alConditions.Add(" INSMK = '" + dtOutSource.Rows[i]["INSMK"].ToString() + "'");
                    alConditions.Add(" CHARG = '" + dtOutSource.Rows[i]["CHARG"].ToString() + "'");
                    alConditions.Add(" LIFNR = '" + strLifnr.Trim() + "'");
                    alConditions.Add(" " + strSqlWhere + " order by DACOD,INDAT, LOCAT,CRDAT");

                    try
                    {
                        dtData = objWhitm.EntityQuery(alColumns, alConditions, false);
                    }
                    catch (CommonObjectsException ex)
                    {
                        //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                        ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                        ControlExceptionType = ex.SourceExceptionType;
                        this.ControlPriority = "1";
                        ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                        throw ex;
                    }//可自行增加要handle的Exception  
                    catch (Exception ex)
                    {
                        ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                        ControlExceptionType = ex.GetType().FullName;
                        this.ControlPriority = "1";
                        ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                        throw new Exception("999");
                    }

                    int intLocatMenge = 0;

                    if (i == 0)
                    {
                        dtStorage = dtData.Clone();
                    }

                    for (int j = 0; j < dtData.Rows.Count; j++)
                    {
                        if (intLocatMenge + int.Parse(dtData.Rows[j]["MENGE"].ToString()) <= intSourceMenge)
                        {
                            intLocatMenge += int.Parse(dtData.Rows[j]["MENGE"].ToString());
                            dtData.Rows[j]["ALQTY"] = dtData.Rows[j]["MENGE"].ToString();
                        }
                        else
                        {
                            dtData.Rows[j]["ALQTY"] = intSourceMenge - intLocatMenge;
                            intLocatMenge += intSourceMenge - intLocatMenge;
                        }
                        if (dtData.Rows[j]["ALQTY"].ToString() != "0")
                        {
                            drRow = dtStorage.NewRow();
                            drRow["MANDT"] = dtData.Rows[j]["MANDT"].ToString();
                            drRow["COMCD"] = dtData.Rows[j]["COMCD"].ToString();
                            drRow["WERKS"] = dtData.Rows[j]["WERKS"].ToString();
                            drRow["LGORT"] = dtData.Rows[j]["LGORT"].ToString();
                            drRow["LOCAT"] = dtData.Rows[j]["LOCAT"].ToString();
                            drRow["MATNR"] = dtData.Rows[j]["MATNR"].ToString();
                            drRow["INSMK"] = dtData.Rows[j]["INSMK"].ToString();
                            drRow["CHARG"] = dtData.Rows[j]["CHARG"].ToString();
                            drRow["MENGE"] = dtData.Rows[j]["MENGE"].ToString();
                            drRow["ALQTY"] = dtData.Rows[j]["ALQTY"].ToString();
                            drRow["MBLNR"] = dtData.Rows[j]["MBLNR"].ToString();
                            drRow["ZEILE"] = dtData.Rows[j]["ZEILE"].ToString();
                            drRow["EBELN"] = dtData.Rows[j]["EBELN"].ToString();
                            drRow["LIFNR"] = dtData.Rows[j]["LIFNR"].ToString();
                            drRow["OMBLNR"] = dtData.Rows[j]["OMBLNR"].ToString();
                            drRow["MRGID"] = dtData.Rows[j]["MRGID"].ToString();
                            drRow["KOSTL"] = dtData.Rows[j]["KOSTL"].ToString();
                            drRow["ARBPL"] = dtData.Rows[j]["ARBPL"].ToString();
                            drRow["TRNTP"] = dtData.Rows[j]["TRNTP"].ToString();
                            drRow["RMAK1"] = dtData.Rows[j]["RMAK1"].ToString();
                            drRow["INDAT"] = dtData.Rows[j]["INDAT"].ToString();
                            drRow["KDMAT"] = dtData.Rows[j]["KDMAT"].ToString();
                            drRow["DACOD"] = dtData.Rows[j]["DACOD"].ToString();
                            drRow["EXPDAT"] = dtData.Rows[j]["EXPDAT"].ToString();
                            drRow["TASKID"] = dtData.Rows[j]["TASKID"].ToString();
                            dtStorage.Rows.Add(drRow);
                        }
                    }
                    dtOutSource.Rows[i]["ALQTY"] = intLocatMenge;
                }

                DataSet dsData = new DataSet();
                DataTable dtData1;
                DataTable dtData2;
                dtData1 = dtOutSource.Copy();
                dtData2 = dtStorage.Copy();
                dtData1.TableName = "Source";
                dtData2.TableName = "Destination";
                dsData.Tables.Add(dtData1);
                dsData.Tables.Add(dtData2);
                return dsData;
            }

            #endregion


