                            "from WHSTG inner join WHHED on WHSTG.MANDT=WHHED.MANDT and WHSTG.COMCD=WHHED.COMCD and WHSTG.WERKS = WHHED.WERKS and WHSTG.LGORT = WHHED.LGORT and WHSTG.STSET = WHHED.STSET " +
                            "where WHHED.MANDT='" + MANDT + "' and WHHED.COMCD='" + COMCD + "' and WHHED.WERKS='" + WERKS + "' and WHHED.LGORT='" + strLgort + "' and WHHED.STSET='" + strStset + "'  and WHHED.STHGH='" + strSthgh + "'";

