            #region Query Storage Status Detail Data ,Add by Bruce Zhang
            /// <summary>
            /// </summary> 
            /// <param name="strInsmk"></param>
            /// <param name="strMatnr"></param>
            /// <param name="strInsmk"></param>
            /// <param name="strIsmrg"></param>
            /// <returns>
