            /////////////////////////////////////////////////////////////////////////////
            public DataTable QueryStorageDetailData(string strLocat, string strStset, string strSthgh, string strStlen, string strStwid)
            {
                //偞隅猁??Error Message腔眈燊?洘息
                this.ControlMethodName = "QueryStorageDetailData";
                this.ControlMethodParm = "('" + strLocat + "','" + strStset + "','" + strSthgh + "','" + strStlen + "','" + strStwid + "')";
                if (ControlTraceCode == "T") //猁??網請森WebMethod腔log...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    string strSQL = "";
                    if (strLocat != "")
                    {
                        strSQL = "Select WHHED.MANDT, WHHED.COMCD, WHHED.WERKS, WHHED.LGORT, WHHED.LOCAT, WHHED.STSET, WHHED.STHGH, WHHED.STLEN, WHHED.STWID, " +
                            "(Select isnull(sum(MENGE),0) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT and MRGID='' ) as MENGE1, " +
                            "(Select isnull(sum(MENGE),0) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT and MRGID<>'' ) as MENGE2, " +
                            "(Select isnull(sum(MENGE),0) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT ) as MENGE, " +
                            "(Select min(INDAT) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT) as OINDAT, " +
                            "(Select max(INDAT) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT) as NINDAT " +
                            "from WHHED where MANDT='" + MANDT + "' and COMCD='" + COMCD + "' and WERKS='" + WERKS + "' and LGORT= '" + LGORT + "'  and LOCAT='" + strLocat + "'";
                    }
                    else
                    {
                        strSQL = "Select WHHED.MANDT, WHHED.COMCD, WHHED.WERKS, WHHED.LGORT, WHHED.LOCAT, WHHED.STSET, WHHED.STHGH, WHHED.STLEN, WHHED.STWID, " +
                            "(Select isnull(sum(MENGE),0) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT and MRGID='' ) as MENGE1, " +
                            "(Select isnull(sum(MENGE),0) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT and MRGID<>'' ) as MENGE2, " +
                            "(Select isnull(sum(MENGE),0) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT ) as MENGE, " +
                            "(Select min(INDAT) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT) as OINDAT, " +
                            "(Select max(INDAT) from WHITM where MANDT=WHHED.MANDT AND COMCD=WHHED.COMCD and WERKS=WHHED.WERKS and LGORT=WHHED.LGORT and LOCAT=WHHED.LOCAT) as NINDAT " +
                            "from WHHED where MANDT='" + MANDT + "' and COMCD='" + COMCD + "' and WERKS='" + WERKS + "' and LGORT= '" + LGORT + "'  and STSET='" + strStset + "'  and STHGH='" + strSthgh + "'  and STLEN='" + strStlen + "'  and STWID='" + strStwid + "'";
                    }
                    DataTable dtData = new DataTable();
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();
                    return dtData;
                }
                catch (CommonObjectsException ex)
                {
                    //莮Common Object腔淩淏嶒悷?洘ㄛ瞰ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//褫赻俴崝樓猁handle腔Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
