            /// <summary>
            /// 檢查WHECD 的Key是否已經存在, 作為Update或Insert的依據
            /// </summary> 
            /// <param name="strLocat">儲位。</param>
            /// <param name="strMatnr">料號。</param>
            /// <returns>
            /// bool。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  bool  bolReturn = objStorageData.QueryDataExistsInWhecd(string strLocat, string strMatnr);
            ///  Your Code Here......
