            public bool QueryDataExistsInWhecd(string strLgort, string strLocat, string strMatnr, string strQctyp, string strVbeln)
            {

                bool bolDay = false;
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryDataExistsInWhecd";
                this.ControlMethodParm = "(" + strLocat + "," + strMatnr + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataWhecd objWhecd = new DataWhecd(UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alQueryConditions = new ArrayList();

                alColumns.Add("*");
                alQueryConditions.Add("MANDT = '" + UserData.Client + "'");
                alQueryConditions.Add("COMCD = '" + UserData.CompanyCode + "'");
                alQueryConditions.Add("WERKS = '" + WERKS + "'");
                alQueryConditions.Add("LGORT = '" + strLgort + "'");
                alQueryConditions.Add("LOCAT = '" + strLocat + "'");
                alQueryConditions.Add("MATNR = '" + strMatnr + "'");
                alQueryConditions.Add("QCTYP = '" + strQctyp + "'");
                alQueryConditions.Add("VBELN = '" + strVbeln + "'");
                DataTable dtData = new DataTable();
                try
                {
                    dtData = objWhecd.EntityQuery(alColumns, alQueryConditions, false, true);
                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryDataExistsInWhecd()";
                }

                if (dtData.Rows.Count > 0)
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }

