            /// <summary>
            /// 查詢庫存比對資料
            /// </summary> 
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objStorageData.QueryContrastData("G", true);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////
            public DataTable QueryContrastData(string strInsmk, bool bolSkipCharg)
            {
                string strTempInsmk = "";
                string strTempInsmk1 = "";
                if (strInsmk.Trim() != "")
                {
                    strTempInsmk = " and WHCST.INSMK='" + strInsmk + "'";
                    strTempInsmk1 = " and WHITM.INSMK='" + strInsmk + "'";
                }
                string strSQL = "";
                if (bolSkipCharg == false)
                {

                    strSQL = "select * from ( " +
                        "select WHCST.MANDT,WHCST.COMCD, WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.CHARG, WHCST.INSMK, WHCST.MENGE as SAP_MENGE, isnull(QWMS.MENGE,0) as QWMS_MENGE, (WHCST.MENGE-isnull(QWMS.MENGE,0)) as KTMNG " +
                        "from WHCST inner join  " +
                        "( " +
                        "select MANDT,COMCD, WERKS, LGORT, MATNR, CHARG, INSMK, sum(MENGE) as MENGE from WHITM where MANDT='" + MANDT + "' and COMCD='" + COMCD + "'and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' " +
                        "group by  MANDT, COMCD,WERKS, LGORT, MATNR, CHARG, INSMK " +
                        ") as QWMS on WHCST.MANDT=QWMS.MANDT and WHCST.COMCD=QWMS.COMCD and WHCST.WERKS=QWMS.WERKS and WHCST.LGORT=QWMS.LGORT and WHCST.MATNR=QWMS.MATNR and WHCST.INSMK=QWMS.INSMK and WHCST.CHARG=QWMS.CHARG   " +
                        "where WHCST.MANDT='" + MANDT + "' and WHCST.COMCD='" + COMCD + "' and WHCST.WERKS='" + strWerks + "' and WHCST.LGORT='" + strLgort + "' and WHCST.MENGE-isnull(QWMS.MENGE,0)<>0" + strTempInsmk + " " +
                        "union " +
                        "select WHITM.MANDT,WHITM.COMCD, WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.CHARG, WHITM.INSMK, 0 as SAP_MENGE, sum(WHITM.MENGE) as QWMS_MENGE, 0-sum(WHITM.MENGE) as KTMNG " +
                        "from WHITM where MANDT='" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS='" + strWerks + "' and LGORT='" + strLgort + "'" + strTempInsmk1 + " and not exists (select * from WHCST where MANDT=WHITM.MANDT  and COMCD=WHITM.COMCD and WERKS=WHITM.WERKS and LGORT=WHITM.LGORT and MATNR=WHITM.MATNR and INSMK=WHITM.INSMK and CHARG=WHITM.CHARG)  group by MANDT, COMCD,WERKS, LGORT, MATNR, INSMK, CHARG " +
                        "union " +
                        "select WHCST.MANDT, WHCST.COMCD, WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.CHARG, WHCST.INSMK, MENGE as SAP_MENGE, 0  as QWMS_MENGE, MENGE as KTMNG " +
                        "from WHCST where MANDT='" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' and MENGE <>0" + strTempInsmk + " and not exists (select MANDT, COMCD,WERKS, LGORT, MATNR, INSMK, CHARG, sum(MENGE) as MENGE from WHITM where MANDT=WHCST.MANDT and COMCD=WHCST.COMCD and WERKS=WHCST.WERKS and LGORT=WHCST.LGORT and MATNR=WHCST.MATNR and INSMK=WHCST.INSMK and CHARG=WHCST.CHARG  group by MANDT, COMCD,WERKS, LGORT, MATNR, INSMK, CHARG) " +
                        ") as T " +
                        "order by MANDT, COMCD,WERKS, LGORT, MATNR, CHARG, INSMK";


                }
                else
                {
                    strSQL = "select * from ( " +
                        "select WHCST.MANDT, WHCST.COMCD,WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.CHARG, WHCST.INSMK, WHCST.MENGE as SAP_MENGE, isnull(QWMS.MENGE,0) as QWMS_MENGE, (WHCST.MENGE-isnull(QWMS.MENGE,0)) as KTMNG " +
                        "from (select MANDT, COMCD,WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE from WHCST where MANDT='" + MANDT + "' and COMCD='" + COMCD + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' group by  MANDT, COMCD,WERKS, LGORT, MATNR,  INSMK) as WHCST inner join " +
                        "( " +
                        "select MANDT, COMCD,WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE from WHITM where MANDT='" + MANDT + "' and COMCD='" + COMCD + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' " +
                        "group by  MANDT, COMCD,WERKS, LGORT, MATNR,  INSMK " +
                        ") as QWMS on WHCST.MANDT=QWMS.MANDT AND WHCST.COMCD=QWMS.COMCD  and WHCST.WERKS=QWMS.WERKS and WHCST.LGORT=QWMS.LGORT and WHCST.MATNR=QWMS.MATNR and WHCST.INSMK=QWMS.INSMK and WHCST.CHARG=QWMS.CHARG   " +
                        "where WHCST.MANDT='" + MANDT + "' AND WHCST.COMCD='" + COMCD + "' and WHCST.WERKS='" + strWerks + "' and WHCST.LGORT='" + strLgort + "' and WHCST.MENGE-isnull(QWMS.MENGE,0)<>0" + strTempInsmk + " " +
                        "union " +
                        "select WHITM.MANDT, WHITM.COMCD,WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.CHARG, WHITM.INSMK, 0 as SAP_MENGE, sum(WHITM.MENGE) as QWMS_MENGE, 0-sum(WHITM.MENGE) as KTMNG " +
                        "from (select MANDT, COMCD,WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE from WHITM where MANDT='" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' group by  MANDT, COMCD,WERKS, LGORT, MATNR,  INSMK) as WHITM where MANDT='" + MANDT + "' and COMCD='" + COMCD + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "'" + strTempInsmk1 + " and not exists (select MANDT, COMCD,WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE  from WHCST where MANDT=WHITM.MANDT AND COMCD=WHITM.COMCD and WERKS=WHITM.WERKS and LGORT=WHITM.LGORT and MATNR=WHITM.MATNR and INSMK=WHITM.INSMK  group by WHCST.MANDT, WHCST.COMCD,WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.INSMK )  group by MANDT, COMCD,WERKS, LGORT, MATNR, INSMK, CHARG " +
                        "union " +
                        "select WHCST.MANDT,WHCST.COMCD, WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.CHARG, WHCST.INSMK, MENGE as SAP_MENGE, 0  as QWMS_MENGE, MENGE as KTMNG " +
                        "from (select MANDT, COMCD,WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE from WHCST where MANDT='" + MANDT + "' AND COMCD='" + COMCD + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' group by  MANDT, COMCD,WERKS, LGORT, MATNR,  INSMK) as WHCST where MANDT='" + MANDT + "' and COMCD='" + COMCD + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' and MENGE <>0" + strTempInsmk + " and not exists (select MANDT, COMCD,WERKS, LGORT, MATNR, INSMK, '' as CHARG, sum(MENGE) as MENGE from WHITM where MANDT=WHCST.MANDT AND COMCD=WHCST.COMCD and WERKS=WHCST.WERKS and LGORT=WHCST.LGORT and MATNR=WHCST.MATNR and INSMK=WHCST.INSMK   group by WHITM.MANDT, WHITM.COMCD,WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.INSMK) " +
                        ") as T " +
                        "order by MANDT, COMCD,WERKS, LGORT, MATNR, CHARG, INSMK";

                }

                DataTable dtData = new DataTable();
                try
                {
                    ControlHandleDB();
                    ControlSqlAccess.CommandTimeOut = 120;
                    dtData = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();
                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryContrastData()";
                    throw new Exception(ERRMSG);
                }
                return dtData;
