                        "union " +
                        "select WHITM.MANDT, WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.CHARG, WHITM.INSMK, 0 as SAP_MENGE, sum(WHITM.MENGE) as QWMS_MENGE, 0-sum(WHITM.MENGE) as KTMNG, MTYPE ='" + strMType + "' " +
                        "from WHITM where MANDT='" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "'" + strTempInsmk1 + " and not exists (select * from WHCST where MANDT=WHITM.MANDT and WERKS=WHITM.WERKS and LGORT=WHITM.LGORT and MATNR=WHITM.MATNR and INSMK=WHITM.INSMK and CHARG=WHITM.CHARG " + strTempMType + ")  group by MANDT, WERKS, LGORT, MATNR, INSMK, CHARG " +
                        "union " +
                        "select WHCST.MANDT, WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.CHARG, WHCST.INSMK, MENGE as SAP_MENGE, 0  as QWMS_MENGE, MENGE as KTMNG, WHCST.MTYPE " +
                        "from WHCST where MANDT='" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' and MENGE <>0" + strTempInsmk + strTempMType + " and not exists (select MANDT, WERKS, LGORT, MATNR, INSMK, CHARG, sum(MENGE) as MENGE from WHITM where MANDT=WHCST.MANDT and WERKS=WHCST.WERKS and LGORT=WHCST.LGORT and MATNR=WHCST.MATNR and INSMK=WHCST.INSMK and CHARG=WHCST.CHARG  group by MANDT, WERKS, LGORT, MATNR, INSMK, CHARG) " +
                        ") as T " +
                        "Where MTYPE = '" + strMType + "'" +
                        "order by MANDT, WERKS, LGORT, MATNR, CHARG, INSMK";
                }
                else
                {
                    strSQL = "select * from ( " +
                        "select WHCST.MANDT, WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.CHARG, WHCST.INSMK, WHCST.MENGE as SAP_MENGE, isnull(QWMS.MENGE,0) as QWMS_MENGE, (WHCST.MENGE-isnull(QWMS.MENGE,0)) as KTMNG " +
                        "from (select MANDT, WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE from WHCST where MANDT='" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' " + strTempMType + " group by  MANDT, WERKS, LGORT, MATNR,  INSMK) as WHCST inner join " +
                        "( " +
