                        "group by  MANDT, WERKS, LGORT, MATNR,  INSMK " +
                        ") as QWMS on WHCST.MANDT=QWMS.MANDT and WHCST.WERKS=QWMS.WERKS and WHCST.LGORT=QWMS.LGORT and WHCST.MATNR=QWMS.MATNR and WHCST.INSMK=QWMS.INSMK and WHCST.CHARG=QWMS.CHARG   " +
                        "where WHCST.MANDT='" + UserData.Client + "' and WHCST.COMCD = '" + UserData.CompanyCode + "' and WHCST.WERKS='" + strWerks + "' and WHCST.LGORT='" + strLgort + "' and WHCST.MENGE-isnull(QWMS.MENGE,0)<>0" + strTempInsmk + " " +
                        "union " +
                        "select WHITM.MANDT, WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.CHARG, WHITM.INSMK, 0 as SAP_MENGE, sum(WHITM.MENGE) as QWMS_MENGE, 0-sum(WHITM.MENGE) as KTMNG " +
                        "from (select MANDT, WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE from WHITM where MANDT='" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' group by  MANDT, WERKS, LGORT, MATNR,  INSMK) as WHITM where MANDT='" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "'" + strTempInsmk1 + " and not exists (select MANDT, WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE  from WHCST where MANDT=WHITM.MANDT and WERKS=WHITM.WERKS and LGORT=WHITM.LGORT and MATNR=WHITM.MATNR and INSMK=WHITM.INSMK " + strTempMType + "  group by WHCST.MANDT, WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.INSMK )  group by MANDT, WERKS, LGORT, MATNR, INSMK, CHARG " +
                        "union " +
                        "select WHCST.MANDT, WHCST.WERKS, WHCST.LGORT, WHCST.MATNR, WHCST.CHARG, WHCST.INSMK, MENGE as SAP_MENGE, 0  as QWMS_MENGE, MENGE as KTMNG " +
                        "from (select MANDT, WERKS, LGORT, MATNR, '' as CHARG, INSMK, sum(MENGE) as MENGE from WHCST where MANDT='" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' " + strTempMType + " group by  MANDT, WERKS, LGORT, MATNR,  INSMK) as WHCST where MANDT='" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS='" + strWerks + "' and LGORT='" + strLgort + "' and MENGE <>0" + strTempInsmk + " and not exists (select MANDT, WERKS, LGORT, MATNR, INSMK, '' as CHARG, sum(MENGE) as MENGE from WHITM where MANDT=WHCST.MANDT and WERKS=WHCST.WERKS and LGORT=WHCST.LGORT and MATNR=WHCST.MATNR and INSMK=WHCST.INSMK   group by WHITM.MANDT, WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.INSMK) " +
                        ") as T " +
                        "order by MANDT, WERKS, LGORT, MATNR, CHARG, INSMK";
                }

                DataTable dtData = new DataTable();
                try
                {
                    //DataWhitm objWhitm = new DataWhitm(UserData);
