            /// <summary>
            /// 查詢庫存的日期狀態
            /// </summary> 
            /// <param name="strInsmk">庫別。</param>
            /// <param name="strStartMatnr">開始料號。</param>
            /// <param name="strEndMatnr">結束料號。</param>
            /// <param name="strStartLocat">開始儲位。</param>
            /// <param name="strEndLocat">結束儲位。</param>
            /// <param name="strType1">開始類型(>,=,<)。</param>
            /// <param name="strStartDate">開始日期。</param>
            /// <param name="strComparsion">連結類型(and, or)。</param>
            /// <param name="strType2">結束類型(>,=,<)。</param>
            /// <param name="strEndDate">結束日期。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objStorageData.QueryStorageTimeData(strInsmk,strStartMatnr,strEndMatnr,strStartLocat, strEndLocat, strType1, strStartDate, strComparsion, strType2, strEndDate);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////
            public DataTable QueryStorageTimeData(string strInsmk, string strStartMatnr, string strEndMatnr, string strStartLocat, string strEndLocat, string strType1, string strStartDate, string strComparsion, string strType2, string strEndDate)
            {
                DataWhitm objWhitm = new DataWhitm(UserData);

                ArrayList alColumns = new ArrayList();
                ArrayList alQueryConditions = new ArrayList();

                alColumns.Add("*");

                alQueryConditions.Add("MANDT = '" + UserData.Client + "'");
                alQueryConditions.Add("COMCD = '" + UserData.CompanyCode + "'");
                alQueryConditions.Add("WERKS = '" + WERKS + "'");
                alQueryConditions.Add("LGORT = '" + LGORT + "'");

                //strSQL = "Select * from WHITM where MANDT= '" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS = '" + WERKS + "' and LGORT= '" + LGORT + "'";

                if (strInsmk != "")
                {
                    //strSQL += " and WHITM.INSMK = '" + strInsmk + "'";
                    alQueryConditions.Add("INSMK = '" + strInsmk + "'");
                }

                if (strStartMatnr != "" && strEndMatnr != "")
                {
                    //strSQL += " and (WHITM.MATNR between '" + strStartMatnr + "' and '" + strEndMatnr + "')";
                    alQueryConditions.Add("(WHITM.MATNR between '" + strStartMatnr + "' and '" + strEndMatnr + "')");
                }
                else if (strStartMatnr == "" && strEndMatnr != "")
                {
                    //strSQL += " and WHITM.MATNR = '" + strEndMatnr + "'";
                    alQueryConditions.Add("MATNR = '" + strEndMatnr + "'");
                }
                else if (strStartMatnr != "" && strEndMatnr == "")
                {
                    //strSQL += " and WHITM.MATNR = '" + strStartMatnr + "'";
                    alQueryConditions.Add("MATNR = '" + strStartMatnr + "'");
                }
                if (strStartLocat != "" && strEndLocat != "")
                {
                    //strSQL += " and (WHITM.LOCAT between '" + strStartLocat + "' and '" + strEndLocat + "')";
                    alQueryConditions.Add("(WHITM.LOCAT between '" + strStartLocat + "' and '" + strEndLocat + "')");
                }
                else if (strStartLocat == "" && strEndLocat != "")
                {
                    //strSQL += " and WHITM.LOCAT = '" + strEndLocat + "'";
                    alQueryConditions.Add("LOCAT = '" + strEndLocat + "'");
                }
                else if (strStartLocat != "" && strEndMatnr == "")
                {
                    //strSQL += " and WHITM.LOCAT = '" + strEndLocat + "'";
                    alQueryConditions.Add("LOCAT = '" + strEndLocat + "'");
                }

                if (strType1 != "" && strStartDate != "")
                {
                    if (strComparsion != "" && strType2 != "" && strEndDate != "")
                    {
                        //strSQL += " and Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", INDAT), 112) " + strComparsion + " Convert(varchar(8), getdate(), 112) " + strType2 + " convert(varchar(8), dateadd(day ," + strEndDate + ", INDAT), 112)";
                        //修改呆料查詢的條件：改成用料號的建立日期(WHITM.CRDAT)當查詢條件  Smose Liao 20100326
                        //alQueryConditions.Add("Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", INDAT), 112) " + strComparsion + " Convert(varchar(8), getdate(), 112) " + strType2 + " convert(varchar(8), dateadd(day ," + strEndDate + ", INDAT), 112)");
                        alQueryConditions.Add("Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", INDAT), 112) " + strComparsion + " Convert(varchar(8), getdate(), 112) " + strType2 + " convert(varchar(8), dateadd(day ," + strEndDate + ", CRDAT), 112)");
                    }
                    else
                    {
                        //strSQL += " and Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", INDAT), 112)";
                        //修改呆料查詢的條件：改成用料號的建立日期(WHITM.CRDAT)當查詢條件  Smose Liao 20100326
                        //alQueryConditions.Add("Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", INDAT), 112)");
                        alQueryConditions.Add("Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", CRDAT), 112)");
                    }
                }

                DataTable dtData = new DataTable();
                try
                {
                    //ControlHandleDB();
                    //dtData = ControlSqlAccess.GetDataTable(strSQL);
                    //ControlSqlAccess.CloseConnection();

                    dtData = objWhitm.EntityQuery(alColumns, alQueryConditions, false, true);
                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryStorageTimeData()";
                }
                return dtData;
            }

