            public DataTable QueryStorageData_DateCode(string strInsmk, string strStartMatnr, string strEndMatnr, string strMaktx, string strLoadID, string strIndat_From, string strIndat_To)
            {
                //string strSQL = "";

                DataWhitm objWhitm = new DataWhitm(UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alQueryCondition = new ArrayList();
                ArrayList alGrouyby = new ArrayList();

                string strFromTable = string.Empty;

