            public DataTable QueryStorageData_DateCode(string strInsmk, string strMatnr, string strIndat_From, string strIndat_To)
            {
                DataWhitm objWhitm = new DataWhitm(UserData);

                ArrayList alColumns = new ArrayList();
                ArrayList alQueryCondition = new ArrayList();

                alColumns.Add("*");
                alColumns.Add("(MENGE+BKQTY) AS NEW_MENGE");

                alQueryCondition.Add("MANDT = '" + UserData.Client + "'");
                alQueryCondition.Add("COMCD = '" + UserData.CompanyCode + "'");
                alQueryCondition.Add("WERKS = '" + WERKS + "'");
                alQueryCondition.Add("LGORT = '" + LGORT + "'");
                alQueryCondition.Add("INSMK = '" + strInsmk + "'");
                alQueryCondition.Add("MATNR = '" + strMatnr + "'");

                //Modify: Support 9700 PDA two step goods issue by Smose Liao 20100324 
                if (COMCD != "9700")
                {
                    alQueryCondition.Add("WHITM.LOCOD <> ''");
                }

                alQueryCondition.Add("WHITM.LOCOD is not null");
                alQueryCondition.Add("(WHITM.INDAT between '" + strIndat_From + "'  and  '" + strIndat_To + "')");


                //string strSQL = "Select *,(MENGE+BKQTY) AS NEW_MENGE from WHITM where MANDT= '" + UserData.Client + "' and COMCD = '" + UserData.CompanyCode + "' and WERKS = '" + WERKS + "' and LGORT = '" + LGORT + "' and INSMK= '" + strInsmk + "' and MATNR = '" + strMatnr + "' and WHITM.LOCOD<>''  and WHITM.LOCOD is not null  and (WHITM.INDAT between '" + strIndat_From + "'  and  '" + strIndat_To + "') ";

                DataTable dtData = new DataTable();
                try
                {
                    string str = objWhitm.EntityGetQuerySql(alColumns, alQueryCondition, false, true);
                    dtData = objWhitm.EntityQuery(alColumns, alQueryCondition, false, true);
                    //ControlHandleDB();
                    //ControlSqlAccess.GetDataTable(strSQL);
                    //ControlSqlAccess.CloseConnection();
                }
                catch (System.Exception ex)
                {
                    //this.objSQLAccess.ErrorMessage = ex.Message + "<- QueryStorageData ";
                    //throw new System.Exception(ex.Message +"<- QueryStorageData " );

                    ERRMSG = ex.Message + "<- QueryStorageData()";
                }
                return dtData;
            }

            #region 查詢倉別庫存資料(Spare Parts)
