            /// <summary>
            /// 查詢倉別庫存資料, 將相同料號的資料Group by在一起strInsmk: 庫別strStartMatnr: 開始料號strEndMatnr: 結束料號
            /// </summary> 
            /// <param name="strStartMatnr">開始料號。</param>
            /// <param name="strEndMatnr">結束料號。</param>
            /// <param name="strEbeln">PO No.。</param>
            /// <param name="strSidno">SI No.。</param>
            /// <param name="strKdmat">客人料號。</param>
            /// <param name="strNloca">待出貨儲位。</param>
            /// <param name="strRmano">RMA No.。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objStorageData.QueryStorageData_SpareParts(strStartMatnr,strEndMatnr, strEbeln, strSino, strKdmat, strNloca, strRmano);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            //////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public DataTable QueryStorageData_SpareParts(string strStartMatnr, string strEndMatnr, string strEbeln, string strSidno, string strKdmat, string strNloca, string strRmano)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryStorageData_SpareParts";
                this.ControlMethodParm = "('" + strStartMatnr + "','" + strEndMatnr + "','" + strEbeln + "','" + strSidno + "','" + strKdmat + "','" + strNloca + "')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    StringBuilder sbSql = new StringBuilder();
                    DataTable dtData = new DataTable();

                    sbSql.Append("Select MANDT, WERKS, LGORT, MATNR, EBELN, KDMAT, INSMK, sum(MENGE) as MENGE, sum(REQTY) as REQTY, count(*) as TOTAL, MIN(INDAT) as INDAT, (select count(distinct LOCAT) from WHITM as A With(Nolock) where A.MANDT=WHITM.MANDT and A.COMCD=WHITM.COMCD and A.WERKS=WHITM.WERKS and A.LGORT=WHITM.LGORT and A.MATNR=WHITM.MATNR and A.INSMK=WHITM.INSMK) as TOLOC, (select count(distinct LOCAT) from WHITM  as A With(Nolock) where A.MANDT=WHITM.MANDT and A.COMCD=WHITM.COMCD and A.WERKS=WHITM.WERKS and A.LGORT=WHITM.LGORT and A.MATNR=WHITM.MATNR and A.INSMK=WHITM.INSMK and MRGID<>'') as MILOC")
                        .AppendFormat(" from WHITM With(Nolock) where MANDT= '{0}' and COMCD = '{1}' and WERKS = '{2}' and LGORT= '{3}'", MANDT, COMCD, WERKS, LGORT);

                    if (strStartMatnr != "" && strEndMatnr != "")
                    {
                        sbSql.AppendFormat(" and ((WHITM.MATNR like '{0}%') or (WHITM.MATNR between '{1}%' and '{2}%'))", strStartMatnr, strStartMatnr, strEndMatnr);
                    }
                    else if (strStartMatnr == "" && strEndMatnr != "")
                    {
                        sbSql.AppendFormat(" and WHITM.MATNR like '{0}%'", strEndMatnr);
                    }
                    else if (strStartMatnr != "" && strEndMatnr == "")
                    {
                        sbSql.AppendFormat(" and WHITM.MATNR like '{0}%'", strStartMatnr);
                    }

                    if (strEbeln != "")
                    {
                        sbSql.AppendFormat(" and WHITM.EBELN = '{0}'", strEbeln);
                    }

                    if (strKdmat != "")
                    {
                        sbSql.AppendFormat(" and WHITM.KDMAT = '{0}'", strKdmat);
                    }

                    if (strSidno != "")
                    {
                        sbSql.AppendFormat(" and WHITM.SIDNO like '%{0}%'", strSidno);
                    }

                    if (strNloca != "")
                    {
                        sbSql.AppendFormat(" and WHITM.NLOCA = '{0}'", strNloca);
                    }

                    if (strRmano != "")
                    {
                        sbSql.AppendFormat(" and WHITM.RMANO = '{0}'", strRmano);
                    }

                    if (strSidno.Trim() != "")
                    {
                        string strTmpSidno = "";
                        string[] ArrSidno = strSidno.Split(',');
                        for (int i = 0; i < ArrSidno.Length; i++)
                        {
                            if (strTmpSidno.Trim() != "")
                                strTmpSidno += " OR ";
                            strTmpSidno += " MBLNR like '" + ArrSidno[i] + "%' ";
                        }

                        sbSql.AppendFormat(" and exists (select * from whdwn where mtype = 'SAP_SI' and mandt = whitm.mandt and comcd = whitm.comcd and werks = whitm.werks and lgort = whitm.lgort and matnr = whitm.matnr and insmk = whitm.insmk and charg = whitm.charg and ({0}))", strTmpSidno);
                    }

                    sbSql.Append(" group by WHITM.MANDT, WHITM.COMCD, WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.EBELN, WHITM.KDMAT, WHITM.INSMK ");

                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();
                    return dtData;
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }

