            /// <summary>
            ///  腕踱湔訧蹋
            /// </summary> 
            /// <param name="strInsmk"></param>
            /// <param name="strStartLocat"></param>
            /// <param name="strEndLocat"></param>
            /// <param name="strStartMatnr"></param>
            /// <param name="strEndMatnr"></param>
            /// <param name="strStartDate"></param>
            /// <param name="strEndDate"></param>
            /// <param name="strCharg"></param>
            /// <param name="strMblnr"></param>
            /// <param name="strIsmrg"></param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.Counting objCounting =new QCI.QWMS.Counting(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objCounting.QueryStorageCheckDetailData(strInsmk,strStartLocat,strEndLocat,strStartMatnr,strEndMatnr,strStartDate,strEndDate,strCharg,strMblnr,strIsmrg);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////
            public DataTable QueryStorageCheckDetailData(string strInsmk, string strStartLocat, string strEndLocat, string strStartMatnr, string strEndMatnr, string strStartDate, string strEndDate, string strCharg, string strMblnr, string strIsmrg)
            {
                //偞隅猁??Error Message腔眈燊?洘息
                this.ControlMethodName = "QueryStorageCheckDetailData";
                this.ControlMethodParm = "('" + strInsmk + "','" + strStartLocat + "','" + strEndLocat + "','" + strStartMatnr + "','" + strEndMatnr + "','" + strStartDate + "','" + strEndDate + "','" + strCharg + "','" + strMblnr + "','" + strIsmrg + "')";
                if (ControlTraceCode == "T") //猁??網請森WebMethod腔log...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {

                    StringBuilder sbSql = new StringBuilder();

                    //string strSQL = "Select * from WHITM where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "'";
                    sbSql.AppendFormat(" Select * from WHITM where MANDT= '{0}' and COMCD='{1}' and WERKS= '{2}' and LGORT= '{3}'", MANDT, COMCD, WERKS, LGORT);
                    if (strInsmk != "")
                    {
                        //strSQL += " and INSMK= '" + strInsmk + "'";
                        sbSql.AppendFormat(" and INSMK='{0}' ", strInsmk);
                    }

                    if (strCharg != "")
                    {
                        //strSQL += " and CHARG = '" + strCharg + "'";
                        sbSql.AppendFormat(" and CHARG='{0}' ", strCharg);
                    }

                    if (strMblnr != "")
                    {
                        //strSQL += " and MBLNR= '" + strMblnr + "'";
                        sbSql.AppendFormat(" and MBLNR= '{0}'", strMblnr);
                    }

                    if (strStartLocat != "" && strEndLocat != "")
                    {
                        //strSQL += " and (LOCAT between '" + strStartLocat + "' and '" + strEndLocat + "')";
                        sbSql.AppendFormat(" and (LOCAT between '{0}' and '{1}')", strStartLocat, strEndLocat);
                    }
                    else if (strStartLocat == "" && strEndLocat != "")
                    {
                        //strSQL += " and LOCAT = '" + strEndLocat + "'";
                        sbSql.AppendFormat(" and LOCAT ='{0}'", strEndLocat);
                    }
                    else if (strStartLocat != "" && strEndLocat == "")
                    {
                        //strSQL += " and LOCAT = '" + strStartLocat + "'";
                        sbSql.AppendFormat(" and LOCAT ='{0}'", strStartLocat);
                    }

                    if (strStartMatnr != "" && strEndMatnr != "")
                    {
                        //strSQL += " and (MATNR between '" + strStartMatnr + "' and '" + strEndMatnr + "')";
                        sbSql.AppendFormat(" and (MATNR between '{0}' and '{1}')", strStartMatnr, strEndMatnr);
                    }
                    else if (strStartMatnr == "" && strEndMatnr != "")
                    {
                        //strSQL += " and MATNR = '" + strEndMatnr + "'";
                        sbSql.AppendFormat(" and MATNR = '{0}'", strEndMatnr);
                    }
                    else if (strStartMatnr != "" && strEndMatnr == "")
                    {
                        //strSQL += " and MATNR = '" + strStartMatnr + "'";
                        sbSql.AppendFormat(" and MATNR = '{0}'", strStartMatnr);
                    }

                    if (strStartDate != "" && strEndDate != "")
                    {
                        //strSQL += " and (CRDAT between '" + strStartDate + "' and '" + strEndDate + "')";
                        sbSql.AppendFormat(" and (CRDAT between '{0}' and '{1}')", strStartDate, strEndDate);
                    }
                    else if (strStartDate == "" && strEndDate != "")
                    {
                        //strSQL += " and CRDAT = '" + strEndDate + "'";
                        sbSql.AppendFormat(" and CRDAT = '{0}'", strEndDate);
                    }
                    else if (strStartDate != "" && strEndDate == "")
                    {
                        //strSQL += " and CRDAT = '" + strStartDate + "'";
                        sbSql.AppendFormat(" and CRDAT = '{0}'", strStartDate);
                    }

                    if (strIsmrg != "")
                    {
                        if (strIsmrg == "Y")
                        {
                            //strSQL += " and MRGID <> ''";
                            sbSql.Append(" and MRGID <> ''");
                        }
                        else
                        {

                            //strSQL += "";
                            sbSql.Append("");
                        }
                    }
                    DataTable dtData = new DataTable();
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();

                    return dtData;
                }
                catch (CommonObjectsException ex)
                {
                    //莮Common Object腔淩淏嶒悷?洘ㄛ瞰ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//褫赻俴崝樓猁handle腔Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
            #endregion


