            #region 連線出庫(查詢庫存並算出出庫狀況) by Brian Zhao
            //=====================================================================================
            ////////////Summary by Marc Hong/////////////////////////////////////////////
            /// <summary> 
            /// 加入"指定Rmano欄位" 連線出庫 
            /// 1.	找出連線出庫在庫存中可以出庫的數量, 不帶出連板料號
            /// 2.	DataSet包括: OutSource及Storage兩個Table
            /// </summary> 
            /// <param name="dtOutSource">出庫資料。</param>
            /// <param name="varLifnr">指定Vendor Code。</param>
            /// <param name="varRmano">指定RMA No。</param>
            /// <param name="varByDateCode">是否要ByDateCode作先進先出出庫。</param>
            /// <param name="varMrgid">連板出庫的模組編號。</param>
            /// <param name="varByPallet">是否要Pallet出庫(成品)。</param>
            /// <param name="varBySerno">是否要Serial No出庫(成品)。</param>
            /// <returns>
            /// DataSet。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QueryOnLineOutData(dtOutSource, txtLifnr, txtRmano);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////
            public DataSet GetOnLineOutData(DataTable dtDwnSource, string varLifnr, string varRmano, bool varByDateCode, string varMrgid, bool varByPallet, bool varBySerno)
            {
                DataSet dsResult = new DataSet();
                try
                {
                    DataTable dtOutWhitm = new DataTable();//要出庫的庫存數據

                    DataRow drRow;
                    //string strSQL = "";
                    //int intLocatHaveOutQty = 0;
                    DataRow[] drFound;
                    DataRow[] drFound1;

                    DataWhitm objWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    DataTable dtWhitm = new DataTable();

                    for (int i = 0; i < dtDwnSource.Rows.Count; i++)
                    {
                        //出庫單據的數量
                        int intSourceMenge = int.Parse(dtDwnSource.Rows[i]["ALMNG"].ToString());

                        #region 找出符合條件且可出庫的庫存
                        #region 設定 Select

                        alColumns.Clear();
                        alColumns.Add(" MANDT ");
                        alColumns.Add(" COMCD ");
                        alColumns.Add(" WERKS ");
                        alColumns.Add(" LGORT ");
                        alColumns.Add(" LOCAT ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MTYPE"].ToString() + "' as MTYPE ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE ");
                        alColumns.Add(" MBLNR as OMBLNR ");
                        alColumns.Add(" MATNR ");
                        alColumns.Add(" INSMK ");
                        alColumns.Add(" CHARG ");
                        alColumns.Add(" (MENGE - REQTY + BKQTY) as MENGE "); // REQTY:被保留的數量(不能出掉的) , BKQTY:二次出貨或入庫會用到(出庫為負的,入庫為正的)
                        alColumns.Add(" 0 as ALQTY ");
                        alColumns.Add(" (MENGE - REQTY + BKQTY) as BLACE ");//Balance数量 brian 20150328
                        alColumns.Add(" 0 as SCQTY ");//Scanned数量 brian 20150328
                        alColumns.Add(" MRGID ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP ");
                        alColumns.Add(" EBELN ");
                        alColumns.Add(" LIFNR ");
                        alColumns.Add(" RMANO ");
                        alColumns.Add(" RMAK1 ");
                        alColumns.Add(" INDAT ");
                        alColumns.Add(" KDMAT ");
                        alColumns.Add(" CRDAT ");
                        //成品
                        alColumns.Add(" SERNO ");
                        alColumns.Add(" BOXID ");
                        //DateCode
                        alColumns.Add(" VEDAT ");
                        alColumns.Add(" DACOD ");
                        alColumns.Add(" LOCOD ");
                        alColumns.Add(" INSPT ");
                        //EPAD
                        alColumns.Add(" PKDAT ");
                        //將PKDAT的日期轉換為'20120109'，後面排序時才不會出現BUG  Smose Liao 20130124
                        alColumns.Add(" SUBSTRING(PKDAT,0,5) + RIGHT('0'+CONVERT(VARCHAR(2), DATEPART(month,PKDAT)), 2) + RIGHT('0'+CONVERT(VARCHAR(2), DATEPART(day,PKDAT)), 2) AS NEW_PKDAT");

                        #endregion

                        #region 設定 Condition

                        alConditions.Clear();
                        alConditions.Add("(MANDT= '" + dtDwnSource.Rows[i]["MANDT"].ToString() + "')");
                        alConditions.Add("(COMCD= '" + dtDwnSource.Rows[i]["COMCD"].ToString() + "')");
                        alConditions.Add("(WERKS= '" + dtDwnSource.Rows[i]["WERKS"].ToString() + "')");
                        alConditions.Add("(LGORT= '" + dtDwnSource.Rows[i]["LGORT"].ToString() + "')");
                        alConditions.Add("(MATNR= '" + dtDwnSource.Rows[i]["MATNR"].ToString() + "')");
                        alConditions.Add("(INSMK= '" + dtDwnSource.Rows[i]["INSMK"].ToString() + "')");
                        alConditions.Add("(CHARG= '" + dtDwnSource.Rows[i]["CHARG"].ToString() + "')");
                        //連板出庫用
                        alConditions.Add("(MRGID='" + varMrgid.Trim() + "')");
                        //SI出庫用 Add by Smose Liao 20100511
                        //if (dtDwnSource.Rows[i]["MTYPE"].ToString() == "SAP_SI")
                        //{
                        //    alConditions.Add("(EBELN= '" + dtDwnSource.Rows[i]["EBELN"].ToString() + "')");
                        //    alConditions.Add("(KDMAT= '" + dtDwnSource.Rows[i]["KDMAT"].ToString() + "')");
                        //}

                        #region 依特殊狀況出庫
                        //依User輸入的Vendor Code出庫
                        if (varLifnr != "")
                            alConditions.Add("(LIFNR='" + varLifnr.Trim() + "')");

                        //依User輸入的RMA Number出庫
                        if (varRmano != "")
                            alConditions.Add("(RMANO='" + varRmano.Trim() + "')");

                        //依PalletID出庫
                        if (varByPallet == true)
                            alConditions.Add("(MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "')");

                        //依Serial No出庫
                        if (varBySerno == true)
                            alConditions.Add(" (SERNO='" + dtDwnSource.Rows[i]["SERNO"].ToString() + "')");

                        //依PKDAT(Pallet滿板的完成時間)，限定超過24小時才能出庫  Smose Liao 20121129
                        if (COMCD == "9200" && WERKS == "CS20" && LGORT == "TW35")
                            alConditions.Add(" (DATEDIFF(MI,PKDAT,GETDATE()) >= 1440)");//計算差異的時間精確到分鐘

                        #endregion
                        #endregion

                        //brian 20150217
                        string strSql = objWhitm.EntityGetQuerySql(alColumns, alConditions, false, false);

                        dtWhitm = objWhitm.EntityQuery(alColumns, alConditions, false, false);
                        #endregion

                        #region //Brian 待修改
                        #region 出庫順序規則
                        //(出庫規則 : INDAT->先進先出, LOCAT->儲位由小到大出, CRDAT->先建檔的先出)
                        string strOrderBy = "";
                        //是否要利用DateCode先後順序作出庫
                        if (varByDateCode == true)
                        {
                            //strOrderBy = "DACOD, VEDAT, LOCAT, CRDAT";
                            strOrderBy = "VEDAT, LOCAT, CRDAT";//DateCode: 廠商生產日期, 儲位, 建立日期
                        }
                        else
                        {
                            //修改COMCD = 9100，廠區為CS12，且倉別為TW10或TW11的出庫順序  Smose Liao 20100329
                            if (COMCD == "9100" && WERKS == "CS12" && (LGORT == "TW10" || LGORT == "TW11"))
                            {
                                strOrderBy = "INDAT, CRDAT, LOCAT";
                            }
                            //依PKDAT(Pallet滿板的完成時間)，限定超過24小時才能出庫  Smose Liao 20121129
                            else if (COMCD == "9200" && WERKS == "CS20" && LGORT == "TW35")
                            {
                                strOrderBy = "NEW_PKDAT, INDAT, LOCAT DESC";
                            }
                            else
                            {
                                strOrderBy = "INDAT, LOCAT, CRDAT";//正常出庫：入庫日期, 儲位, 建立日期
                            }
                        }

                        dtWhitm = CommonInfo.SortDataTable(dtWhitm, strOrderBy);
                        #endregion

                        #region 增加REFID與SEQNO兩個欄位，查詢WHDWN中的REFID與SEQNO的值  Smose Liao 20100427
                        dtWhitm.Columns.Add("CHKED", typeof(Boolean));
                        dtWhitm.Columns.Add("REFID", Type.GetType("System.String"));
                        dtWhitm.Columns.Add("SEQNO", Type.GetType("System.String"));
                        StringBuilder sbRefidSeqno = new StringBuilder();
                        #endregion

                        #region MyRegion
                        //int intLocatMenge = 0;
                        int intSourceOutMenge = 0;

                        if (i == 0)
                        {
                            dtOutWhitm = dtWhitm.Clone();
                        }

                        #region 組單據的Key

                        StringBuilder sbWhdwnKey = new StringBuilder();
                        sbWhdwnKey.Remove(0, sbWhdwnKey.Length);
                        sbWhdwnKey.Append("CHKED = true")
                            .Append(" AND MBLNR = '" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'")
                            .Append(" AND ZEILE = '" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "'")
                            .Append(" AND MATNR = '" + dtDwnSource.Rows[i]["MATNR"].ToString() + "'")
                            .Append(" AND INSMK = '" + dtDwnSource.Rows[i]["INSMK"].ToString() + "'")
                            .Append(" AND CHARG = '" + dtDwnSource.Rows[i]["CHARG"].ToString() + "'");

                        #endregion

                        for (int j = 0; j < dtWhitm.Rows.Count; j++)
                        {
                            intSourceOutMenge = 0;

                            #region 避免重复出库
                            if (i > 0 && dtDwnSource.Rows[i]["MATNR"].ToString() == dtDwnSource.Rows[i - 1]["MATNR"].ToString() && dtDwnSource.Rows[i]["CHARG"].ToString() == dtDwnSource.Rows[i - 1]["CHARG"].ToString())
                            {
                                DataRow[] drTemp = dtOutWhitm.Select("ALQTY>0 AND ALQTY<MENGE AND CHKED = true AND LOCAT='" + dtWhitm.Rows[j]["LOCAT"] + "' ");
                                if(drTemp.Length>0){
                                    dtWhitm.Rows[j]["MENGE"] = drTemp[0]["BLACE"].ToString();
                                    dtWhitm.Rows[j]["BLACE"] = drTemp[0]["BLACE"].ToString();
                                }
                            }
                            #endregion

                            //檢查出庫單據是否都已經出完
                            #region 查看該筆單據已經出多少了

                            drFound = dtWhitm.Select(sbWhdwnKey.ToString());

                            for (int k = 0; k < drFound.Length; k++)
                            {
                                intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                            }
                            #endregion

                            if (intSourceMenge > intSourceOutMenge)//intSourceMenge:whdwn上要出的數量, intSourceMenge:已經出的數量
                            {//如果還沒出完

                                int intLocatMblnrTempAlqty = 0;

                                //從目前已出庫的數量中找出該儲位該料號已經出庫的數量
                                #region 組已出單據中儲位庫存的Key(比對WHITM的Key)
                                StringBuilder sbWhitmKey = new StringBuilder();
                                sbWhitmKey.Remove(0, sbWhitmKey.Length);
                                sbWhitmKey.Append(" LOCAT='" + dtWhitm.Rows[j]["LOCAT"].ToString() + "'");
                                sbWhitmKey.Append(" and OMBLNR = '" + dtWhitm.Rows[j]["OMBLNR"].ToString() + "'");
                                sbWhitmKey.Append(" and MATNR='" + dtWhitm.Rows[j]["MATNR"].ToString() + "'");
                                sbWhitmKey.Append(" and INSMK='" + dtWhitm.Rows[j]["INSMK"].ToString() + "'");
                                sbWhitmKey.Append(" and CHARG='" + dtWhitm.Rows[j]["CHARG"].ToString() + "'");
                                sbWhitmKey.Append(" and MRGID='" + dtWhitm.Rows[j]["MRGID"].ToString() + "'");
                                //成品
                                sbWhitmKey.Append(" and SERNO='" + dtWhitm.Rows[j]["SERNO"].ToString() + "'");
                                //DataCode
                                sbWhitmKey.Append(" and DACOD='" + dtWhitm.Rows[j]["DACOD"].ToString() + "'");
                                sbWhitmKey.Append(" and LOCOD='" + dtWhitm.Rows[j]["LOCOD"].ToString() + "'");
                                sbWhitmKey.Append(" and INSPT='" + dtWhitm.Rows[j]["INSPT"].ToString() + "'");

                                #endregion


                                drFound1 = dtWhitm.Select(sbWhitmKey.ToString());
                                for (int k = 0; k < drFound1.Length; k++)
                                {
                                    intLocatMblnrTempAlqty += Int32.Parse(drFound1[k]["ALQTY"].ToString());
                                }

                                int intBalanceQty = Int32.Parse(dtWhitm.Rows[j]["MENGE"].ToString()) - intLocatMblnrTempAlqty;
                                //MENGE:Locat數量, ALQTY:已出數量
                                //如果儲位還有剩餘數量
                                if (intBalanceQty > 0)
                                {
                                    int intLocatAlqty = 0;
                                    //如果儲位的剩餘數量小於單據的剩餘數量則全出, 否則出差值
                                    if (intSourceMenge - intSourceOutMenge >= intBalanceQty)
                                    {
                                        intLocatAlqty = intBalanceQty;
                                    }
                                    else
                                    {
                                        intLocatAlqty = intSourceMenge - intSourceOutMenge;
                                    }
                                    //如果儲位有出庫則紀錄
                                    if (intLocatAlqty > 0)
                                    {
                                        //drRow = dtOutWhitm.NewRow();
                                        //drRow["MANDT"] = dtWhitm.Rows[j]["MANDT"].ToString();
                                        //drRow["COMCD"] = dtWhitm.Rows[j]["COMCD"].ToString();
                                        //drRow["WERKS"] = dtWhitm.Rows[j]["WERKS"].ToString();
                                        //drRow["LGORT"] = dtWhitm.Rows[j]["LGORT"].ToString();
                                        //drRow["LOCAT"] = dtWhitm.Rows[j]["LOCAT"].ToString();
                                        //drRow["MATNR"] = dtWhitm.Rows[j]["MATNR"].ToString();
                                        //drRow["INSMK"] = dtWhitm.Rows[j]["INSMK"].ToString();
                                        //drRow["CHARG"] = dtWhitm.Rows[j]["CHARG"].ToString();
                                        //drRow["MENGE"] = dtWhitm.Rows[j]["MENGE"].ToString();
                                        dtWhitm.Rows[j]["ALQTY"] = intLocatAlqty.ToString();
                                        dtWhitm.Rows[j]["BLACE"] = Convert.ToString(Int32.Parse(dtWhitm.Rows[j]["BLACE"].ToString()) - intLocatAlqty);
                                        dtWhitm.Rows[j]["CHKED"] = true;
                                        //drRow["MTYPE"] = dtWhitm.Rows[j]["MTYPE"].ToString();
                                        //drRow["MBLNR"] = dtWhitm.Rows[j]["MBLNR"].ToString();
                                        //drRow["ZEILE"] = dtWhitm.Rows[j]["ZEILE"].ToString();
                                        //drRow["EBELN"] = dtWhitm.Rows[j]["EBELN"].ToString();
                                        //drRow["LIFNR"] = dtWhitm.Rows[j]["LIFNR"].ToString();
                                        //drRow["RMANO"] = dtWhitm.Rows[j]["RMANO"].ToString();  // Quanta, Smose.Liao, 20090225：Add the function of Online Goods Issue by RMA No.(連線出庫依據RMA NO.進行出庫)
                                        //drRow["OMBLNR"] = dtWhitm.Rows[j]["OMBLNR"].ToString();
                                        //drRow["MRGID"] = dtWhitm.Rows[j]["MRGID"].ToString();
                                        //drRow["KOSTL"] = dtWhitm.Rows[j]["KOSTL"].ToString();
                                        //drRow["ARBPL"] = dtWhitm.Rows[j]["ARBPL"].ToString();
                                        //drRow["TRNTP"] = dtWhitm.Rows[j]["TRNTP"].ToString();
                                        //drRow["RMAK1"] = dtWhitm.Rows[j]["RMAK1"].ToString();
                                        //drRow["INDAT"] = dtWhitm.Rows[j]["INDAT"].ToString();
                                        ////20051017 MARC 新增KDMAT欄位
                                        //drRow["KDMAT"] = dtWhitm.Rows[j]["KDMAT"].ToString();
                                        ////成品
                                        //drRow["SERNO"] = dtWhitm.Rows[j]["SERNO"].ToString();
                                        //drRow["BOXID"] = dtWhitm.Rows[j]["BOXID"].ToString();
                                        ////DateCode
                                        //drRow["VEDAT"] = dtWhitm.Rows[j]["VEDAT"].ToString();
                                        //drRow["DACOD"] = dtWhitm.Rows[j]["DACOD"].ToString();
                                        //drRow["LOCOD"] = dtWhitm.Rows[j]["LOCOD"].ToString();
                                        //drRow["INSPT"] = dtWhitm.Rows[j]["INSPT"].ToString();
                                        //drRow["PKDAT"] = dtWhitm.Rows[j]["PKDAT"].ToString();

                                        //dtOutWhitm.Rows.Add(drRow);
                                    }
                                }
                            }
                            else
                            {
                                break;
                            }
                        }
                        #endregion

                        #region brian 20150326

                        foreach (DataRow drWhitm in dtWhitm.Rows)
                        {
                            drRow = dtOutWhitm.NewRow();
                            drRow.ItemArray = drWhitm.ItemArray;
                            dtOutWhitm.Rows.Add(drRow);
                        }
                        #endregion

                        #region 更新單據的總出庫數量
                        //更新單據的總出庫數量
                        intSourceOutMenge = 0;

                        drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                        for (int k = 0; k < drFound.Length; k++)
                        {
                            intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                        }
                        dtDwnSource.Rows[i]["ALQTY"] = intSourceOutMenge;

                        #endregion

                        #endregion

                        #region //查詢WHDWN中的REFID與SEQNO的值  Smose Liao 20100427

                        //if (dtOutWhitm.Rows.Count > 0)
                        //{
                        //    sbRefidSeqno.Remove(0, sbRefidSeqno.Length);
                        //    //sbRefidSeqno.Append(" WERKS='" + dtOutWhitm.Rows[i]["WERKS"].ToString() + "'");
                        //    //sbRefidSeqno.Append(" and MBLNR = '" + dtOutWhitm.Rows[i]["MBLNR"].ToString() + "'");
                        //    //sbRefidSeqno.Append(" and MATNR = '" + dtOutWhitm.Rows[i]["MATNR"].ToString() + "'");
                        //    sbRefidSeqno.Append(" WERKS='" + dtOutWhitm.Rows[0]["WERKS"].ToString() + "'");
                        //    sbRefidSeqno.Append(" and MBLNR = '" + dtOutWhitm.Rows[0]["MBLNR"].ToString() + "'");
                        //    sbRefidSeqno.Append(" and MATNR = '" + dtOutWhitm.Rows[0]["MATNR"].ToString() + "'");

                        //    drFound = dtDwnSource.Select(sbRefidSeqno.ToString());
                        //    for (int m = 0; m < dtOutWhitm.Rows.Count; m++)
                        //    {

                        //        if (drFound.Length > 0)
                        //        {
                        //            dtOutWhitm.Rows[m]["REFID"] = drFound[0]["REFID"].ToString();
                        //            //dtOutWhitm.Rows[m]["SEQNO"] = drFound[0]["SEQNO"].ToString();//SEQNO這個欄位現在好像沒在用了，暫時先放空值 Smose Liao 20130523
                        //            dtOutWhitm.Rows[m]["SEQNO"] = "";
                        //        }
                        //        else
                        //        {
                        //            dtOutWhitm.Rows[m]["REFID"] = "";
                        //            dtOutWhitm.Rows[m]["SEQNO"] = "";
                        //        }
                        //    }
                        //}

                        #endregion
                    }

                    if (dtDwnSource.DataSet != null)
                        dtDwnSource.DataSet.Tables.Remove(dtDwnSource);

                    dtDwnSource.TableName = "Source";
                    dtOutWhitm.TableName = "Destination";
                    dsResult.Tables.Add(dtDwnSource);
                    dsResult.Tables.Add(dtOutWhitm);
                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- GetOnLineOutData()";
                }

                return dsResult;
            }
            #endregion

            #region 連線出庫_SpareParts(查詢庫存並算出出庫狀況) by Smose Liao 20100610
            //=====================================================================================
            ////////////Summary by Smose Liao 20100610/////////////////////////////////////////////
            /// <summary> 
            /// 加入"指定Rmano欄位" 連線出庫 
            /// 1.	找出連線出庫在庫存中可以出庫的數量, 不帶出連板料號
            /// 2.	DataSet包括: OutSource及Storage兩個Table
            /// </summary> 
            /// <param name="dtOutSource">出庫資料。</param>
            /// <param name="varLifnr">指定Vendor Code。</param>
            /// <param name="varRmano">指定RMA No。</param>
            /// <param name="varByDateCode">是否要ByDateCode作先進先出出庫。</param>
            /// <param name="varMrgid">連板出庫的模組編號。</param>
            /// <param name="varByPallet">是否要Pallet出庫(成品)。</param>
            /// <param name="varBySerno">是否要Serial No出庫(成品)。</param>
            /// <returns>
            /// DataSet。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QueryOnLineOutData_SpareParts(dtOutSource, txtLifnr, txtRmano);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////
            public DataSet QueryOnLineOutData_SpareParts(DataTable dtDwnSource, string varLifnr, string varRmano, bool varByDateCode, string varMrgid, bool varByPallet, bool varBySerno, bool varByEbeln, bool varByKdmat)
            {
                DataSet dsResult = new DataSet();
                try
                {
                    DataTable dtOutWhitm = new DataTable();//要出庫的庫存數據

                    DataRow drRow;
                    DataRow[] drFound;
                    DataRow[] drFound1;

                    DataWhitm objWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    DataTable dtWhitm = new DataTable();

                    for (int i = 0; i < dtDwnSource.Rows.Count; i++)
                    {
                        #region 組單據的Key
                        StringBuilder sbWhdwnKey = new StringBuilder();
                        sbWhdwnKey.Remove(0, sbWhdwnKey.Length);
                        sbWhdwnKey.Append(" MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'");
                        sbWhdwnKey.Append(" and ZEILE='" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "'");
                        sbWhdwnKey.Append(" and MATNR='" + dtDwnSource.Rows[i]["MATNR"].ToString() + "'");
                        sbWhdwnKey.Append(" and INSMK='" + dtDwnSource.Rows[i]["INSMK"].ToString() + "'");
                        sbWhdwnKey.Append(" and CHARG='" + dtDwnSource.Rows[i]["CHARG"].ToString() + "'");
                        #endregion

                        //出庫單據的數量
                        int intSourceMenge = int.Parse(dtDwnSource.Rows[i]["MENGE"].ToString());

                        #region 找出符合條件且可出庫的庫存
                        #region 設定 Select

                        alColumns.Clear();
                        alColumns.Add(" MANDT ");
                        alColumns.Add(" COMCD ");
                        alColumns.Add(" WERKS ");
                        alColumns.Add(" LGORT ");
                        alColumns.Add(" LOCAT ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MTYPE"].ToString() + "' as MTYPE ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE ");
                        alColumns.Add(" MBLNR as OMBLNR ");
                        alColumns.Add(" MATNR ");
                        alColumns.Add(" INSMK ");
                        alColumns.Add(" CHARG ");
                        alColumns.Add(" (MENGE-REQTY+BKQTY) as MENGE "); // REQTY:被保留的數量(不能出掉的) , BKQTY:二次出貨或入庫會用到(出庫為負的,入庫為正的)
                        alColumns.Add(" 0 as ALQTY ");
                        alColumns.Add(" MRGID ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP ");
                        alColumns.Add(" EBELN ");
                        alColumns.Add(" LIFNR ");
                        alColumns.Add(" RMANO ");
                        alColumns.Add(" RMAK1 ");
                        alColumns.Add(" INDAT ");
                        alColumns.Add(" KDMAT ");
                        alColumns.Add(" CRDAT ");
                        //成品
                        alColumns.Add(" SERNO ");
                        //DateCode
                        alColumns.Add(" VEDAT ");
                        alColumns.Add(" DACOD ");
                        alColumns.Add(" LOCOD ");
                        alColumns.Add(" INSPT ");

                        #endregion

                        #region 設定 Condition

                        alConditions.Clear();
                        alConditions.Add("(MANDT= '" + dtDwnSource.Rows[i]["MANDT"].ToString() + "')");
                        alConditions.Add("(COMCD= '" + dtDwnSource.Rows[i]["COMCD"].ToString() + "')");
                        alConditions.Add("(WERKS= '" + dtDwnSource.Rows[i]["WERKS"].ToString() + "')");
                        alConditions.Add("(LGORT= '" + dtDwnSource.Rows[i]["LGORT"].ToString() + "')");
                        alConditions.Add("(MATNR= '" + dtDwnSource.Rows[i]["MATNR"].ToString() + "')");
                        alConditions.Add("(INSMK= '" + dtDwnSource.Rows[i]["INSMK"].ToString() + "')");
                        alConditions.Add("(CHARG= '" + dtDwnSource.Rows[i]["CHARG"].ToString() + "')");
                        //連板出庫用
                        alConditions.Add("(MRGID='" + varMrgid.Trim() + "')");
                        //SI出庫用 Add by Smose Liao 20100511
                        if (dtDwnSource.Rows[i]["MTYPE"].ToString() == "SAP_SI")
                        {
                            if (varByEbeln)
                            {
                                alConditions.Add("(EBELN= '" + dtDwnSource.Rows[i]["EBELN"].ToString() + "')");
                            }
                            if (varByKdmat)
                            {
                                alConditions.Add("(KDMAT= '" + dtDwnSource.Rows[i]["KDMAT"].ToString() + "')");
                            }
                            alConditions.Add("(NLOCA = '')");
                        }

                        #region 依特殊狀況出庫
                        //依User輸入的Vendor Code出庫
                        if (varLifnr != "")
                            alConditions.Add("(LIFNR='" + varLifnr.Trim() + "')");

                        //依User輸入的RMA Number出庫
                        if (varRmano != "")
                            alConditions.Add("(RMANO='" + varRmano.Trim() + "')");

                        //依PalletID出庫
                        if (varByPallet == true)
                            alConditions.Add("(MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "')");

                        //依Serial No出庫
                        if (varBySerno == true)
                            alConditions.Add(" (SERNO='" + dtDwnSource.Rows[i]["SERNO"].ToString() + "')");

                        #endregion

                        //去掉待确认储位
                        alConditions.Add("(LOCAT not in(select ctrlc2 from WHCTRL where MANDT='" + dtDwnSource.Rows[i]["MANDT"].ToString() + "'AND COMCD='" + dtDwnSource.Rows[i]["COMCD"].ToString() + "'AND CTRLNM='" + dtDwnSource.Rows[i]["WERKS"].ToString() + "'AND CTRLID='TDBLOCAT'))");
                        #endregion

                        //annie 20160811
                        string str = objWhitm.EntityGetQuerySql(alColumns, alConditions, false, true);

                        dtWhitm = objWhitm.EntityQuery(alColumns, alConditions, false, false);
                        #endregion

                        #region 出庫順序規則
                        //(出庫規則 : INDAT->先進先出, LOCAT->儲位由小到大出, CREDAT->先建檔的先出)
                        string strOrderBy = "";
                        //是否要利用DateCode先後順序作出庫
                        if (varByDateCode == true)
                        {
                            strOrderBy = "VEDAT, LOCAT, CRDAT";
                        }
                        else
                        {
                            //修改COMCD = 9100，廠區為CS12，且倉別為TW10或TW11的出庫順序  Smose Liao 20100329
                            if (COMCD == "9100" && WERKS == "CS12" && (LGORT == "TW10" || LGORT == "TW11"))
                            {
                                strOrderBy = "INDAT, CRDAT, LOCAT";
                            }
                            else
                            {
                                strOrderBy = "INDAT, LOCAT, CRDAT";
                            }
                        }

                        dtWhitm = CommonInfo.SortDataTable(dtWhitm, strOrderBy);
                        #endregion

                        #region //增加REFID與SEQNO兩個欄位，查詢WHDWN中的REFID與SEQNO的值  Smose Liao 20100427
                        dtWhitm.Columns.Add("REFID", Type.GetType("System.String"));
                        dtWhitm.Columns.Add("SEQNO", Type.GetType("System.String"));
                        StringBuilder sbRefidSeqno = new StringBuilder();
                        #endregion

                        int intSourceOutMenge = 0;

                        if (i == 0)
                        {
                            dtOutWhitm = dtWhitm.Clone();
                        }

                        for (int j = 0; j < dtWhitm.Rows.Count; j++)
                        {
                            intSourceOutMenge = 0;

                            //檢查出庫單據是否都已經出完
                            #region 查看該筆單據已經出多少了

                            drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                            for (int k = 0; k < drFound.Length; k++)
                            {
                                intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                            }
                            #endregion

                            if (intSourceMenge > intSourceOutMenge)//intSourceMenge:whdwn上要出的數量, intSourceMenge:已經出的數量
                            {//如果還沒出完

                                int intLocatMblnrTempAlqty = 0;

                                //從目前已出庫的數量中找出該儲位該料號已經出庫的數量
                                #region 組已出單據中儲位庫存的Key(比對WHITM的Key)
                                StringBuilder sbWhitmKey = new StringBuilder();
                                sbWhitmKey.Remove(0, sbWhitmKey.Length);
                                sbWhitmKey.Append(" LOCAT='" + dtWhitm.Rows[j]["LOCAT"].ToString() + "'");
                                sbWhitmKey.Append(" and OMBLNR = '" + dtWhitm.Rows[j]["OMBLNR"].ToString() + "'");
                                sbWhitmKey.Append(" and MATNR='" + dtWhitm.Rows[j]["MATNR"].ToString() + "'");
                                sbWhitmKey.Append(" and INSMK='" + dtWhitm.Rows[j]["INSMK"].ToString() + "'");
                                sbWhitmKey.Append(" and CHARG='" + dtWhitm.Rows[j]["CHARG"].ToString() + "'");
                                sbWhitmKey.Append(" and MRGID='" + dtWhitm.Rows[j]["MRGID"].ToString() + "'");
                                //成品
                                sbWhitmKey.Append(" and SERNO='" + dtWhitm.Rows[j]["SERNO"].ToString() + "'");
                                //DataCode
                                sbWhitmKey.Append(" and DACOD='" + dtWhitm.Rows[j]["DACOD"].ToString() + "'");
                                sbWhitmKey.Append(" and LOCOD='" + dtWhitm.Rows[j]["LOCOD"].ToString() + "'");
                                sbWhitmKey.Append(" and INSPT='" + dtWhitm.Rows[j]["INSPT"].ToString() + "'");

                                #endregion


                                drFound1 = dtOutWhitm.Select(sbWhitmKey.ToString());
                                for (int k = 0; k < drFound1.Length; k++)
                                {
                                    intLocatMblnrTempAlqty += Int32.Parse(drFound1[k]["ALQTY"].ToString());
                                }

                                int intBalanceQty = Int32.Parse(dtWhitm.Rows[j]["MENGE"].ToString()) - intLocatMblnrTempAlqty;
                                //MENGE:Locat數量, ALQTY:已出數量
                                //如果儲位還有剩餘數量
                                if (intBalanceQty > 0)
                                {
                                    int intLocatAlqty = 0;
                                    //如果儲位的剩餘數量小於單據的剩餘數量則全出, 否則出差值
                                    if (intSourceMenge - intSourceOutMenge >= intBalanceQty)
                                    {
                                        intLocatAlqty = intBalanceQty;
                                    }
                                    else
                                    {
                                        intLocatAlqty = intSourceMenge - intSourceOutMenge;
                                    }
                                    //如果儲位有出庫則紀錄
                                    if (intLocatAlqty > 0)
                                    {
                                        drRow = dtOutWhitm.NewRow();
                                        drRow["MANDT"] = dtWhitm.Rows[j]["MANDT"].ToString();
                                        drRow["COMCD"] = dtWhitm.Rows[j]["COMCD"].ToString();
                                        drRow["WERKS"] = dtWhitm.Rows[j]["WERKS"].ToString();
                                        drRow["LGORT"] = dtWhitm.Rows[j]["LGORT"].ToString();
                                        drRow["LOCAT"] = dtWhitm.Rows[j]["LOCAT"].ToString();
                                        drRow["MATNR"] = dtWhitm.Rows[j]["MATNR"].ToString();
                                        drRow["INSMK"] = dtWhitm.Rows[j]["INSMK"].ToString();
                                        drRow["CHARG"] = dtWhitm.Rows[j]["CHARG"].ToString();
                                        drRow["MENGE"] = dtWhitm.Rows[j]["MENGE"].ToString();
                                        drRow["ALQTY"] = intLocatAlqty.ToString();
                                        drRow["MTYPE"] = dtWhitm.Rows[j]["MTYPE"].ToString();
                                        drRow["MBLNR"] = dtWhitm.Rows[j]["MBLNR"].ToString();
                                        drRow["ZEILE"] = dtWhitm.Rows[j]["ZEILE"].ToString();
                                        drRow["EBELN"] = dtWhitm.Rows[j]["EBELN"].ToString();
                                        drRow["LIFNR"] = dtWhitm.Rows[j]["LIFNR"].ToString();
                                        drRow["RMANO"] = dtWhitm.Rows[j]["RMANO"].ToString();
                                        drRow["OMBLNR"] = dtWhitm.Rows[j]["OMBLNR"].ToString();
                                        drRow["MRGID"] = dtWhitm.Rows[j]["MRGID"].ToString();
                                        drRow["KOSTL"] = dtWhitm.Rows[j]["KOSTL"].ToString();
                                        drRow["ARBPL"] = dtWhitm.Rows[j]["ARBPL"].ToString();
                                        drRow["TRNTP"] = dtWhitm.Rows[j]["TRNTP"].ToString();
                                        drRow["RMAK1"] = dtWhitm.Rows[j]["RMAK1"].ToString();
                                        drRow["INDAT"] = dtWhitm.Rows[j]["INDAT"].ToString();
                                        //20051017 MARC 新增KDMAT欄位
                                        drRow["KDMAT"] = dtWhitm.Rows[j]["KDMAT"].ToString();
                                        //成品
                                        drRow["SERNO"] = dtWhitm.Rows[j]["SERNO"].ToString();
                                        //DateCode
                                        drRow["VEDAT"] = dtWhitm.Rows[j]["VEDAT"].ToString();
                                        drRow["DACOD"] = dtWhitm.Rows[j]["DACOD"].ToString();
                                        drRow["LOCOD"] = dtWhitm.Rows[j]["LOCOD"].ToString();
                                        drRow["INSPT"] = dtWhitm.Rows[j]["INSPT"].ToString();

                                        dtOutWhitm.Rows.Add(drRow);

                                    }
                                }
                            }
                            else
                            {
                                break;
                            }
                        }
                        //更新單據的總出庫數量
                        intSourceOutMenge = 0;

                        drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                        for (int k = 0; k < drFound.Length; k++)
                        {
                            intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                        }
                        dtDwnSource.Rows[i]["ALQTY"] = intSourceOutMenge;
                    }

                    //記錄剩餘的數量
                    //dtDwnSource.Columns.Add("BLACE");
                    //by blank 20151224 在ref的时候如果不判断加列会报错。
                    if (dtDwnSource.Columns.IndexOf("BLACE") == -1)
                    {
                        dtDwnSource.Columns.Add("BLACE");
                    }
                    for (int m = 0; m < dtDwnSource.Rows.Count; m++)
                    {
                        dtDwnSource.Rows[m]["BLACE"] = Convert.ToString(int.Parse(dtDwnSource.Rows[m]["MENGE"].ToString()) - int.Parse(dtDwnSource.Rows[m]["ALQTY"].ToString()));
                    }

                    if (dtDwnSource.DataSet != null)
                        dtDwnSource.DataSet.Tables.Remove(dtDwnSource);

                    dtDwnSource.TableName = "Source";
                    dtOutWhitm.TableName = "Destination";
                    dsResult.Tables.Add(dtDwnSource);
                    dsResult.Tables.Add(dtOutWhitm);

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryOnLineOutData_SpareParts()";
                }
                return dsResult;
            }

            #endregion


            #region 連線出庫_DOA(查詢庫存並算出出庫狀況) by Smose Liao 20110125
            //=====================================================================================
            ////////////Summary by Smose Liao 20110125/////////////////////////////////////////////
            /// <summary> 
            /// 加入"指定Rmano欄位" 連線出庫 
            /// 1.	找出連線出庫在庫存中可以出庫的數量, 不帶出連板料號
            /// 2.	DataSet包括: OutSource及Storage兩個Table
            /// </summary> 
            /// <param name="dtOutSource">出庫資料。</param>
            /// <param name="varLifnr">指定Vendor Code。</param>
            /// <param name="varRmano">指定RMA No。</param>
            /// <param name="varByDateCode">是否要ByDateCode作先進先出出庫。</param>
            /// <param name="varMrgid">連板出庫的模組編號。</param>
            /// <param name="varByPallet">是否要Pallet出庫(成品)。</param>
            /// <param name="varBySerno">是否要Serial No出庫(成品)。</param>
            /// <param name="varBySerno">是否要RMA No出庫。</param>
            /// <returns>
            /// DataSet。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QueryOnLineOutData_DOA(dtOutSource, txtLifnr, txtRmano);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////
            public DataSet QueryOnLineOutData_DOA(DataTable dtDwnSource, string varLifnr, string varRmano, bool varByDateCode, string varMrgid, bool varByPallet, bool varBySerno, bool varByRmano)
            {
                DataSet dsResult = new DataSet();
                try
                {
                    DataTable dtOutWhitm = new DataTable();//要出庫的庫存數據

                    DataRow drRow;
                    DataRow[] drFound;
                    DataRow[] drFound1;

                    DataWhitm objWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    DataTable dtWhitm = new DataTable();

                    for (int i = 0; i < dtDwnSource.Rows.Count; i++)
                    {
                        #region 組單據的Key
                        StringBuilder sbWhdwnKey = new StringBuilder();
                        sbWhdwnKey.Remove(0, sbWhdwnKey.Length);
                        sbWhdwnKey.Append(" MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'");
                        sbWhdwnKey.Append(" and ZEILE='" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "'");
                        sbWhdwnKey.Append(" and MATNR='" + dtDwnSource.Rows[i]["MATNR"].ToString() + "'");
                        //SI單據庫別皆為S，但W/H入進去的庫別是S，因此不考慮庫別 Smose Liao 20110324
                        //sbWhdwnKey.Append(" and INSMK='" + dtDwnSource.Rows[i]["INSMK"].ToString() + "'");
                        sbWhdwnKey.Append(" and CHARG='" + dtDwnSource.Rows[i]["CHARG"].ToString() + "'");
                        #endregion

                        //出庫單據的數量
                        int intSourceMenge = int.Parse(dtDwnSource.Rows[i]["MENGE"].ToString());

                        #region 找出符合條件且可出庫的庫存
                        #region 設定 Select

                        alColumns.Clear();
                        alColumns.Add(" MANDT ");
                        alColumns.Add(" COMCD ");
                        alColumns.Add(" WERKS ");
                        alColumns.Add(" LGORT ");
                        alColumns.Add(" LOCAT ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MTYPE"].ToString() + "' as MTYPE ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE ");
                        alColumns.Add(" MBLNR as OMBLNR ");
                        alColumns.Add(" MATNR ");
                        alColumns.Add(" INSMK ");
                        alColumns.Add(" CHARG ");
                        alColumns.Add(" (MENGE-REQTY+BKQTY) as MENGE "); // REQTY:被保留的數量(不能出掉的) , BKQTY:二次出貨或入庫會用到(出庫為負的,入庫為正的)
                        alColumns.Add(" 0 as ALQTY ");
                        alColumns.Add(" MRGID ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP ");
                        alColumns.Add(" EBELN ");
                        alColumns.Add(" LIFNR ");
                        alColumns.Add(" RMANO ");
                        alColumns.Add(" RMAK1 ");
                        alColumns.Add(" INDAT ");
                        alColumns.Add(" KDMAT ");
                        alColumns.Add(" CRDAT ");
                        //成品
                        alColumns.Add(" SERNO ");
                        //DateCode
                        alColumns.Add(" VEDAT ");
                        alColumns.Add(" DACOD ");
                        alColumns.Add(" LOCOD ");
                        alColumns.Add(" INSPT ");

                        #endregion

                        #region 設定 Condition

                        alConditions.Clear();
                        alConditions.Add("(MANDT= '" + dtDwnSource.Rows[i]["MANDT"].ToString() + "')");
                        alConditions.Add("(COMCD= '" + dtDwnSource.Rows[i]["COMCD"].ToString() + "')");
                        alConditions.Add("(WERKS= '" + dtDwnSource.Rows[i]["WERKS"].ToString() + "')");
                        alConditions.Add("(LGORT= '" + dtDwnSource.Rows[i]["LGORT"].ToString() + "')");
                        alConditions.Add("(MATNR= '" + dtDwnSource.Rows[i]["MATNR"].ToString() + "')");
                        //SI單據庫別皆為S，但W/H入進去的庫別是S，因此不考慮庫別 Smose Liao 20110324
                        //alConditions.Add("(INSMK= '" + dtDwnSource.Rows[i]["INSMK"].ToString() + "')");
                        alConditions.Add("(CHARG= '" + dtDwnSource.Rows[i]["CHARG"].ToString() + "')");
                        ////連板出庫用
                        //alConditions.Add("(MRGID='" + varMrgid.Trim() + "')");
                        //SI出庫用(By RMA No.出庫)
                        if (dtDwnSource.Rows[i]["MTYPE"].ToString() == "SAP_SI")
                        {
                            if (varByRmano)
                            {
                                alConditions.Add("(RMANO= '" + dtDwnSource.Rows[i]["RMANO"].ToString() + "')");
                            }

                            alConditions.Add("(NLOCA = '')");
                        }

                        #region 依特殊狀況出庫
                        //依User輸入的Vendor Code出庫
                        if (varLifnr != "")
                            alConditions.Add("(LIFNR='" + varLifnr.Trim() + "')");

                        //依User輸入的RMA Number出庫
                        if (varRmano != "")
                            alConditions.Add("(RMANO='" + varRmano.Trim() + "')");

                        //依PalletID出庫
                        if (varByPallet == true)
                            alConditions.Add("(MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "')");

                        //依Serial No出庫
                        if (varBySerno == true)
                            alConditions.Add(" (SERNO='" + dtDwnSource.Rows[i]["SERNO"].ToString() + "')");

                        #endregion
                        #endregion

                        dtWhitm = objWhitm.EntityQuery(alColumns, alConditions, false, false);
                        #endregion

                        #region 出庫順序規則
                        //(出庫規則 : INDAT->先進先出, LOCAT->儲位由小到大出, CREDAT->先建檔的先出)
                        string strOrderBy = "";
                        //是否要利用DateCode先後順序作出庫
                        if (varByDateCode == true)
                        {
                            strOrderBy = "VEDAT, LOCAT, CRDAT";
                        }
                        else
                        {
                            //修改COMCD = 9100，廠區為CS12，且倉別為TW10或TW11的出庫順序  Smose Liao 20100329
                            if (COMCD == "9100" && WERKS == "CS12" && (LGORT == "TW10" || LGORT == "TW11"))
                            {
                                strOrderBy = "INDAT, CRDAT, LOCAT";
                            }
                            else
                            {
                                strOrderBy = "INDAT, LOCAT, CRDAT";
                            }
                        }

                        dtWhitm = CommonInfo.SortDataTable(dtWhitm, strOrderBy);
                        #endregion

                        #region //增加REFID與SEQNO兩個欄位，查詢WHDWN中的REFID與SEQNO的值  Smose Liao 20100427
                        dtWhitm.Columns.Add("REFID", Type.GetType("System.String"));
                        dtWhitm.Columns.Add("SEQNO", Type.GetType("System.String"));
                        StringBuilder sbRefidSeqno = new StringBuilder();
                        #endregion

                        int intSourceOutMenge = 0;

                        if (i == 0)
                        {
                            dtOutWhitm = dtWhitm.Clone();
                        }

                        for (int j = 0; j < dtWhitm.Rows.Count; j++)
                        {
                            intSourceOutMenge = 0;

                            //檢查出庫單據是否都已經出完
                            #region 查看該筆單據已經出多少了

                            drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                            for (int k = 0; k < drFound.Length; k++)
                            {
                                intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                            }
                            #endregion

                            if (intSourceMenge > intSourceOutMenge)//intSourceMenge:whdwn上要出的數量, intSourceMenge:已經出的數量
                            {//如果還沒出完

                                int intLocatMblnrTempAlqty = 0;

                                //從目前已出庫的數量中找出該儲位該料號已經出庫的數量
                                #region 組已出單據中儲位庫存的Key(比對WHITM的Key)
                                StringBuilder sbWhitmKey = new StringBuilder();
                                sbWhitmKey.Remove(0, sbWhitmKey.Length);
                                sbWhitmKey.Append(" LOCAT='" + dtWhitm.Rows[j]["LOCAT"].ToString() + "'");
                                sbWhitmKey.Append(" and OMBLNR = '" + dtWhitm.Rows[j]["OMBLNR"].ToString() + "'");
                                sbWhitmKey.Append(" and MATNR='" + dtWhitm.Rows[j]["MATNR"].ToString() + "'");
                                //SI單據庫別皆為S，但W/H入進去的庫別是S，因此不考慮庫別 Smose Liao 20110324
                                //sbWhitmKey.Append(" and INSMK='" + dtWhitm.Rows[j]["INSMK"].ToString() + "'");
                                sbWhitmKey.Append(" and CHARG='" + dtWhitm.Rows[j]["CHARG"].ToString() + "'");
                                sbWhitmKey.Append(" and MRGID='" + dtWhitm.Rows[j]["MRGID"].ToString() + "'");
                                //成品
                                sbWhitmKey.Append(" and SERNO='" + dtWhitm.Rows[j]["SERNO"].ToString() + "'");
                                //DataCode
                                sbWhitmKey.Append(" and DACOD='" + dtWhitm.Rows[j]["DACOD"].ToString() + "'");
                                sbWhitmKey.Append(" and LOCOD='" + dtWhitm.Rows[j]["LOCOD"].ToString() + "'");
                                sbWhitmKey.Append(" and INSPT='" + dtWhitm.Rows[j]["INSPT"].ToString() + "'");

                                #endregion


                                drFound1 = dtOutWhitm.Select(sbWhitmKey.ToString());
                                for (int k = 0; k < drFound1.Length; k++)
                                {
                                    intLocatMblnrTempAlqty += Int32.Parse(drFound1[k]["ALQTY"].ToString());
                                }

                                int intBalanceQty = Int32.Parse(dtWhitm.Rows[j]["MENGE"].ToString()) - intLocatMblnrTempAlqty;
                                //MENGE:Locat數量, ALQTY:已出數量
                                //如果儲位還有剩餘數量
                                if (intBalanceQty > 0)
                                {
                                    int intLocatAlqty = 0;
                                    //如果儲位的剩餘數量小於單據的剩餘數量則全出, 否則出差值
                                    if (intSourceMenge - intSourceOutMenge >= intBalanceQty)
                                    {
                                        intLocatAlqty = intBalanceQty;
                                    }
                                    else
                                    {
                                        intLocatAlqty = intSourceMenge - intSourceOutMenge;
                                    }
                                    //如果儲位有出庫則紀錄
                                    if (intLocatAlqty > 0)
                                    {
                                        drRow = dtOutWhitm.NewRow();
                                        drRow["MANDT"] = dtWhitm.Rows[j]["MANDT"].ToString();
                                        drRow["COMCD"] = dtWhitm.Rows[j]["COMCD"].ToString();
                                        drRow["WERKS"] = dtWhitm.Rows[j]["WERKS"].ToString();
                                        drRow["LGORT"] = dtWhitm.Rows[j]["LGORT"].ToString();
                                        drRow["LOCAT"] = dtWhitm.Rows[j]["LOCAT"].ToString();
                                        drRow["MATNR"] = dtWhitm.Rows[j]["MATNR"].ToString();
                                        drRow["INSMK"] = dtWhitm.Rows[j]["INSMK"].ToString();
                                        drRow["CHARG"] = dtWhitm.Rows[j]["CHARG"].ToString();
                                        drRow["MENGE"] = dtWhitm.Rows[j]["MENGE"].ToString();
                                        drRow["ALQTY"] = intLocatAlqty.ToString();
                                        drRow["MTYPE"] = dtWhitm.Rows[j]["MTYPE"].ToString();
                                        drRow["MBLNR"] = dtWhitm.Rows[j]["MBLNR"].ToString();
                                        drRow["ZEILE"] = dtWhitm.Rows[j]["ZEILE"].ToString();
                                        drRow["EBELN"] = dtWhitm.Rows[j]["EBELN"].ToString();
                                        drRow["LIFNR"] = dtWhitm.Rows[j]["LIFNR"].ToString();
                                        drRow["RMANO"] = dtWhitm.Rows[j]["RMANO"].ToString();
                                        drRow["OMBLNR"] = dtWhitm.Rows[j]["OMBLNR"].ToString();
                                        drRow["MRGID"] = dtWhitm.Rows[j]["MRGID"].ToString();
                                        drRow["KOSTL"] = dtWhitm.Rows[j]["KOSTL"].ToString();
                                        drRow["ARBPL"] = dtWhitm.Rows[j]["ARBPL"].ToString();
                                        drRow["TRNTP"] = dtWhitm.Rows[j]["TRNTP"].ToString();
                                        drRow["RMAK1"] = dtWhitm.Rows[j]["RMAK1"].ToString();
                                        drRow["INDAT"] = dtWhitm.Rows[j]["INDAT"].ToString();
                                        //20051017 MARC 新增KDMAT欄位
                                        drRow["KDMAT"] = dtWhitm.Rows[j]["KDMAT"].ToString();
                                        //成品
                                        drRow["SERNO"] = dtWhitm.Rows[j]["SERNO"].ToString();
                                        //DateCode
                                        drRow["VEDAT"] = dtWhitm.Rows[j]["VEDAT"].ToString();
                                        drRow["DACOD"] = dtWhitm.Rows[j]["DACOD"].ToString();
                                        drRow["LOCOD"] = dtWhitm.Rows[j]["LOCOD"].ToString();
                                        drRow["INSPT"] = dtWhitm.Rows[j]["INSPT"].ToString();

                                        dtOutWhitm.Rows.Add(drRow);
                                    }
                                }
                            }
                            else
                            {
                                break;
                            }
                        }
                        //更新單據的總出庫數量
                        intSourceOutMenge = 0;

                        drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                        for (int k = 0; k < drFound.Length; k++)
                        {
                            intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                        }
                        dtDwnSource.Rows[i]["ALQTY"] = intSourceOutMenge;
                    }

                    //記錄剩餘的數量
                    dtDwnSource.Columns.Add("BLACE");
                    for (int m = 0; m < dtDwnSource.Rows.Count; m++)
                    {
                        dtDwnSource.Rows[m]["BLACE"] = Convert.ToString(int.Parse(dtDwnSource.Rows[m]["MENGE"].ToString()) - int.Parse(dtDwnSource.Rows[m]["ALQTY"].ToString()));
                    }

                    if (dtDwnSource.DataSet != null)
                        dtDwnSource.DataSet.Tables.Remove(dtDwnSource);

                    dtDwnSource.TableName = "Source";
                    dtOutWhitm.TableName = "Destination";
                    dsResult.Tables.Add(dtDwnSource);
                    dsResult.Tables.Add(dtOutWhitm);

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryOnLineOutData_DOA()";
                }
                return dsResult;
            }

            #endregion


