            //=========================================================================
            ////////////Summary by Marc Hong////////////////////////////////////////////
            /// <summary>
            /// 找出某料號的庫存庫量
            /// </summary> 
            /// <param name="varLocat">儲位。</param>
            /// <param name="varMatnr">料號。</param>
            /// <param name="varInsmk">庫別。</param>
            /// <param name="varCharg">版本。</param>
            /// <param name="varSerno">Serno。</param>
            /// <param name="varIndat">入庫日期。</param>
            /// <param name="varLifnr">依Vendor Code統計。</param>
            /// <param name="varRmano">依RMA No統計。</param>
            /// <param name="varDacod">依DateCode統計。</param>
            /// <param name="varLocod">依LockCode統計。</param>
            /// <param name="varInspt">依Inspection Lot統計。</param>
            /// <returns>
            /// int。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objStorageData.QueryMatnrQty(strLocat, strMatnr,strInsmk,strCharg, strIndat);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////
            public int QueryMatnrQty(string varLocat, string varMatnr, string varInsmk, string varCharg, string varSerno, string varIndat, string varLifnr, string varRmano, string varDacod, string varLocod, string varInspt)
            {
                int intResult = 0;
                DataWhitm objWhitm = new DataWhitm(UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();

                alColumns.Clear();
                alColumns.Add(" Sum(MENGE-REQTY+BKQTY) as MENGE ");

                alConditions.Clear();
                alConditions.Add("(MANDT= '" + MANDT + "')");
                alConditions.Add("(COMCD= '" + COMCD + "')");
                alConditions.Add("(WERKS = '" + WERKS + "')");
                alConditions.Add("(LGORT = '" + LGORT + "')");
                alConditions.Add("(LOCAT = '" + varLocat + "')");
                alConditions.Add("(INSMK= '" + varInsmk + "')");
                alConditions.Add("(MATNR = '" + varMatnr + "')");
                alConditions.Add("(CHARG = '" + varCharg + "')");

                if (varSerno.Trim() != "")
                    alConditions.Add("(SERNO = '" + varSerno + "')");

                if (varIndat.Trim() != "")
                    alConditions.Add("(INDAT='" + varIndat + "')");

                if (varLifnr.Trim() != "")
                    alConditions.Add("(LIFNR='" + varLifnr + "')");

                if (varRmano.Trim() != "")
                    alConditions.Add("(RMANO='" + varRmano + "')");

                if (varDacod.Trim() != "")
                    alConditions.Add("(DACOD='" + varDacod + "')");

                if (varLocod.Trim() != "")
                    alConditions.Add("(LOCOD='" + varLocod + "')");

                if (varInspt.Trim() != "")
                    alConditions.Add("(INSPT='" + varInspt + "')");

                try
                {
                    DataTable dtTmp = objWhitm.EntityQuery(alColumns, alConditions, false, false);

                    if (dtTmp.Rows.Count > 0)
                        intResult = Convert.ToInt32(dtTmp.Rows[0]["MENGE"].ToString());
                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryMatnrQty()";
                }
                return intResult;
            }

            #endregion

