            //=========================================================================
            ////////////Summary by Eric Chou////////////////////////////////////////////
            /// <summary>
            /// 查詢倉別庫存資料, 將相同料號的資料Group by在一起strInsmk: 庫別strStartMatnr: 開始料號strEndMatnr: 結束料號
            /// </summary> 
            /// <param name="strInsmk">庫別。</param>
            /// <param name="strStartMatnr">開始料號。</param>
            /// <param name="strEndMatnr">結束料號。</param>
            /// <param name="strMaktx">料號說明。</param>
            /// <param name="strLoadID">LoadID。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objStorageData.QueryStorageData(strInsmk,strStartMatnr,strEndMatnr, strMaktx, strLoadID);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////
            public DataTable QueryStorageData(string strInsmk, string strStartMatnr, string strEndMatnr, string strMaktx, string strLoadID)
            {
                string strSQL = "";

                if (strMaktx == "")
                {
                    strSQL = "Select MANDT, WERKS, LGORT, MATNR, KDMAT, INSMK, sum(MENGE) as MENGE, sum(REQTY) as REQTY, count(*) as TOTAL, MIN(INDAT) as INDAT, (select count(distinct LOCAT) from WHITM as A where A.MANDT=WHITM.MANDT and A.WERKS=WHITM.WERKS and A.LGORT=WHITM.LGORT and A.MATNR=WHITM.MATNR and A.INSMK=WHITM.INSMK) as TOLOC, (select count(distinct LOCAT) from WHITM as A where A.MANDT=WHITM.MANDT and A.WERKS=WHITM.WERKS and A.LGORT=WHITM.LGORT and A.MATNR=WHITM.MATNR and A.INSMK=WHITM.INSMK and MRGID<>'') as MILOC from WHITM where MANDT= '" + MANDT + "' and WERKS = '" + WERKS + "' and LGORT= '" + LGORT + "'  ";
                }
                else
                {
                    strSQL = "Select WHITM.MANDT, WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.KDMAT, WHITM.INSMK, sum(WHITM.MENGE) as MENGE, sum(WHITM.REQTY) as REQTY, count(*) as TOTAL, MIN(WHITM.INDAT) as INDAT, (select count(distinct LOCAT) from WHITM as A where A.MANDT=WHITM.MANDT and A.WERKS=WHITM.WERKS and A.LGORT=WHITM.LGORT and A.MATNR=WHITM.MATNR and A.INSMK=WHITM.INSMK) as TOLOC, (select count(distinct LOCAT) from WHITM as A where A.MANDT=WHITM.MANDT and A.WERKS=WHITM.WERKS and A.LGORT=WHITM.LGORT and A.MATNR=WHITM.MATNR and A.INSMK=WHITM.INSMK and MRGID<>'') as MILOC from WHITM inner join WHPAT on WHITM.MATNR=WHPAT.MATNR where WHITM.MANDT= '" + MANDT + "' and WHITM.WERKS = '" + WERKS + "' and WHITM.LGORT= '" + LGORT + "'  ";
                }

                if (strInsmk != "")
                {
                    strSQL += " and WHITM.INSMK = '" + strInsmk + "'";
                }

                if (strStartMatnr != "" && strEndMatnr != "")
                {
                    strSQL += " and ((WHITM.MATNR like '" + strStartMatnr + "%') or (WHITM.MATNR between '" + strStartMatnr + "%' and '" + strEndMatnr + "%'))";
                }
                else if (strStartMatnr == "" && strEndMatnr != "")
                {
                    strSQL += " and WHITM.MATNR like '" + strEndMatnr + "%'";
                }
                else if (strStartMatnr != "" && strEndMatnr == "")
                {
                    strSQL += " and WHITM.MATNR like '" + strStartMatnr + "%'";
                }

                if (strMaktx != "")
                {
                    strSQL += " and WHPAT.MAKTX like '%" + strMaktx + "%'";
                }

                if (strLoadID.Trim() != "")
                {
                    string strTmpLoadID = "";
                    string[] ArrLoadID = strLoadID.Split(',');
                    for (int i = 0; i < ArrLoadID.Length; i++)
                    {
                        if (strTmpLoadID.Trim() != "")
                            strTmpLoadID += " OR ";
                        strTmpLoadID += " MBLNR = '" + ArrLoadID[i] + "' ";
                    }

                    strSQL += " and exists (select * from whdwn where mtype = 'SDS' and mandt = whitm.mandt and werks = whitm.werks and lgort = whitm.lgort and matnr = whitm.matnr and insmk = whitm.insmk and charg = whitm.charg and (" + strTmpLoadID + "))";
                }

                strSQL += " group by WHITM.MANDT, WHITM.WERKS, WHITM.LGORT, WHITM.MATNR, WHITM.KDMAT, WHITM.INSMK ";

                DataTable dtData = new DataTable();
                try
                {
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();
                }
                catch (System.Exception ex)
                {
                    //this.objSQLAccess.ErrorMessage = ex.Message + "<- QueryStorageData_DateCode ";
                    //throw new System.Exception(ex.Message +"<- QueryStorageData " );

                    ERRMSG = ex.Message + "<- QueryStorageData_DateCode()";
                }
                return dtData;
            }


            #region QueryOnLineOutDataPallet(成品連線出庫by Pallet方式出貨)
