                DataRow[] drFound1;

                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhitm objWhitm = new DataWhitm(UserData);

                for (int i = 0; i < dtOutSource.Rows.Count; i++)
                {
                    int intSourceMenge = int.Parse(dtOutSource.Rows[i]["MENGE"].ToString());

                    //strSQL = "Select MANDT, WERKS, LGORT, LOCAT, '" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR, '" + dtOutSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE, MBLNR as OMBLNR, MATNR, INSMK, CHARG, (MENGE-REQTY) as MENGE, 0 as ALQTY, MRGID, '" + dtOutSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL, '" + dtOutSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL, '" + dtOutSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP, EBELN, LIFNR, RMAK1, INDAT, KDMAT, SERNO " +
                    //    "from WHITM where MANDT= '" + dtOutSource.Rows[i]["MANDT"].ToString() + "' and WERKS= '" + dtOutSource.Rows[i]["WERKS"].ToString() + "' and LGORT= '" + dtOutSource.Rows[i]["LGORT"].ToString() + "' and MATNR= '" + dtOutSource.Rows[i]["MATNR"].ToString() + "' and INSMK= '" + dtOutSource.Rows[i]["INSMK"].ToString() + "' and CHARG= '" + dtOutSource.Rows[i]["CHARG"].ToString() + "' and MRGID='' and MBLNR = '" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' order by INDAT, CRDAT";

                    alColumns.Clear();
                    alConditions.Clear();
                    objWhitm.ResetField();
                    alColumns.Add("MANDT, COMCD, WERKS, LGORT, LOCAT, '" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR, '" + dtOutSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE, MBLNR as OMBLNR, MATNR, INSMK, CHARG, (MENGE-REQTY) as MENGE, 0 as ALQTY, MRGID, '" + dtOutSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL, '" + dtOutSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL, '" + dtOutSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP, EBELN, LIFNR, RMAK1, INDAT, CRDAT, KDMAT, SERNO ");
                    alConditions.Add(" MANDT='" + dtOutSource.Rows[i]["MANDT"].ToString() + "'");
