            #region  查詢某筆Box id的資料，並比對儲位是否相同
            //================================================================================================================
            ////////////Summary by Smose Liao 20091106////////////////////////////////////////////////////////////////////////
            /// <summary>
            /// 查詢某筆Box id的資料，並比對儲位是否相同
            /// </summary> 
            /// <param name="aryLocat">儲位。</param>
            /// <param name="strSerno">Box id。</param>
            /// <returns>
            /// int。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objStorageData.QuerySerNoData(aryLocat, strSerNo);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public DataTable QuerySerNoData(ArrayList aryLocat, string strBoxid)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QuerySerNoData";
                this.ControlMethodParm = "(" + aryLocat + "," + strBoxid + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                string strLocat = "";
                ArrayList CurLocat = new ArrayList();
                DataTable dtData = new DataTable();
                CurLocat = aryLocat;

                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhitm objWhitm = new DataWhitm(UserData);

                //strSQL = "Select * from WHITM where MANDT= '" + MANDT + "' and WERKS = '" + WERKS + "' and SERNO = '" + strSerNo + "'";

                alColumns.Add("*");
                alConditions.Add(" MANDT='" + MANDT + "'");
                alConditions.Add(" WERKS='" + WERKS + "'");
                alConditions.Add(" BOXID='" + strBoxid + "'");

                try
                {
                    dtData = objWhitm.EntityQuery(alColumns, alConditions, false);  //查詢該筆Box id的資料
                    strLocat = dtData.Rows[0]["LOCAT"].ToString();

                    //比對該筆Box id的儲位是否與出庫的儲位相符合  20090629 Smose Liao 
                    for (int i = 0; i < CurLocat.Count; i++)
                    {
                        if (strLocat != CurLocat[i].ToString())
                        {
                            dtData.Rows.Clear();  //該筆Box id的儲位與出庫的儲位不符合
                        }
                    }
                }

                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return dtData;
            }

