            /// </example>
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public int QueryMatnrSernoQty_DateCode(string strLocat, string strMatnr, string strInsmk, string strCharg, string strDacod)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryMatnrSernoQty_DateCode";
                this.ControlMethodParm = "(" + strLocat + "," + strMatnr + "," + strInsmk + "," + strCharg + "," + strDacod + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                int intMenge = 0;
                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhitm objWhitm = new DataWhitm(UserData);

                //string strSQL = "Select sum(MENGE) as MENGE from WHITM where MANDT= '" + MANDT + "' and WERKS = '" + WERKS + "' and LGORT = '" + LGORT + "' and LOCAT = '" + strLocat + "' and INSMK= '" + strInsmk + "' and MATNR = '" + strMatnr + "' and CHARG = '" + strCharg + "'";
                //strSQL = strSQL + " and SERNO like '" + strSerNo.Trim() + "%' ";
                alColumns.Add("sum(MENGE) as MENGE");
                alConditions.Add(" MANDT='" + MANDT + "'");
                alConditions.Add(" COMCD='" + COMCD + "'");
                alConditions.Add(" WERKS='" + WERKS + "'");
                alConditions.Add(" LGORT='" + LGORT + "'");
                alConditions.Add(" LOCAT='" + strLocat + "'");
                alConditions.Add(" INSMK='" + strInsmk + "'");
                alConditions.Add(" MATNR='" + strMatnr + "'");
                alConditions.Add(" DACOD like'" + strDacod.Trim() + "%'");

                try
                {
                    //intMenge = Convert.ToInt32(this.objSQLAccess.GetFieldValue(strSQL).ToString());
                    dtData = objWhitm.EntityQuery(alColumns, alConditions, false);
                    intMenge = Convert.ToInt32(dtData.Rows[0]["MENGE"].ToString());
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return intMenge;
            }

