                this.ControlMethodName = "QueryTransferData";
                this.ControlMethodParm = "(" + strWerks + "," + strLgort_From + "," + strLgort_To + "," + strLocat_From + "," + strLocat_To + "," + strMatnr + "," + dcmMenge + "," + strInsmk + "," + strCharg + ")";
