                //    " from WHITM " +
                //    " where MANDT= '" + strMandt + "' and WERKS= '" + strWerks + "' and LGORT='" + strLgort_From + "' and LOCAT= '" + strLocat_From + "' and MATNR= '" + strMatnr + "' and INSMK='" + strInsmk + "' and CHARG='" + strCharg + "' and MENGE >= " + dcmMenge.ToString();

                DataTable dtData = new DataTable();
