                alColumns.Add("MANDT,WERKS,LGORT as Lgort_From ,'" + strLgort_To + "' as Lgort_To,LOCAT AS LOCAT_From,MATNR,INSMK,CHARG,MENGE,'" + strLocat_To + "' as LOCAT_To, '' as MBLNR,LIFNR,EBELN, INDAT,QCQTY, REFNO, MRGID, ISPTM, RMAK1,CRNAM, CRDAT, MONAM, MODAT ,MENGE as ALQTY ,MBLNR as OMBLNR,'G+' as TRNTP ,'' as KOSTL,'' as ARBPL ");
                alConditions.Add(" MANDT='" + strMandt + "'");
                alConditions.Add(" WERKS='" + strWerks + "'");
                alConditions.Add(" LGORT='" + strLgort_From + "'");
                alConditions.Add(" LOCAT='" + strLocat_From + "'");
                alConditions.Add(" MATNR='" + strMatnr + "'");
