            #region  批次轉倉入庫(指定Locat)
            //====================================================================================
            ////////////Summary by Smose Liao 20091106////////////////////////////////////////////
            /// <summary>
            /// 20080414 批次轉倉入庫(指定Locat)
            /// </summary> 
            /// <param name="dtOutSource">出庫資料。</param>
            /// <returns>
            /// DataSet。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QueryTransferOutDataByLocat(dtOutSource);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////
            public DataSet QueryTransferOutDataByLocat(DataTable dtOutSource)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryTransferOutDataByLocat";
                this.ControlMethodParm = "(' ')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtStorage = new DataTable();
                DataRow drRow;
                DataRow[] drFound;
                DataRow[] drFound1;
                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhitm objWhitm = new DataWhitm(UserData);

                for (int i = 0; i < dtOutSource.Rows.Count; i++)
                {
                    int intSourceMenge = int.Parse(dtOutSource.Rows[i]["MENGE"].ToString());
                    //string strSQL = "Select MANDT, WERKS, LGORT, LOCAT, '" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR, '' as ZEILE, MBLNR as OMBLNR, MATNR, INSMK, CHARG, (MENGE-REQTY) as MENGE, 0 as ALQTY, MRGID," +
                    //    "'' as KOSTL, '' as ARBPL, 'T-' as TRNTP, EBELN, LIFNR, RMAK1, INDAT, KDMAT,'" + dtOutSource.Rows[i]["LGORT_TO"].ToString() + "' as LGORT_TO,'" + dtOutSource.Rows[i]["LOCAT_TO"].ToString() + "' as LOCAT_TO  from WHITM where MANDT= '" + dtOutSource.Rows[i]["MANDT"].ToString() +
                    //    "' and WERKS = '" + dtOutSource.Rows[i]["WERKS"].ToString() + "' and LGORT= '" + dtOutSource.Rows[i]["LGORT_FROM"].ToString() + "' and MATNR= '" + dtOutSource.Rows[i]["MATNR"].ToString() + "' and INSMK= '" + dtOutSource.Rows[i]["INSMK"].ToString() + "' and CHARG= '" +
                    //    dtOutSource.Rows[i]["CHARG"].ToString() + "' and MRGID = '' and LOCAT='" + dtOutSource.Rows[i]["LOCAT_FROM"].ToString() + "' order by INDAT,LOCAT, CRDAT";
                    alConditions.Clear();
                    alColumns.Clear();
                    alColumns.Add("MANDT, WERKS, LGORT, LOCAT, '" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR, '' as ZEILE, MBLNR as OMBLNR, MATNR, INSMK, CHARG, (MENGE-REQTY) as MENGE, 0 as ALQTY, MRGID, '' as KOSTL, '' as ARBPL, 'T-' as TRNTP, EBELN, LIFNR, RMAK1, INDAT, KDMAT,'" + dtOutSource.Rows[i]["LGORT_TO"].ToString() + "' as LGORT_TO,'" + dtOutSource.Rows[i]["LOCAT_TO"].ToString() + "' as LOCAT_TO");
                    alConditions.Add(" MANDT='" + dtOutSource.Rows[i]["MANDT"].ToString() + "'");
                    alConditions.Add(" WERKS='" + dtOutSource.Rows[i]["WERKS"].ToString() + "'");
                    alConditions.Add(" LGORT='" + dtOutSource.Rows[i]["LGORT_FROM"].ToString() + "'");
                    alConditions.Add(" MATNR='" + dtOutSource.Rows[i]["MATNR"].ToString() + "'");
                    alConditions.Add(" INSMK='" + dtOutSource.Rows[i]["INSMK"].ToString() + "'");
                    alConditions.Add(" CHARG='" + dtOutSource.Rows[i]["CHARG"].ToString() + "'");
                    alConditions.Add(" LOCAT='" + dtOutSource.Rows[i]["LOCAT_FROM"].ToString() + "'");
                    alConditions.Add(" MRGID=''");

                    try
                    {
                        dtData = objWhitm.EntityQuery(alColumns, alConditions, false);
                    }
                    catch (CommonObjectsException ex)
                    {
                        //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                        ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                        ControlExceptionType = ex.SourceExceptionType;
                        this.ControlPriority = "1";
                        ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                        throw ex;
                    }//可自行增加要handle的Exception  
                    catch (Exception ex)
                    {
                        ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                        ControlExceptionType = ex.GetType().FullName;
                        this.ControlPriority = "1";
                        ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                        throw new Exception("999");
                    }

                    int intSourceOutMenge = 0;

                    if (i == 0)
                    {
                        dtStorage = dtData.Clone();
                    }

                    dtData.Columns.Add("HAVEMENGE", Type.GetType("System.Int32"));

                    for (int j = 0; j < dtData.Rows.Count; j++)
                    {
                        intSourceOutMenge = 0;
                        ////檢查出庫單據是否都已經出完
                        string strKey = " MBLNR='" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' " +
                                        " and LGORT='" + dtOutSource.Rows[i]["LGORT_FROM"].ToString() + "'  and LOCAT='" + dtOutSource.Rows[i]["LOCAT_FROM"].ToString() + "' " +
                                        " and LGORT_TO='" + dtOutSource.Rows[i]["LGORT_TO"].ToString() + "'  and LOCAT_TO='" + dtOutSource.Rows[i]["LOCAT_TO"].ToString() + "' " +
                                        " and MATNR='" + dtOutSource.Rows[i]["MATNR"].ToString() + "' and INSMK='" + dtOutSource.Rows[i]["INSMK"].ToString() + "' and CHARG='" + dtOutSource.Rows[i]["CHARG"].ToString() + "' ";
                        drFound = dtStorage.Select(strKey);
                        for (int k = 0; k < drFound.Length; k++)
                        {
                            intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                        }
                        if (intSourceMenge > intSourceOutMenge)
                        {
                            int intLocatMblnrTempAlqty = 0;
                            drFound1 = dtStorage.Select("LOCAT='" + dtData.Rows[j]["LOCAT"].ToString() + "' and OMBLNR = '" + dtData.Rows[j]["OMBLNR"].ToString() + "' and MATNR='" + dtData.Rows[j]["MATNR"].ToString() + "' and INSMK='" + dtData.Rows[j]["INSMK"].ToString() + "' and CHARG='" + dtData.Rows[j]["CHARG"].ToString() + "' and MRGID='" + dtData.Rows[j]["MRGID"].ToString() + "'");
                            for (int k = 0; k < drFound1.Length; k++)
                            {
                                intLocatMblnrTempAlqty += Int32.Parse(drFound1[k]["ALQTY"].ToString());
                            }

                            int intBalanceQty = Int32.Parse(dtData.Rows[j]["MENGE"].ToString()) - intLocatMblnrTempAlqty;
                            //MENGE:Locat數量, ALQTY:已出數量
                            //如果儲位還有剩餘數量
                            if (intBalanceQty > 0)
                            {
                                int intLocatAlqty = 0;
                                //如果儲位的剩餘數量小於單據的剩餘數量則全出, 否則出差值
                                if (intSourceMenge - intSourceOutMenge >= intBalanceQty)
                                {
                                    intLocatAlqty = intBalanceQty;
                                }
                                else
                                {
                                    intLocatAlqty = intSourceMenge - intSourceOutMenge;
                                }
                                //如果儲位有出庫則紀錄
                                if (intLocatAlqty > 0)
                                {
                                    drRow = dtStorage.NewRow();
                                    drRow["MANDT"] = dtData.Rows[j]["MANDT"].ToString();
                                    drRow["WERKS"] = dtData.Rows[j]["WERKS"].ToString();
                                    drRow["LGORT"] = dtData.Rows[j]["LGORT"].ToString();
                                    drRow["LOCAT"] = dtData.Rows[j]["LOCAT"].ToString();
                                    drRow["MATNR"] = dtData.Rows[j]["MATNR"].ToString();
                                    drRow["INSMK"] = dtData.Rows[j]["INSMK"].ToString();
                                    drRow["CHARG"] = dtData.Rows[j]["CHARG"].ToString();
                                    drRow["MENGE"] = dtData.Rows[j]["MENGE"].ToString();
                                    drRow["ALQTY"] = intLocatAlqty.ToString();
                                    drRow["MBLNR"] = dtData.Rows[j]["MBLNR"].ToString();
                                    drRow["ZEILE"] = dtData.Rows[j]["ZEILE"].ToString();
                                    drRow["EBELN"] = dtData.Rows[j]["EBELN"].ToString();
                                    drRow["LIFNR"] = dtData.Rows[j]["LIFNR"].ToString();
                                    drRow["OMBLNR"] = dtData.Rows[j]["OMBLNR"].ToString();
                                    drRow["MRGID"] = dtData.Rows[j]["MRGID"].ToString();
                                    drRow["KOSTL"] = dtData.Rows[j]["KOSTL"].ToString();
                                    drRow["ARBPL"] = dtData.Rows[j]["ARBPL"].ToString();
                                    drRow["TRNTP"] = dtData.Rows[j]["TRNTP"].ToString();
                                    drRow["RMAK1"] = dtData.Rows[j]["RMAK1"].ToString();
                                    drRow["INDAT"] = dtData.Rows[j]["INDAT"].ToString();
                                    drRow["KDMAT"] = dtData.Rows[j]["KDMAT"].ToString();
                                    drRow["LOCAT_TO"] = dtData.Rows[j]["LOCAT_TO"].ToString();
                                    drRow["LGORT_TO"] = dtData.Rows[j]["LGORT_TO"].ToString();
                                    dtStorage.Rows.Add(drRow);
                                }
                            }
                        }
                    }
                    //更新單據的總出庫數量
                    intSourceOutMenge = 0;
                    drFound = dtStorage.Select("MBLNR='" + dtOutSource.Rows[i]["MBLNR"].ToString() + "' and LOCAT='" + dtOutSource.Rows[i]["LOCAT_FROM"].ToString() + "' and MATNR='" + dtOutSource.Rows[i]["MATNR"].ToString() + "' and INSMK='" + dtOutSource.Rows[i]["INSMK"].ToString() + "' and CHARG='" + dtOutSource.Rows[i]["CHARG"].ToString() + "'");
                    for (int k = 0; k < drFound.Length; k++)
                    {
                        intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                    }
                    dtOutSource.Rows[i]["ALQTY"] = intSourceOutMenge;


                }

                DataSet dsData = new DataSet();
                DataTable dtData1;
                DataTable dtData2;
                dtData1 = dtOutSource.Copy();
                dtData2 = dtStorage.Copy();
                dtData1.TableName = "Source";
                dtData2.TableName = "Destination";
                dsData.Tables.Add(dtData1);
                dsData.Tables.Add(dtData2);

                return dsData;
            }

            #endregion


