            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            //////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public DataTable QueryGroupIdFinalData(string strGrpid, string strType)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryGroupIdFinalData";
                this.ControlMethodParm = "(" + strGrpid + "," + strType + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                string strSQL = "";
                DataTable dtData = new DataTable();
                ArrayList arySQL = new ArrayList();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhfin objWhFin = new DataWhfin(UserData);
                string strFromTable = string.Empty;

                alColumns.Clear();
                alConditions.Clear();

                alColumns.Add("WHFIN.*, ISNULL(WHDWN.OTQTY,0) AS ALQTY");
                strFromTable = "WHFIN LEFT JOIN WHDWN ON WHDWN.INTID = WHFIN.GRPID AND WHDWN.MATNR = WHFIN.MATNR AND WHDWN.FMATN =WHFIN.FMATN AND WHDWN.WKORD = WHFIN.WKORD";
                //alConditions.Add("(MANDT= '" + MANDT + "')");
                //alConditions.Add("(COMCD= '" + COMCD + "')");
                alConditions.Add("(WHFIN.WERKS= '" + strWerks + "')");
                alConditions.Add("(WHFIN.GRPID= '" + strGrpid + "')");

                try
                {
                    strSQL = objWhFin.ControlGetQuerySql(strFromTable, alColumns, alConditions, false);

                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();

                    if (dtData.Rows.Count > 0)
                    {
                        dtData.Columns.Add("BLACE");
                        for (int i = 0; i < dtData.Rows.Count; i++)
                        {
                            //差異數量 = WHDWN.MENGE - WHFIN.MENGE
                            dtData.Rows[i]["BLACE"] = int.Parse(dtData.Rows[i]["ALQTY"].ToString()) - int.Parse(dtData.Rows[i]["MENGE"].ToString());
                        }
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return dtData;
            }
            #endregion


