                {
                    dtData = objWhdwn.EntityQuery(alColumns, alConditions, false, false);
                    if (dtData.Rows.Count > 0)
                    {
                        dtData = CommonInfo.SortDataTable(dtData, "BWART, MBLNR, MATNR");
