            #region QueryQuarantinedAreaStorageData(查詢待驗儲位庫存資料)
            //===============================================================================================================
            ////////////Summary by Ryan Tsai 20111004///////////////////////////////////////////////////////////////////////
            /// <summary>
            /// 查詢QWMS中的待驗儲位庫存資料(WHECD)
            /// </summary> 
            /// <param name="strLocat">儲位。</param>
            /// <param name="strType">檢案狀態。</param>
            /// <param name="strStartMatnr">起始料號。</param>
            /// <param name="strEndMatnr">結束料號。</param>
            /// <param name="strStartDate">起始時間。</param>
            /// <param name="strEndDate">結束時間。</param>
            /// <param name="strUsrQry">人員工號。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objStorageData.QueryStorageDetailData_DOA(strLocat, strMatnr, strInsmk, strRmano);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            //////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public DataTable QueryQuarantinedAreaStorageData(string strType, string strLocat, string strInspecType, string strStartMatnr, string strEndMatnr, string strStartDate, string strEndDate, string strUsrQry)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryQuarantinedAreaStorageData";
                this.ControlMethodParm = "(" + strLocat + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhecd objWhecd = new DataWhecd(UserData);
                //alColumns.Add("*");
                alColumns.Add("WERKS, LGORT, LOCAT, MATNR, ALQTY, QCTYP, QCUSR, WHUSR, REMAK, CRDAT, VBELN ");
                alConditions.Add(" MANDT='" + strMandt + "'");
                alConditions.Add(" COMCD='" + strComcd + "'");
                if (strWerks != "")
                {
                    alConditions.Add(" WERKS='" + strWerks + "'");
                }
                if (strLgort != "")
                {
                    alConditions.Add(" LGORT='" + strLgort + "'");
                }
                if (strLocat != "")
                {
                    alConditions.Add(" LOCAT='" + strLocat + "'");
                }
                //僅查詢特定料號庫存
                if (strStartMatnr != "" && strEndMatnr != "")
                {
                    //strSQL += " and (MATNR between '" + strStartMatnr + "' and '" + strEndMatnr + "')";
                    alConditions.Add("(MATNR between '" + strStartMatnr + "' and '" + strEndMatnr + "')");
                }
                else if (strStartMatnr == "" && strEndMatnr != "")
                {
                    //strSQL += " and MATNR = '" + strEndMatnr + "'";
                    alConditions.Add("MATNR = '" + strEndMatnr + "'");
                }
                else if (strStartMatnr != "" && strEndMatnr == "")
                {
                    //strSQL += " and MATNR = '" + strStartMatnr + "'";
                    alConditions.Add("MATNR = '" + strStartMatnr + "'");
                }
                //僅查詢未檢驗狀態的庫存
                if (strInspecType == "N")
                {
                    alConditions.Add("( QCTYP is NULL  or QCTYP = '' )");
                }
                if (strInspecType == "O")
                {
                    alConditions.Add("( QCTYP='O' )");
                }
                if (strInspecType == "Y")
                {
                    alConditions.Add("( QCTYP='Y' )");
                }
                //查詢特定時間區間
                if (strStartDate != "" && strEndDate != "")
                {
                    if (strStartDate == strEndDate)
                    {
                        alConditions.Add("(CRDAT between '" + strStartDate + " 00:00:00.000" + "' and '" + strEndDate + " 23:59:59.999" + "')");
                    }
                    else
                    {
                        alConditions.Add("(CRDAT between '" + strStartDate + " 00:00:00.000" + "' and '" + strEndDate + " 23:59:59.999" + "')");
                        //strSQL += " and (CRDAT between '" + strStartDate + "' and '" + strEndDate + "')";
                    }
                }
                else if (strStartDate == "" && strEndDate != "")
                {
                    alConditions.Add("(CRDAT between '" + strEndDate + " 00:00:00.000" + "' and '" + strEndDate + " 23:59:59.999" + "')");
                    //strSQL += " and CRDAT = '" + strEndDate + "'";
                }
                else if (strStartDate != "" && strEndDate == "")
                {
                    //strSQL += " and CRDAT = '" + strStartDate + "'";
                    alConditions.Add("(CRDAT between '" + strStartDate + " 00:00:00.000" + "' and '" + strStartDate + " 23:59:59.999" + "')");
                }
                if (strUsrQry != "")
                {
                    if (strType == "IN")
                    {
                        alConditions.Add("QCUSR = '" + strUsrQry + "'");
                    }
                    if (strType == "QUERY")
                    {
                        alConditions.Add("( WHUSR = '" + strUsrQry + "' OR QCUSR ='" + strUsrQry + "' )");
                    }
                }
                try
                {
                    dtData = objWhecd.EntityQuery(alColumns, alConditions, false, true);
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return dtData;

            }
            #endregion

