            //Query中double-click location detail
            public DataTable QueryStorageStatus4(string WERKS, string LGORT, string FLOOR, string AREA)
            {

                this.ControlMethodName = "QueryStorageStatus4";
                this.ControlMethodParm = "";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    string strSQL = "";
                    string strADD = "";

                    if (FLOOR.Equals(""))
                    {
                        if (AREA.Equals(""))
                        {
                            strADD = "and [FLOOR] is null and AREA is null ";
                        }
                        else
                        {
                            strADD = "and [FLOOR] is null and AREA = '" + AREA + "' ";
                        }
                    }
                    else
                    {
                        if (AREA.Equals(""))
                        {
                            strADD = "and [FLOOR] = '" + FLOOR + "' and AREA is null ";
                        }
                        else
                        {
                            strADD = "and [FLOOR] = '" + FLOOR + "' and AREA = '" + AREA + "' ";
                        }
                    }


                    strSQL = "SELECT a.LOCAT,a.[TYPE],ISNULL(b.TOTAL,0) as TOTAL,ISNULL(b.USED,0) as USED,ISNULL(b.UNUSE,0) as UNUSE,ISNULL(CONVERT(VARCHAR,Round((CONVERT(float,b.USED)/NULLIF(CONVERT(float,b.TOTAL),0))*100,0)),0)+'%' as [USAGE RATE] " +
                             "FROM WHHED a left join WHPAL b on a.MANDT = b.MANDT and a.WERKS = b.WERKS and a.LGORT = b.LGORT " +
                             "and a.LOCAT = b.LOCAT where a.MANDT='" + MANDT + "' and a.COMCD='" + COMCD + "' and a.WERKS='" + WERKS + "' and a.LGORT='" + LGORT + "' " + strADD +
                             "ORDER BY LOCAT";

                    DataTable dtData = new DataTable();
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();
                    return dtData;
                }
                catch (CommonObjectsException ex)
                {

                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }

