                                     "left join WHPAL b on a.MANDT = b.MANDT and a.WERKS = b.WERKS and a.LGORT = b.LGORT and a.LOCAT = b.LOCAT group by a.WERKS,a.LGORT) c";
                            */

                            strSQL = "select c.PLANT,d.[STORAGE(QUANTITY)],c.TOTAL,c.USED,c.UNUSE,ISNULL(CONVERT(VARCHAR,Round((CONVERT(float,USED)/NULLIF(CONVERT(float,TOTAL),0))*100,0)),0)+'%' as [USAGE RATE] " +
                                     "from (SELECT a.WERKS as PLANT,ISNULL(SUM(b.TOTAL),0) as TOTAL,ISNULL(SUM(b.USED),0) as USED, " +
                                     "ISNULL(SUM(b.UNUSE),0) as UNUSE from (select * from WHHED where MANDT='" + MANDT + "' and COMCD='" + COMCD + "') a left join WHPAL b " +
                                     "on a.MANDT = b.MANDT and a.WERKS = b.WERKS and a.LGORT = b.LGORT and a.LOCAT = b.LOCAT " +
                                     "group by a.WERKS) c,(SELECT CTRLNM as PLANT,COUNT(CTRLC1) as [STORAGE(QUANTITY)]  from WHCTRL " +
                                     "WHERE MANDT='" + MANDT + "' and COMCD='" + COMCD + "' and CTRLID='LGORT' group by CTRLNM) d WHERE c.PLANT = d.PLANT";
                        }
                    }

                    DataTable dtData = new DataTable();
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();
                    return dtData;
                }
                catch (CommonObjectsException ex)
                {

                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }

