            #region 更新WHPAL-- by Gary Lee

            public void Update_WHPAL(string LOCAT, int Total, int USED, int UNUSE, int CHANGE, string action, bool TotalChecked, bool BatchImport)
            {

                this.ControlMethodName = "Update_WHPAL";
                this.ControlMethodParm = "";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    string strSQL = "";

                    if (action.Equals("insert"))//insert
                    {
                        strSQL = "insert into WHPAL (MANDT,WERKS,LGORT,LOCAT,USED,UNUSE,TOTAL)" +
                                 "values('" + MANDT + "','" + WERKS + "','" + LGORT + "','" + LOCAT + "'," + USED + "," + UNUSE + "," + Total + ")";
                    }
                    else
                    {
                        if (action.Equals("update"))//update
                        {
                            strSQL = "update WHPAL" +
                                     " set TOTAL=" + Total + ",USED=" + USED + ",UNUSE=" + UNUSE +
                                     " where MANDT='" + MANDT + "'and WERKS='" + WERKS + "'and LGORT='" + LGORT + "' and LOCAT='" + LOCAT + "'";
                        }
                        else//delete
                        {
                            strSQL = "delete from WHPAL" +
                                     " where MANDT='" + MANDT + "'and WERKS='" + WERKS + "'and LGORT='" + LGORT + "' and LOCAT='" + LOCAT + "'";
                        }
                    }

                    #region 紀錄log(WHLOG)

                    string strSQL_Log = "";
                    string TRNTP = "";

                    #region 找出使用的功能

                    if (TotalChecked)//為總棧版數維護
                    {
                        if (CHANGE > 0)
                            TRNTP = "A+";

                        if (CHANGE == 0)
                            TRNTP = "A=";

                        if (CHANGE < 0)
                            TRNTP = "A-";
                    }
                    else
                    {
                        if (!BatchImport)//為已使用棧板維護
                        {
                            if (CHANGE > 0)
                                TRNTP = "U+";

                            if (CHANGE == 0)
                                TRNTP = "U=";

                            if (CHANGE < 0)
                                TRNTP = "U-";
                        }
                        else//批次上傳功能
                            TRNTP = "B";
                    }

                    if (CHANGE < 0 && !BatchImport)
                        CHANGE = Convert.ToInt32(CHANGE.ToString().Substring(1, CHANGE.ToString().Length - 1));

                    #endregion

                    strSQL_Log = "insert into WHLOG (MANDT,WERKS,LGORT,CGCLS,OLOCA,MATNR,TRNTP,MENGE,CRNAM,CRDAT,SERNO,COMCD)" +
                    "values('" + MANDT + "','" + WERKS + "','" + LGORT + "','55','" + LOCAT + "','','" + TRNTP + "','" + CHANGE + "','" + UserData.UserId + "','" + Convert.ToDateTime(System.DateTime.Now).ToString("yyyy/MM/dd HH:mm:ss") + "','','" + UserData.CompanyCode + "')";

                    #endregion

                    ControlHandleDB();
                    ControlSqlAccess.ExecSql(strSQL);
                    ControlSqlAccess.ExecSql(strSQL_Log);
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {

                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }

