            #region WHDCR(新增)-- by Gary Lee

            public void WHDCR_DML(DataTable dt, string Type, string UserName = "")
            {

                this.ControlMethodName = "WHDCR_DML";
                this.ControlMethodParm = "";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    string strSQL = "";
                    string DC_Before = "";
                    string DC_After = "";
                    string LIFNR = "";
                    string strUser = string.IsNullOrEmpty(UserName) ? UserData.UserId : UserName;

                    #region ADD,BATCH

                    if (Type == "ADD" || Type == "BATCH" || Type == "NEW")
                    {
                        for (int i = 0; i < dt.Rows.Count; i++)
                        {
                            DC_Before = dt.Rows[i][1].ToString();
                            DC_After = dt.Rows[i][2].ToString();
                            LIFNR = dt.Rows[i][0].ToString();
                            bool isRepeat = WHDCR_CheckRepeat(LIFNR,DC_After,DC_Before);
                            if (!isRepeat)
                            {
                                strSQL = strSQL + "insert into WHDCR (DC_Before, DC_After, LIFNR, USNAM, CRDAT, MODAT, COMCD) values('" + DC_Before + "','" + DC_After + "','" + LIFNR + "','" + strUser + "','" + Convert.ToDateTime(System.DateTime.Now).ToString("yyyy/MM/dd HH:mm:ss") + "','" + Convert.ToDateTime(System.DateTime.Now).ToString("yyyy/MM/dd HH:mm:ss") + "','" + COMCD + "');";
                            }
                        }
                    }

                    #endregion

                    #region UPDATE

                    if (Type == "MODIFY")
                    {
                        for (int i = 0; i < dt.Rows.Count; i++)
                        {
                            DC_Before = dt.Rows[i][1].ToString();
                            DC_After = dt.Rows[i][2].ToString();
                            LIFNR = dt.Rows[i][0].ToString();
                            strSQL = strSQL + "UPDATE WHDCR SET DC_After='" + DC_After + "',LIFNR ='" + LIFNR + "'   ,USNAM='" + UserData.UserId + "' ,MODAT='" + Convert.ToDateTime(System.DateTime.Now).ToString("yyyy/MM/dd HH:mm:ss") + "' WHERE  DC_Before = '" + DC_Before + "' AND LIFNR='" + LIFNR + "';";

                        }
                    }

                    #endregion

                    #region DELETE

                    if (Type == "DELETE")
                    {
                        for (int i = 0; i < dt.Rows.Count; i++)
                        {
                            DC_Before = dt.Rows[i][1].ToString();
                            DC_After = dt.Rows[i][2].ToString();
                            LIFNR = dt.Rows[i][0].ToString();
                            strSQL = strSQL + "delete from WHDCR WHERE LIFNR ='" + LIFNR + "' and DC_Before = '" + DC_Before + "' and DC_After ='" + DC_After + "';";

                        }
                    }

                    #endregion

                    ControlHandleDB();
                    ControlSqlAccess.ExecSql(strSQL);
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {

                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }

            #region 判断D/C表中是否已有此规则
            public bool WHDCR_CheckRepeat(string LIFNR, string DC_After, string DC_Before)
            {
                string strSQL = "";
                bool bolChecked = false;
                DataTable dtData = new DataTable();

                strSQL = "SELECT * FROM WHDCR WITH(NOLOCK) WHERE LIFNR='" + LIFNR + "' AND DC_Before='" + DC_Before + "' AND DC_After='" + DC_After + "' ";
                try
                {
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL.ToString());
                    ControlSqlAccess.CloseConnection();

                    if (dtData.Rows.Count > 0)
                    {
                        bolChecked = true;
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return bolChecked;
            }
