            #region 治具管理-查詢領退料資訊(QueryRqqReturnInfo)--by Ryan Tsai
            //====================================================================================
            ////////////Summary by Ryan Tsai 20110316////////////////////////////////////////////
            /// <summary>
            /// 依據選取的廠區、倉別、領退料、表單單號, 帶出對應的領退料(BPM)表單申請內容
            /// </summary> 
            /// <param name="WERKS">廠區。</param>
            /// <param name="LGORT">倉別。</param>
            /// <param name="TRNTP">交易型態:領料或退料。</param>
            /// <param name="GRRNO">表單單號。</param>
            /// <returns>DataTable。</returns>
            /// <example>
            /// <code>
            /// <remarks>
            /// 修改記錄：
            /// 修改者-修改日期時間：Ryan 2011/3/25
            /// 修改內容：
            /// </remarks>
            /// </code>
            /// </example>
            //////////////////////////////////////////////////////////////////////////////////////
            public DataTable QueryRqqReturnInfo(string strWerks, string strLgort, string strTRNTP, string strGRRNO)
            {
                DataTable dtData = new DataTable();
                string sqlSelect = "";
                string sqlFrom = "";
                string sqlWhere = "";
                string sqlQuery = "";

                sqlSelect = "select WHGRR.TRNTP, GRRNO, PRTYP, WHGRR.WERKS, WHGRR.MANDT,WHGRR.COMCD ,WHGRR.LGORT,WHGRR.LOCAT ,ITEMNUM , WHGRR.MATNR , WHGRR.INSMK , WHGRR.BKQTY , WHGRR.ALQTY , MENGE , MAKTX,  ";
                sqlSelect += "WHGRR.INDAT,WHGRR.VEDAT , WHITM.MODAT ";

                sqlFrom = "from ( WHGRR inner join WHPAT on WHGRR.MATNR =WHPAT.MATNR ) left join WHITM on  WHGRR.WERKS= WHITM.WERKS and WHGRR.LGORT= WHITM.LGORT and WHGRR.LOCAT= WHITM.LOCAT and WHGRR.INSMK= WHITM.INSMK and WHGRR.MATNR = WHITM.MATNR and WHGRR.MANDT= WHITM.MANDT and WHGRR.COMCD= WHITM.COMCD ";

                sqlWhere = "where WHGRR.TRNTP='" + strTRNTP + "' and "; //交易型態
                sqlWhere += "WHGRR.WERKS='" + strWerks + "' and ";      //廠區
                sqlWhere += "WHGRR.LGORT='" + strLgort + "' and ";      //倉別
                sqlWhere += "WHGRR.GRRNO='" + strGRRNO + "'  ";         //表單編號

                //sqlWhere += "WHGRR.PRTYP= 0";                         //0=未處理

                sqlQuery = sqlSelect + sqlFrom + sqlWhere;
                ControlHandleDB();
                dtData = ControlSqlAccess.GetDataTable(sqlQuery);
                ControlSqlAccess.CloseConnection();

                return dtData;
            }
