                this.ControlMethodParm = "";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }
                string strPallet;

                try
                {
                    string strSQL = "";
                    DataTable dtPallet = new DataTable();

                    strSQL =
                        string.Format(
                            "SELECT DISTINCT MBLNR  FROM dbo.WHDWN WHERE MANDT ='{0}' AND  WERKS ='{1}' AND LGORT ='{2}'   ",
                            Mandt, Werks, Lgort);

                    if (!string.IsNullOrEmpty(CHARG))
                    {
                        strSQL += string.Format(" and CHARG='{0} '", CHARG);
                    }
                    if (!string.IsNullOrEmpty(BOXID))
                    {
                        strSQL += string.Format(" and BOXID='{0}'", BOXID);
                    }
                    if (!string.IsNullOrEmpty(SERNO))
                    {
                        strSQL += string.Format(" and SERNO='{0}' ", SERNO);
                    }


                    ControlHandleDB();
                    dtPallet = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();

                    if (dtPallet.Rows.Count > 0)
                    {
                        strPallet = dtPallet.Rows[0]["MBLNR"].ToString();
                    } //?�查询都没?�信息 返?�空?User ?個动输入 
                    else
                    {
                        strPallet = "";
                    }
                }
                catch (CommonObjectsException ex)
                {

                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return strPallet;
            }

