            #region Add By Michael 20150928 for Film出库
            //Film出库
            public DataSet QueryOnLineOutData_Film(DataTable dtDwnSource, string varLifnr, string varRmano, bool varByDateCode, string varMrgid, bool varByPallet, bool varBySerno)
            {
                DataSet dsResult = new DataSet();
                try
                {
                    DataTable dtOutWhitm = new DataTable();//要出库的库存

                    DataRow drRow;
                    DataRow[] drFound;
                    DataRow[] drFound1;

                    DataWhitm objWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    DataTable dtWhitm = new DataTable();

                    for (int i = 0; i < dtDwnSource.Rows.Count; i++)
                    {
                        #region primary key
                        StringBuilder sbWhdwnKey = new StringBuilder();
                        sbWhdwnKey.Remove(0, sbWhdwnKey.Length);
                        sbWhdwnKey.Append(" MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'");
                        sbWhdwnKey.Append(" and ZEILE='" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "'");
                        sbWhdwnKey.Append(" and MATNR='" + dtDwnSource.Rows[i]["MATNR"].ToString() + "'");
                        sbWhdwnKey.Append(" and INSMK='" + dtDwnSource.Rows[i]["INSMK"].ToString() + "'");
                        sbWhdwnKey.Append(" and CHARG='" + dtDwnSource.Rows[i]["CHARG"].ToString() + "'");
                        #endregion

                        //出库单据数量
                        int intSourceMenge = int.Parse(dtDwnSource.Rows[i]["MENGE"].ToString());

                        #region 找出符合條件且可出库的库存

                        #region 设定 Select

                        alColumns.Clear();
                        alColumns.Add(" MANDT ");
                        alColumns.Add(" COMCD ");
                        alColumns.Add(" WERKS ");
                        alColumns.Add(" LGORT ");
                        alColumns.Add(" LOCAT ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MTYPE"].ToString() + "' as MTYPE ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "' as MBLNR ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE ");
                        alColumns.Add(" MBLNR as OMBLNR ");
                        alColumns.Add(" MATNR ");
                        alColumns.Add(" INSMK ");
                        alColumns.Add(" CHARG ");
                        alColumns.Add(" (MENGE-REQTY+BKQTY) as MENGE "); // REQTY:被保留的數量(不能出掉的) , BKQTY:二次出貨或入庫會用到(出庫為負的,入庫為正的)
                        alColumns.Add(" 0 as ALQTY ");
                        alColumns.Add(" MRGID ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL ");
                        alColumns.Add(" '" + dtDwnSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP ");
                        alColumns.Add(" EBELN ");
                        alColumns.Add(" LIFNR ");
                        alColumns.Add(" RMANO ");
                        alColumns.Add(" RMAK1 ");
                        alColumns.Add(" INDAT ");
                        alColumns.Add(" KDMAT ");
                        alColumns.Add(" CRDAT ");
                        //成品
                        alColumns.Add(" SERNO ");
                        alColumns.Add(" BOXID ");
                        //DateCode
                        alColumns.Add(" VEDAT ");
                        alColumns.Add(" DACOD ");
                        alColumns.Add(" LOCOD ");
                        alColumns.Add(" INSPT ");
                        //EPAD
                        alColumns.Add(" PKDAT ");

                        #endregion

                        #region 設定 Condition

                        alConditions.Clear();
                        alConditions.Add("(MANDT= '" + dtDwnSource.Rows[i]["MANDT"].ToString() + "')");
                        alConditions.Add("(COMCD= '" + dtDwnSource.Rows[i]["COMCD"].ToString() + "')");
                        alConditions.Add("(WERKS= '" + dtDwnSource.Rows[i]["WERKS"].ToString() + "')");
                        alConditions.Add("(LGORT= '" + dtDwnSource.Rows[i]["LGORT"].ToString() + "')");
                        alConditions.Add("(MATNR= '" + dtDwnSource.Rows[i]["MATNR"].ToString() + "')");
                        alConditions.Add("(INSMK= '" + dtDwnSource.Rows[i]["INSMK"].ToString() + "')");
                        alConditions.Add("(CHARG= '" + dtDwnSource.Rows[i]["CHARG"].ToString() + "')");

                        #endregion

                        string strSql = objWhitm.EntityGetQuerySql(alColumns, alConditions, false, false);
                        dtWhitm = objWhitm.EntityQuery(alColumns, alConditions, false, false);
                        #endregion

                        #region 出库规则
                        string strOrderBy = "";
                        strOrderBy = "INDAT, LOCAT, CRDAT";//正常出庫：入庫日期, 儲位, 建立日期
                        dtWhitm = CommonInfo.SortDataTable(dtWhitm, strOrderBy);
                        #endregion

                        int intSourceOutMenge = 0;

                        if (i == 0)
                        {
                            dtOutWhitm = dtWhitm.Clone();
                            dtOutWhitm.Columns.Add("SQTY", typeof(string));
                        }

                        for (int j = 0; j < dtWhitm.Rows.Count; j++)
                        {

                            intSourceOutMenge = 0;

                            //檢查出庫單據是否都已經出完
                            #region 查看該筆單據已經出多少了

                            drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                            for (int k = 0; k < drFound.Length; k++)
                            {
                                intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                            }
                            #endregion

                            if (intSourceMenge > intSourceOutMenge)//intSourceMenge:whdwn上要出的數量, intSourceMenge:已經出的數量
                            {//如果還沒出完

                                int intLocatMblnrTempAlqty = 0;

                                #region 待出库储位库存key

                                StringBuilder sbWhitmKey = new StringBuilder();
                                sbWhitmKey.Remove(0, sbWhitmKey.Length);
                                sbWhitmKey.Append(" LOCAT='" + dtWhitm.Rows[j]["LOCAT"].ToString() + "'");
                                sbWhitmKey.Append(" and OMBLNR = '" + dtWhitm.Rows[j]["OMBLNR"].ToString() + "'");
                                sbWhitmKey.Append(" and MATNR='" + dtWhitm.Rows[j]["MATNR"].ToString() + "'");
                                sbWhitmKey.Append(" and INSMK='" + dtWhitm.Rows[j]["INSMK"].ToString() + "'");
                                sbWhitmKey.Append(" and CHARG='" + dtWhitm.Rows[j]["CHARG"].ToString() + "'");
                                sbWhitmKey.Append(" and SERNO='" + dtWhitm.Rows[j]["SERNO"].ToString() + "'");
                                sbWhitmKey.Append(" and BOXID='" + dtWhitm.Rows[j]["BOXID"].ToString() + "'");

                                #endregion

                                drFound1 = dtOutWhitm.Select(sbWhitmKey.ToString());
                                for (int k = 0; k < drFound1.Length; k++)
                                {
                                    intLocatMblnrTempAlqty += Int32.Parse(drFound1[k]["ALQTY"].ToString());
                                }

                                int intBalanceQty = Int32.Parse(dtWhitm.Rows[j]["MENGE"].ToString()) - intLocatMblnrTempAlqty;
                                //MENGE:Locat數量, ALQTY:已出數量
                                //如果儲位還有剩餘數量
                                if (intBalanceQty > 0)
                                {
                                    int intLocatAlqty = 0;
                                    //如果儲位的剩餘數量小於單據的剩餘數量則全出, 否則出差值
                                    if (intSourceMenge - intSourceOutMenge >= intBalanceQty)
                                    {
                                        intLocatAlqty = intBalanceQty;
                                    }
                                    else
                                    {
                                        intLocatAlqty = intSourceMenge - intSourceOutMenge;
                                    }
                                    //如果儲位有出庫則紀錄
                                    if (intLocatAlqty > 0)
                                    {
                                        #region 出库记录
                                        drRow = dtOutWhitm.NewRow();
                                        drRow["MANDT"] = dtWhitm.Rows[j]["MANDT"].ToString();
                                        drRow["COMCD"] = dtWhitm.Rows[j]["COMCD"].ToString();
                                        drRow["WERKS"] = dtWhitm.Rows[j]["WERKS"].ToString();
                                        drRow["LGORT"] = dtWhitm.Rows[j]["LGORT"].ToString();
                                        drRow["LOCAT"] = dtWhitm.Rows[j]["LOCAT"].ToString();
                                        drRow["MATNR"] = dtWhitm.Rows[j]["MATNR"].ToString();
                                        drRow["INSMK"] = dtWhitm.Rows[j]["INSMK"].ToString();
                                        drRow["CHARG"] = dtWhitm.Rows[j]["CHARG"].ToString();
                                        drRow["MENGE"] = dtWhitm.Rows[j]["MENGE"].ToString();
                                        drRow["ALQTY"] = intLocatAlqty.ToString();
                                        drRow["MTYPE"] = dtWhitm.Rows[j]["MTYPE"].ToString();
                                        drRow["MBLNR"] = dtWhitm.Rows[j]["MBLNR"].ToString();
                                        drRow["ZEILE"] = dtWhitm.Rows[j]["ZEILE"].ToString();
                                        drRow["EBELN"] = dtWhitm.Rows[j]["EBELN"].ToString();
                                        drRow["LIFNR"] = dtWhitm.Rows[j]["LIFNR"].ToString();
                                        drRow["RMANO"] = dtWhitm.Rows[j]["RMANO"].ToString();
                                        drRow["OMBLNR"] = dtWhitm.Rows[j]["OMBLNR"].ToString();
                                        drRow["MRGID"] = dtWhitm.Rows[j]["MRGID"].ToString();
                                        drRow["KOSTL"] = dtWhitm.Rows[j]["KOSTL"].ToString();
                                        drRow["ARBPL"] = dtWhitm.Rows[j]["ARBPL"].ToString();
                                        drRow["TRNTP"] = dtWhitm.Rows[j]["TRNTP"].ToString();
                                        drRow["RMAK1"] = dtWhitm.Rows[j]["RMAK1"].ToString();
                                        drRow["INDAT"] = dtWhitm.Rows[j]["INDAT"].ToString();
                                        //KDMAT欄位
                                        drRow["KDMAT"] = dtWhitm.Rows[j]["KDMAT"].ToString();
                                        //成品
                                        drRow["SERNO"] = dtWhitm.Rows[j]["SERNO"].ToString();
                                        drRow["BOXID"] = dtWhitm.Rows[j]["BOXID"].ToString();
                                        //DateCode
                                        drRow["VEDAT"] = dtWhitm.Rows[j]["VEDAT"].ToString();
                                        drRow["DACOD"] = dtWhitm.Rows[j]["DACOD"].ToString();
                                        drRow["LOCOD"] = dtWhitm.Rows[j]["LOCOD"].ToString();
                                        drRow["INSPT"] = dtWhitm.Rows[j]["INSPT"].ToString();
                                        drRow["PKDAT"] = dtWhitm.Rows[j]["PKDAT"].ToString();

                                        //不良品数量
                                        StringBuilder strReturn = new StringBuilder();
                                        strReturn.AppendFormat(@"SELECT MENGE FROM WHITM WITH(NOLOCK) 
                                                                WHERE MANDT = '{0}' AND COMCD ='{1}' AND WERKS = '{2}'
                                                                  AND LGORT = '{3}' AND LOCAT = '{4}' AND MATNR = '{5}'
                                                                  AND INSMK = 'S' AND CHARG = '{6}' AND BOXID = '{7}' ",
                                                                 dtWhitm.Rows[j]["MANDT"].ToString(), dtWhitm.Rows[j]["COMCD"].ToString(), dtWhitm.Rows[j]["WERKS"].ToString(),
                                                                 dtWhitm.Rows[j]["LGORT"].ToString(), dtWhitm.Rows[j]["LOCAT"].ToString(), dtWhitm.Rows[j]["MATNR"].ToString(),
                                                                 dtWhitm.Rows[j]["CHARG"].ToString(), dtWhitm.Rows[j]["BOXID"].ToString());
                                        ControlHandleDB();
                                        DataTable dt = ControlSqlAccess.GetDataTable(strReturn.ToString());
                                        ControlSqlAccess.CloseConnection();
                                        if (dt != null && dt.Rows.Count > 0)
                                            drRow["SQTY"] = dt.Rows[0]["MENGE"].ToString();

                                        dtOutWhitm.Rows.Add(drRow);
                                        #endregion
                                    }
                                }
                            }
                            else
                                break;
                        }
                        //更新單據的總出庫數量
                        intSourceOutMenge = 0;

                        drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                        for (int k = 0; k < drFound.Length; k++)
                        {
                            intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                        }
                        dtDwnSource.Rows[i]["ALQTY"] = intSourceOutMenge;

                    }

                    if (dtDwnSource.DataSet != null)
                        dtDwnSource.DataSet.Tables.Remove(dtDwnSource);

                    dtDwnSource.TableName = "Source";
                    dtOutWhitm.TableName = "Destination";
                    dsResult.Tables.Add(dtDwnSource);
                    dsResult.Tables.Add(dtOutWhitm);

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryOnLineOutData_Film()";
                }

                return dsResult;
            }

            #endregion

            #region 查询华为H95DateCode
            public DataTable QueryH95DateCodeDate(string Werks, string Matnr, string Insmk)
            {
                StringBuilder sbSql = new StringBuilder();
                sbSql.Append("SELECT WHHDC.MATNR,WHHDC.INSMK,WHHDC.StockTime,WHHDC.AdvanceWarningTime FROM WHHDC INNER JOIN WHITM ON WHITM.MATNR=WHHDC.MATNR WHERE  ");
                sbSql.AppendFormat(" WERKS='{0}' ", Werks);
                sbSql.AppendFormat("AND WHHDC.MATNR='{0}' ", Matnr);
                sbSql.AppendFormat("AND WHHDC.INSMK='{0}' ", Insmk);
                sbSql.AppendFormat("GROUP BY WHHDC.MATNR,WHHDC.INSMK,WHHDC.StockTime,WHHDC.AdvanceWarningTime");

                DataTable result = new DataTable();
                try
                {
                    base.ControlHandleDB();
                    result = this.ControlSqlAccess.GetDataTable(sbSql.ToString());
                    this.ControlSqlAccess.CloseConnection();
                }
                catch (Exception ex)
                {
                    this.ERRMSG = ex.Message + "<- QueryH95DateCodeDate()";
                }
                return result;
            }
            public DataTable QueryH95DateCodeDateExtend(string Werks, string Lgort, string Matnr, string Insmk, string Dacod)
            {
                StringBuilder sbSql = new StringBuilder();
                sbSql.Append("SELECT WHITM.WERKS,WHITM.LGORT,WHITM.MATNR,WHITM.INSMK,WHITM.DACOD,WHETDC.ETDAT,WHETDC.ARETDAT,(SELECT StockTime FROM WHHDC WHERE  ");
                sbSql.AppendFormat(" MATNR='{0}' ", Matnr);
                sbSql.AppendFormat("') AS StockTime FROM WHETDC RIGHT JOIN WHITM ON WHETDC.MATNR=WHITM.MATNR AND WHETDC.DACOD=WHITM.DACOD  WHERE");
                sbSql.AppendFormat(" WHITM.WERKS='{0}' ", Werks);
                if (!string.IsNullOrEmpty(Lgort))
                {
                    sbSql.AppendFormat(" AND WHITM.LGORT='{0}' ", Lgort);
                }
                sbSql.AppendFormat("AND WHITM.MATNR='{0}' ", Matnr);
                sbSql.AppendFormat("AND WHITM.INSMK='{0}' ", Insmk);
                sbSql.AppendFormat("AND WHITM.DACOD='{0}' ", Dacod);
                sbSql.AppendFormat("GROUP BY WHITM.WERKS,WHITM.LGORT,WHITM.MATNR,WHITM.INSMK,WHITM.DACOD,WHETDC.ETDAT,WHETDC.ARETDAT");

                DataTable result = new DataTable();
                try
                {
                    base.ControlHandleDB();
                    result = this.ControlSqlAccess.GetDataTable(sbSql.ToString());
                    this.ControlSqlAccess.CloseConnection();
                }
                catch (Exception ex)
                {
                    this.ERRMSG = ex.Message + "<- QueryH95DateCodeDateExtend()";
                }
                return result;
            }
