            #region 查詢祥龙解欠备料信息
            public DataTable QuerySimulationOutConfirmData(string varWerks, string varLgort, string varGrpid, string varKittingUser, string strStartDate, string strEndDate)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QuerySimulationOutConfirmData";
                this.ControlMethodParm = "(" + varWerks + "," + varLgort + "," + varGrpid + "," + varKittingUser + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtResult = new DataTable();
                StringBuilder sbSQL = new StringBuilder();

                //已备料部分
                sbSQL.Append(@"SELECT DISTINCT A.MANDT,A.COMCD,A.WERKS,A.LGORT,CONVERT(VARCHAR(100),A.CRDAT,112)AS CRDAT,A.GRPID,A.USRNM,ISNULL(B.ITEM,0) AS ITEM,ISNULL(C.ITEM,0) AS FITEM,(ISNULL(B.ITEM,0))-(ISNULL(C.ITEM,0)) AS PITEM,
                        CASE WHEN CONVERT(VARCHAR(100),A.CRDAT,114)>'08:00:00:000' AND CONVERT(VARCHAR(100),A.CRDAT,114)<'20:00:00:000' THEN N'白班' WHEN CONVERT(VARCHAR(100),A.CRDAT,114)>'00:00:00:000' AND CONVERT(VARCHAR(100),A.CRDAT,114)<'08:00:00:000' AND CONVERT(VARCHAR(100),A.CRDAT,114)>'20:00:00:000' AND CONVERT(VARCHAR(100),A.CRDAT,114)<'23:59:59:999' THEN N'夜班' END AS CLASS 
                        FROM WHDTB AS A WITH(NOLOCK) LEFT JOIN (SELECT GRPID,COUNT(*) AS ITEM,USRNM FROM WHDTB WITH(NOLOCK) WHERE WERKS='" +
                             varWerks + "' GROUP BY GRPID,USRNM) AS B ON A.GRPID=B.GRPID AND A.USRNM=B.USRNM " +
                             "LEFT JOIN (SELECT GRPID,COUNT(*) AS ITEM,USRNM FROM WHDTB WITH(NOLOCK) WHERE WERKS='" + varWerks +
                             "' AND FLAGE='Y' GROUP BY GRPID,USRNM) AS C ON A.GRPID=C.GRPID AND A.USRNM=C.USRNM");

                if (varLgort == "" && varGrpid == "" && varKittingUser == "") //AllLgortCheck
                {
                    sbSQL.AppendFormat(" WHERE A.WERKS='" + varWerks + "' ");
                }
                else if (varLgort != "" && varGrpid == "" && varKittingUser == "") //AllSendIdCheck
                {
                    sbSQL.AppendFormat(@" WHERE A.WERKS='" + varWerks + "' AND A.LGORT='" + varLgort + "'");
                }
                else if (varLgort != "" && varGrpid != "" && varKittingUser != "")
                {
                    sbSQL.AppendFormat(@" WHERE A.WERKS='" + varWerks + "' AND A.LGORT='" + varLgort + "' AND A.GRPID='" + varGrpid + "' AND A.USRNM='" + varKittingUser + "' ");
                }
                sbSQL.AppendFormat(@" AND CRDAT BETWEEN '" + strStartDate + "' AND '" + strEndDate + "  23:59:59' ");
                //未使用PAD备料部分
                sbSQL.AppendFormat(@" UNION ALL SELECT DISTINCT S.MANDT,S.COMCD,S.WERKS,D.LGORT,CONVERT(VARCHAR(100),S.CRDAT,112) AS CRDAT,GRPID,'' AS USRNM,'' AS ITEM,'' AS FITEM,'' AS PITEM,
                    CASE WHEN CONVERT(VARCHAR(100),S.CRDAT,114)>'08:00:00:000' AND CONVERT(VARCHAR(100),S.CRDAT,114)<'20:00:00:000' THEN N'白班' WHEN CONVERT(VARCHAR(100),S.CRDAT,114)>'00:00:00:000' AND  CONVERT(VARCHAR(100),S.CRDAT,114)<'08:00:00:000' THEN N'夜班' WHEN CONVERT(VARCHAR(100),S.CRDAT,114)>'20:00:00:000' AND CONVERT(VARCHAR(100),S.CRDAT,114)<'23:59:59:999' THEN N'夜班' END AS CLASS FROM WHSMT S WITH(NOLOCK)");
                sbSQL.AppendFormat(@" INNER JOIN WHDWN D WITH(NOLOCK) ON GRPID=INTID WHERE S.CRDAT BETWEEN '" + strStartDate + "' AND '" + strEndDate + " 23:59:59.999' ");
                if (varLgort == "" && varGrpid == "" && varKittingUser == "")
                {
                    sbSQL.AppendFormat(@" AND S.WERKS='" + varWerks + "'");
                }
                else if (varLgort != "" && varGrpid == "" && varKittingUser == "")
                {
                    sbSQL.AppendFormat(@" AND S.WERKS='" + varWerks + "' AND D.LGORT='" + varLgort + "'");
                }
                sbSQL.AppendFormat(@" AND GRPID NOT IN(SELECT DISTINCT GRPID FROM WHDTB WITH(NOLOCK) WHERE CRDAT BETWEEN '" + strStartDate + "' AND '" + strEndDate + " 23:59:59.999' ");
                if (varLgort == "" && varGrpid == "" && varKittingUser == "")
                {
                    sbSQL.AppendFormat(@" AND WERKS='" + varWerks + "')");
                }
                else if (varLgort != "" && varGrpid == "" && varKittingUser == "")
                {
                    sbSQL.AppendFormat(@" AND WERKS='" + varWerks + "' AND LGORT='" + varLgort + "')");
                }
                sbSQL.AppendFormat(@" ORDER BY CRDAT");

                try
                {
                    ControlHandleDB();
                    dtResult = ControlSqlAccess.GetDataTable(sbSQL.ToString());
                    ControlSqlAccess.CloseConnection();
                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryGroupIdData()";
                }

                return dtResult;
            }
            #endregion

