            public DataTable QueryStoragePalletData(string strPallet, string type)
            {
                DataWhitm objWhitm = new DataWhitm(UserData);

                string strFrom = " WHITM With(Nolock) ";

                ArrayList alColumns = new ArrayList();
                ArrayList alQuestionCondtion = new ArrayList();

                alColumns.Add("MANDT");
                alColumns.Add("COMCD");
                alColumns.Add("WERKS");
                alColumns.Add("LGORT");
                alColumns.Add("LOCAT");
                alColumns.Add("MATNR");
                alColumns.Add("INSMK");
                alColumns.Add("CHARG");
                alColumns.Add("MENGE");

                alColumns.Add("QCQTY");
                alColumns.Add("MBLNR");
                alColumns.Add("'' as OMBLNR");
                alColumns.Add("'' as ZEILE");
                alColumns.Add("MRGID");
                alColumns.Add("'' as KOSTL");
                alColumns.Add("'' as ARBPL");
                alColumns.Add("'' as TRNTP");
                alColumns.Add("EBELN");
                alColumns.Add("LIFNR");
                alColumns.Add("RMAK1");
                alColumns.Add("INDAT");
                alColumns.Add("VEDAT");
                alColumns.Add("REFNO");
                alColumns.Add("Convert(varchar(20), CRDAT, 120) as CRDAT");
                alColumns.Add("KDMAT");
                alColumns.Add("SERNO");
                alColumns.Add("LOCOD");
                alColumns.Add("INSPT");
                alColumns.Add("DACOD");
                alColumns.Add("BOXID");
                alColumns.Add("RMANO");
                alColumns.Add("PKDAT");
                //判断是combine 还是split
                if (type.ToLower().Contains("combine"))
                {
                    alColumns.Add("0 as BalanceQty");
                    alColumns.Add("MENGE as ALQTY");
                }
                else
                {
                    alColumns.Add("MENGE as BalanceQty");
                    alColumns.Add("0 as ALQTY");
                }

                alColumns.Add("0 as AddQty");


                alQuestionCondtion.Add("MANDT = '" + MANDT + "'");
                alQuestionCondtion.Add("COMCD = '" + COMCD + "'");
                alQuestionCondtion.Add("WERKS = '" + WERKS + "'");
                alQuestionCondtion.Add("LGORT = '" + LGORT + "'");


                if (strPallet != "")
                {
                    //strSQL += " and LOCAT= '" + strLocat + "'";
                    alQuestionCondtion.Add("MBLNR = '" + strPallet + "'");
                }



                DataTable dtData = new DataTable();
                try
                {
                    //ControlHandleDB();
                    //string strSQL = objWhitm.ControlGetQuerySql(strFrom, alColumns, alQuestionCondtion, true);
                    dtData = objWhitm.ControlQuery(strFrom, alColumns, alQuestionCondtion, true);
                    //dtData = ControlSqlAccess.GetDataTable(strSQL);
                    //ControlSqlAccess.CloseConnection();
                }
                catch (System.Exception ex)
                {
                    //this.objSQLAccess.ErrorMessage = ex.Message + "<- QueryStorageDetailData ";
                    //throw new System.Exception(ex.Message +"<- QueryStorageDetailData " );

                    ERRMSG = ex.Message + "<- QueryStorageDetailData()";
                }
                return dtData;
            }
