                {
                    //查询储位中料号ID
                    strSQL.AppendFormat(
                        @"SELECT MANDT, COMCD,WERKS, LGORT, LOCAT, MBLNR, '' AS ZEILE, MBLNR as OMBLNR, MATNR, INSMK, CHARG, (MENGE-REQTY) as MENGE, 0 as ALQTY, MRGID,SERNO,
