                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                dtStorage = dtData.Clone();

                int intLocatMenge = 0;
                for (int i = 0; i < dtData.Rows.Count; i++)
                {
                    if (!string.IsNullOrEmpty(varQty))
                    {
                        if (!varQty.Equals(""))
                        {
                            intSourceMenge = Convert.ToInt32(varQty);
                            if (intLocatMenge + int.Parse(dtData.Rows[i]["MENGE"].ToString()) <= intSourceMenge)
                            {
                                intLocatMenge += int.Parse(dtData.Rows[i]["MENGE"].ToString());
                                dtData.Rows[i]["ALQTY"] = dtData.Rows[i]["MENGE"].ToString();
                            }
                            else
                            {
                                dtData.Rows[i]["ALQTY"] = intSourceMenge - intLocatMenge;
                                intLocatMenge += intSourceMenge - intLocatMenge;
                            }
                        }
                    }

                    if (dtData.Rows[i]["ALQTY"].ToString() != "0")
                    {
                        drRow = dtStorage.NewRow();
                        drRow["MANDT"] = dtData.Rows[i]["MANDT"].ToString();
                        drRow["COMCD"] = dtData.Rows[i]["COMCD"].ToString();
