                        drRow["MENGE"] = dtData.Rows[i]["MENGE"].ToString();
                        drRow["ALQTY"] = dtData.Rows[i]["ALQTY"].ToString();
                        drRow["MBLNR"] = dtData.Rows[i]["MBLNR"].ToString();
                        drRow["ZEILE"] = dtData.Rows[i]["ZEILE"].ToString();
                        drRow["EBELN"] = dtData.Rows[i]["EBELN"].ToString();
                        drRow["LIFNR"] = dtData.Rows[i]["LIFNR"].ToString();
                        drRow["OMBLNR"] = dtData.Rows[i]["OMBLNR"].ToString();
                        drRow["MRGID"] = dtData.Rows[i]["MRGID"].ToString();
                        drRow["SERNO"] = dtData.Rows[i]["SERNO"].ToString();
                        drRow["KOSTL"] = dtData.Rows[i]["KOSTL"].ToString();
                        drRow["ARBPL"] = dtData.Rows[i]["ARBPL"].ToString();
                        drRow["TRNTP"] = dtData.Rows[i]["TRNTP"].ToString();
                        drRow["RMAK1"] = dtData.Rows[i]["RMAK1"].ToString();
                        drRow["INDAT"] = dtData.Rows[i]["INDAT"].ToString();
                        drRow["KDMAT"] = dtData.Rows[i]["KDMAT"].ToString();
                        drRow["DACOD"] = dtData.Rows[i]["DACOD"].ToString();
                        dtStorage.Rows.Add(drRow);
                    }
                    for (int j = 0; j < dtOutSource.Rows.Count; j++)
                    {
                        if (dtData.Rows[i]["MBLNR"].ToString() == dtOutSource.Rows[j]["MBLNR"].ToString())
                        {
                            if (dtData.Rows[i]["ALQTY"].ToString() != "0")
                            {
                                dtOutSource.Rows[j]["ALQTY"] = dtData.Rows[i]["ALQTY"].ToString();
                            }
                        }
                    }
                }
                DataSet dsData = new DataSet();
                DataTable dtData1;
                DataTable dtData2;
                dtData1 = dtOutSource.Copy();
                dtData2 = dtStorage.Copy();
                dtData1.TableName = "Source";
                dtData2.TableName = "Destination";
                dsData.Tables.Add(dtData1);
                dsData.Tables.Add(dtData2);
                return dsData;

