                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return dtData;
            }

            #endregion

            #region 联机出库查询库存信息
            public DataSet QueryOnLineOutData(DataTable dtDwnSource, string varLifnr, string varRmano, bool varByDateCode, string varMrgid, bool bolByPallet, bool bolBySerno)
            {
                DataSet dsResult = new DataSet();
                try
                {
                    DataTable dtOutWhitm = new DataTable();//要出庫的庫存數據

                    DataRow drRow;
                    DataRow[] drFound;
                    DataRow[] drFound1;

                    DataWhitm objWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    DataTable dtWhitm = new DataTable();
                    StringBuilder sbSql = new StringBuilder();

                    for (int i = 0; i < dtDwnSource.Rows.Count; i++)
                    {
                        #region 組單據的Key
                        StringBuilder sbWhdwnKey = new StringBuilder();
                        sbWhdwnKey.Remove(0, sbWhdwnKey.Length);
                        sbWhdwnKey.Append(" MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'");
                        sbWhdwnKey.Append(" and ZEILE='" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "'");
                        sbWhdwnKey.Append(" and MATNR='" + dtDwnSource.Rows[i]["MATNR"].ToString() + "'");
                        sbWhdwnKey.Append(" and INSMK='" + dtDwnSource.Rows[i]["INSMK"].ToString() + "'");
                        sbWhdwnKey.Append(" and CHARG='" + dtDwnSource.Rows[i]["CHARG"].ToString() + "'");
                        #endregion

                        //出庫單據的數量
                        int intSourceMenge = int.Parse(dtDwnSource.Rows[i]["MENGE"].ToString());
                        string strIQCWerks = dtDwnSource.Rows[i]["WERKS"].ToString();                        
                        string strTranLgort = "";
                        if (dtDwnSource.Columns.Contains("UMLGO"))
                        {
                            strTranLgort = dtDwnSource.Rows[i]["UMLGO"].ToString();//转入仓
                        }                          
                        #region 查询库存SQL
                        sbSql.Length = 0;
                        sbSql.AppendLine(" SELECT MANDT,W.COMCD,WERKS,LGORT,LOCAT,MBLNR as OMBLNR,"
                        + "  '" + dtDwnSource.Rows[i]["MTYPE"].ToString() + "'  as MTYPE, "
                        + "  '" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'  as MBLNR,"
                        + "  '" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "' as ZEILE,"
                        + "  '" + dtDwnSource.Rows[i]["KOSTL"].ToString() + "' as KOSTL, "
                        + "  '" + dtDwnSource.Rows[i]["ARBPL"].ToString() + "' as ARBPL ,"
                        + "  '" + dtDwnSource.Rows[i]["TRNTP"].ToString() + "' as TRNTP ,"
                        + " W.MATNR, M.DECITEM ,INSMK, CHARG,(MENGE-REQTY+BKQTY) as MENGE,0 as ALQTY,MRGID,"
                        + "EBELN,LIFNR,RMANO,RMAK1,INDAT,  KDMAT,CRDAT,SERNO,BOXID,VEDAT,DACOD,LOCOD,INSPT,PKDAT,"
                        + "SUBSTRING(PKDAT,0,5) + RIGHT('0'+CONVERT(VARCHAR(2), DATEPART(month,PKDAT)), 2) + RIGHT('0'+CONVERT(VARCHAR(2), DATEPART(day,PKDAT)), 2) AS NEW_PKDAT, "
                        + "ExpiryDate AS EXPDAT,TASKID,CONFIG,CASE WHEN MCDAT IS NULL THEN FORMAT(DATEADD(day, 1, GETDATE()),'yyyyMMdd') ELSE  MCDAT END AS MCDAT"
                        + " FROM DBO.WHITM W   LEFT JOIN MATDIC AS M ON W.COMCD=M.COMCD AND  W.MATNR=M.MATNR   ");

                        sbSql.AppendLine(" WHERE  (MANDT= '" + MANDT + "') And (W.COMCD= '" + COMCD + "') And (WERKS= '" + WERKS + "') And (LGORT= '" + LGORT + "') "
                          + " And (W.MATNR= '" + dtDwnSource.Rows[i]["MATNR"].ToString() + "') And (INSMK= '" + dtDwnSource.Rows[i]["INSMK"].ToString() + "') "
                          + " And (CHARG= '" + dtDwnSource.Rows[i]["CHARG"].ToString() + "')  And (MRGID='" + varMrgid.Trim() + "')  ");

                        if (!string.IsNullOrEmpty(varLifnr))
                        {
                            sbSql.AppendFormat("  AND LIFNR ='" + varLifnr.Trim() + "' ");
                        }
                        if (!string.IsNullOrEmpty(varRmano))
                        {
                            sbSql.AppendFormat("  AND RMANO ='" + varRmano.Trim() + "' ");
                        }
                        if (bolByPallet)
                        {
                            sbSql.AppendFormat(" AND  MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'  ");
                        }
                        if (bolBySerno)
                        {
                            sbSql.AppendFormat("  AND  SERNO='" + dtDwnSource.Rows[i]["SERNO"].ToString() + "' ");
                        }
                        if (COMCD == "9200" && WERKS == "CS20" && LGORT == "TW35")
                        {
                            sbSql.AppendFormat("  AND  DATEDIFF(MI,PKDAT,GETDATE()) >= 1440) ");
                        }
                        //strIQCLgort 转出仓 
                        //转入待验仓、不良品仓都卡控加锁库存
                        if (CheckStorageInType(strIQCWerks, strTranLgort, "IQC LGORT") || CheckStorageInType(strIQCWerks, strTranLgort, "DEF LGORT"))                    
                        {
                            sbSql.AppendFormat("  AND LOCKED ='Y' ");
                        }
                        else
                        {
                            sbSql.AppendFormat("  AND LOCKED<>'Y' ");
                        }
                        //添加Config
                        if (dtDwnSource.Columns.Contains("CONFIG"))
                        {
                            if (!string.IsNullOrEmpty(dtDwnSource.Rows[i]["CONFIG"].ToString()))
                            {
                                sbSql.AppendFormat("  AND CONFIG ='" + dtDwnSource.Rows[i]["CONFIG"].ToString() + "' ");
                            }
                            else
                            {
                                sbSql.AppendFormat(" AND (CONFIG = '' OR CONFIG IS NULL)");
                            }
                        }

                        #endregion
                            try
                        {
                            ControlHandleDB();
                            dtWhitm = ControlSqlAccess.GetDataTable(sbSql.ToString());
                            ControlSqlAccess.CloseConnection();
                        }
                        catch (Exception ex)
                        {
                            ERRMSG = ex.Message + "<- QueryOnLineOutData()查询库存异常";
                        }

                        #region 出库顺序规则
                        //(出庫規則 : INDAT->先進先出, LOCAT->儲位由小到大出, CRDAT->先建檔的先出)
                        string strOrderBy = "";
                        //是否要利用DateCode先後順序作出庫
                        if (varByDateCode == true)
                        {
                            //判断是否为LotCode管控仓-F2 Bob --先是DACOD管控仓，后是Lot Code管控仓
                            if (CheckStorageInType(strWerks, strLgort, "Diff LOCOD Diff Locat"))
                            {             
                                strOrderBy = "VEDAT,LOCOD,INDAT,LOCAT";
                            }
                            // strOrderBy = "DACOD,VEDAT, LOCAT, CRDAT";
                            //strOrderBy = "DACOD, LOCAT, CRDAT";//DateCode: 廠商生產日期, 儲位, 建立日期
                            //管控仓按照Datecode转换后的日期先进先出，不再比对DACOD--车轮飞
                            //出库顺序不要CRDAT栏位-jiashan
                            else
                            {
                                strOrderBy = "VEDAT,INDAT,LOCAT"; //DateCode转换后日期、入库日期、 储位、 建立日期
                            }
                        }                    
                        else
                        {
                            //修改COMCD = 9100，廠區為CS12，且倉別為TW10或TW11的出庫順序  Smose Liao 20100329
                            if (COMCD == "9100" && WERKS == "CS12" && (LGORT == "TW10" || LGORT == "TW11"))
                            {
                                strOrderBy = "INDAT, CRDAT, LOCAT";
                            }
                            //依PKDAT(Pallet滿板的完成時間)，限定超過24小時才能出庫  Smose Liao 20121129
                            else if (COMCD == "9200" && WERKS == "CS20" && LGORT == "TW35")
                            {
                                strOrderBy = "NEW_PKDAT, INDAT, LOCAT DESC";
                            }
                            else if (COMCD == "9200" && WERKS == "CS31" && (LGORT.Substring(0, 2) == "TW" || LGORT.Substring(0, 2) == "TC"))
                            {
                                strOrderBy = "MCDAT, INDAT, LOCAT, CRDAT";//退料出庫：退库日期，入庫日期, 儲位, 建立日期 (退料日期催财NULL值）
                            }
                            else
                            {
                                strOrderBy = "INDAT, LOCAT, CRDAT";//正常出庫：入庫日期, 儲位, 建立日期
                            }
                        }
                        //9900 特殊要求  //廠商生產日期 , 入库日期， 储位， 建立日期
                        if (COMCD == "9100" || (COMCD == "9900" && WERKS == "CS90" && (LGORT == "TW51" || LGORT == "TW10")))
                        {
                            strOrderBy = "VEDAT,INDAT, LOCAT, CRDAT";
                        }
                        if (COMCD == "9200" && WERKS == "CS31" && (LGORT.Substring(0, 2) == "TW" || LGORT.Substring(0, 2) == "TC"))
                        {
                            strOrderBy = " MCDAT,INDAT, LOCAT, CRDAT";//退料出庫：退库日期，入庫日期, 儲位, 建立日期 (退料日期催财NULL值）
                        }

                        dtWhitm = CommonInfo.SortDataTable(dtWhitm, strOrderBy);
                        #endregion

                        #region 增加REFID與SEQNO兩個欄位，查詢WHDWN中的REFID與SEQNO的值  Smose Liao 20100427
                        dtWhitm.Columns.Add("REFID", Type.GetType("System.String"));
                        dtWhitm.Columns.Add("SEQNO", Type.GetType("System.String"));
                        StringBuilder sbRefidSeqno = new StringBuilder();
                        #endregion

                        //int intLocatMenge = 0;
                        int intSourceOutMenge = 0;

                        if (i == 0)
                        {
                            dtOutWhitm = dtWhitm.Clone();  //即将要出库的数据
                        }
                        for (int j = 0; j < dtWhitm.Rows.Count; j++)
                        {
                            intSourceOutMenge = 0;

                            //檢查出庫單據是否都已經出完
                            #region 查看該筆單據已經出多少了

                            drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                            for (int k = 0; k < drFound.Length; k++)
                            {
                                intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                            }
                            #endregion


                            if (intSourceMenge > intSourceOutMenge)
                            {
                                #region 单据数量大于库存数量的情况   //如果還沒出完   //intSourceMenge:whdwn上要出的數量, intSourceMenge:已經出的數量
                                int intLocatMblnrTempAlqty = 0;

                                //從目前已出庫的數量中找出該儲位該料號已經出庫的數量
                                #region 組已出單據中儲位庫存的Key(比對WHITM的Key)
                                StringBuilder sbWhitmKey = new StringBuilder();
                                sbWhitmKey.Remove(0, sbWhitmKey.Length);
                                sbWhitmKey.Append(" LOCAT='" + dtWhitm.Rows[j]["LOCAT"].ToString() + "'");
                                sbWhitmKey.Append(" and OMBLNR = '" + dtWhitm.Rows[j]["OMBLNR"].ToString() + "'");
                                sbWhitmKey.Append(" and MATNR='" + dtWhitm.Rows[j]["MATNR"].ToString() + "'");
                                sbWhitmKey.Append(" and INSMK='" + dtWhitm.Rows[j]["INSMK"].ToString() + "'");
                                sbWhitmKey.Append(" and CHARG='" + dtWhitm.Rows[j]["CHARG"].ToString() + "'");
                                sbWhitmKey.Append(" and MRGID='" + dtWhitm.Rows[j]["MRGID"].ToString() + "'");
                                //成品
                                sbWhitmKey.Append(" and SERNO='" + dtWhitm.Rows[j]["SERNO"].ToString() + "'");
                                //DataCode
                                sbWhitmKey.Append(" and DACOD='" + dtWhitm.Rows[j]["DACOD"].ToString() + "'");
                                sbWhitmKey.Append(" and LOCOD='" + dtWhitm.Rows[j]["LOCOD"].ToString() + "'");
                                sbWhitmKey.Append(" and INSPT='" + dtWhitm.Rows[j]["INSPT"].ToString() + "'");

                                #endregion

                                //查询出前面单据已出的库存
                                drFound1 = dtOutWhitm.Select(sbWhitmKey.ToString());
                                for (int k = 0; k < drFound1.Length; k++)
                                {
                                    intLocatMblnrTempAlqty += Int32.Parse(drFound1[k]["ALQTY"].ToString());  //待出货数量 
                                }

                                int intBalanceQty = Int32.Parse(dtWhitm.Rows[j]["MENGE"].ToString()) - intLocatMblnrTempAlqty;  //这个储位可以出的数量
                                //MENGE:Locat數量, ALQTY:已出數量

                                #region 如果儲位還有剩餘數量 计算出库逻辑
                                if (intBalanceQty > 0)
                                {
                                    int intLocatAlqty = 0;
                                    //如果儲位的剩餘數量小於單據的剩餘數量則全出, 否則出差值
                                    if (intSourceMenge - intSourceOutMenge >= intBalanceQty)
                                    {
                                        intLocatAlqty = intBalanceQty;
                                    }
                                    else
                                    {
                                        intLocatAlqty = intSourceMenge - intSourceOutMenge;
                                    }
                                    #region  如果儲位有出庫則紀錄
                                    if (intLocatAlqty > 0)
                                    {
                                        drRow = dtOutWhitm.NewRow();
                                        drRow["MANDT"] = dtWhitm.Rows[j]["MANDT"].ToString();
                                        drRow["COMCD"] = dtWhitm.Rows[j]["COMCD"].ToString();
                                        drRow["WERKS"] = dtWhitm.Rows[j]["WERKS"].ToString();
                                        drRow["LGORT"] = dtWhitm.Rows[j]["LGORT"].ToString();
                                        drRow["LOCAT"] = dtWhitm.Rows[j]["LOCAT"].ToString();
                                        drRow["MATNR"] = dtWhitm.Rows[j]["MATNR"].ToString();
                                        drRow["DECITEM"] = dtWhitm.Rows[j]["DECITEM"];
                                        drRow["INSMK"] = dtWhitm.Rows[j]["INSMK"].ToString();
                                        drRow["CHARG"] = dtWhitm.Rows[j]["CHARG"].ToString();
                                        drRow["MENGE"] = dtWhitm.Rows[j]["MENGE"].ToString();
                                        drRow["ALQTY"] = intLocatAlqty.ToString();
                                        drRow["MTYPE"] = dtWhitm.Rows[j]["MTYPE"].ToString();
                                        drRow["MBLNR"] = dtWhitm.Rows[j]["MBLNR"].ToString();
                                        drRow["ZEILE"] = dtWhitm.Rows[j]["ZEILE"].ToString();
                                        drRow["EBELN"] = dtWhitm.Rows[j]["EBELN"].ToString();
                                        drRow["LIFNR"] = dtWhitm.Rows[j]["LIFNR"].ToString();
                                        drRow["RMANO"] = dtWhitm.Rows[j]["RMANO"].ToString();  // Quanta, Smose.Liao, 20090225：Add the function of Online Goods Issue by RMA No.(連線出庫依據RMA NO.進行出庫)
                                        drRow["OMBLNR"] = dtWhitm.Rows[j]["OMBLNR"].ToString();
                                        drRow["MRGID"] = dtWhitm.Rows[j]["MRGID"].ToString();
                                        drRow["KOSTL"] = dtWhitm.Rows[j]["KOSTL"].ToString();
                                        drRow["ARBPL"] = dtWhitm.Rows[j]["ARBPL"].ToString();
                                        drRow["TRNTP"] = dtWhitm.Rows[j]["TRNTP"].ToString();
                                        drRow["RMAK1"] = dtWhitm.Rows[j]["RMAK1"].ToString();
                                        drRow["INDAT"] = dtWhitm.Rows[j]["INDAT"].ToString();
                                        //20051017 MARC 新增KDMAT欄位
                                        drRow["KDMAT"] = dtWhitm.Rows[j]["KDMAT"].ToString();
                                        //成品
                                        drRow["SERNO"] = dtWhitm.Rows[j]["SERNO"].ToString();
                                        drRow["BOXID"] = dtWhitm.Rows[j]["BOXID"].ToString();
                                        //DateCode
                                        drRow["VEDAT"] = dtWhitm.Rows[j]["VEDAT"].ToString();
                                        drRow["DACOD"] = dtWhitm.Rows[j]["DACOD"].ToString();
                                        drRow["LOCOD"] = dtWhitm.Rows[j]["LOCOD"].ToString();
                                        drRow["INSPT"] = dtWhitm.Rows[j]["INSPT"].ToString();
                                        drRow["PKDAT"] = dtWhitm.Rows[j]["PKDAT"].ToString();
                                        //有效期以及TASKID
                                        drRow["EXPDAT"] = dtWhitm.Rows[j]["EXPDAT"].ToString();
                                        drRow["TASKID"] = dtWhitm.Rows[j]["TASKID"].ToString();
                                        drRow["MCDAT"] = dtWhitm.Rows[j]["MCDAT"].ToString();
                                        if (dtWhitm.Columns.Contains("CONFIG"))
                                        {
                                            drRow["CONFIG"] = dtWhitm.Rows[j]["CONFIG"].ToString();
                                        }
                                        dtOutWhitm.Rows.Add(drRow);

                                    }
                                    #endregion
                                }
                                #endregion
                            }
                                #endregion
                            else
                            {
                                break;
                            }
                        }
                        //更新單據的總出庫數量
                        intSourceOutMenge = 0;

                        drFound = dtOutWhitm.Select(sbWhdwnKey.ToString());

                        for (int k = 0; k < drFound.Length; k++)
                        {
                            intSourceOutMenge += Int32.Parse(drFound[k]["ALQTY"].ToString());
                        }
                        dtDwnSource.Rows[i]["ALQTY"] = intSourceOutMenge;

                    }

                    if (dtDwnSource.DataSet != null)
                        dtDwnSource.DataSet.Tables.Remove(dtDwnSource);

                    dtDwnSource.TableName = "Source";
                    dtOutWhitm.TableName = "Destination";
                    dsResult.Tables.Add(dtDwnSource);
                    dsResult.Tables.Add(dtOutWhitm);

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryOnLineOutData()";
                }

                return dsResult;
            }
            #endregion

            #region 转仓库存锁定提示
            public DataTable QueryOnLineLockedData(DataTable dtDwnSource)
            {
                DataTable dtResult = new DataTable();                     
                DataTable dtWhitm = new DataTable();
                StringBuilder sbSql = new StringBuilder();

                for (int i = 0; i < dtDwnSource.Rows.Count; i++)
                {
                    StringBuilder sbWhdwnKey = new StringBuilder();
                    sbWhdwnKey.Remove(0, sbWhdwnKey.Length);
                    sbWhdwnKey.Append(" MBLNR='" + dtDwnSource.Rows[i]["MBLNR"].ToString() + "'");
                    sbWhdwnKey.Append(" and ZEILE='" + dtDwnSource.Rows[i]["ZEILE"].ToString() + "'");
                    sbWhdwnKey.Append(" and MATNR='" + dtDwnSource.Rows[i]["MATNR"].ToString() + "'");
                    sbWhdwnKey.Append(" and INSMK='" + dtDwnSource.Rows[i]["INSMK"].ToString() + "'");
                    sbWhdwnKey.Append(" and CHARG='" + dtDwnSource.Rows[i]["CHARG"].ToString() + "'");
                    int intSourceMenge = int.Parse(dtDwnSource.Rows[i]["MENGE"].ToString());                     
                    sbSql.Length = 0;
                    sbSql.AppendLine(" SELECT COUNT (*) FROM DBO.WHITM W   LEFT JOIN MATDIC AS M ON W.COMCD=M.COMCD AND  W.MATNR=M.MATNR   ");
                    sbSql.AppendLine(" WHERE  (MANDT= '" + MANDT + "') And (W.COMCD= '" + COMCD + "') And (WERKS= '" + WERKS + "') And (LGORT= '" + LGORT + "') "
                        + " And (W.MATNR= '" + dtDwnSource.Rows[i]["MATNR"].ToString() + "') And (INSMK= '" + dtDwnSource.Rows[i]["INSMK"].ToString() + "') "
                        + " And (CHARG= '" + dtDwnSource.Rows[i]["CHARG"].ToString() + "') ");
                    sbSql.AppendFormat("  AND LOCKED='Y' ");
                    try
                    {
                        ControlHandleDB();
                        dtWhitm = ControlSqlAccess.GetDataTable(sbSql.ToString());
                        ControlSqlAccess.CloseConnection();
                    }
                    catch (Exception ex)
                    {
                        ERRMSG = ex.Message + "<- QueryOnLineLockedData()查询库存异常";
                    }
                }           
                return dtWhitm;
            }               
            #endregion


            #region 确认出库仓类型

            /// <summary>
            /// 确认出库仓类型
            /// </summary>
            /// <param name="strWerk"></param>
            /// <param name="strLgort"></param>
            /// <param name="strType"></param>
            /// <returns></returns>
            public bool CheckStorageOutType(string strWerk, string strLgort, string strType)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "CheckStorageOutType";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                bool flage = false;
                try
                {
                    StringBuilder sbSql = new StringBuilder();
                    sbSql.AppendFormat("SELECT 1  FROM WHCTRL WHERE MANDT='218' AND SOLDTO='QWMS' AND CTRLID='StorageOut_Type' AND  REMAK='{0}' AND CTRLNM='{1}'AND CTRLC1='{2}'", strType, strWerk, strLgort);
                    ControlHandleDB();
                    DataTable dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();
                    if (dtData.Rows.Count > 0)
                    {
                        flage = true;
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return flage;
            }
            #endregion       

            #region  并储作业查询库存明细
            public DataTable QueryStorageDetailData(string strLocat, string strIsmrg)
            {
                DataWhitm objWhitm = new DataWhitm(UserData);

                string strSQL = "Select I.MANDT,I.COMCD, I.WERKS, I.LGORT, I.LOCAT, I.MATNR, I.INSMK, I.CHARG, I.MENGE, I.MENGE as ALQTY, I.QCQTY, '' as MBLNR, '' as ZEILE,"
                + "I.MBLNR as OMBLNR,I.LOCKED,I.MRGID, '' as KOSTL, '' as ARBPL, '' as TRNTP, I.EBELN, I.LIFNR, I.RMAK1, I.INDAT, I.REFNO, Convert(varchar(20), CRDAT, 120) as CRDAT, I.KDMAT,"
                + "I.SERNO,I.LOCOD,I.INSPT,I.VEDAT,I.DACOD,I.BOXID,I.RMANO,I.PKDAT, M.DECITEM, I.ExpiryDate, I.TASKID, I.MAXEXP,I.CONFIG "
                + " from WHITM   AS I WITH(NOLOCK) LEFT JOIN MATDIC AS M WITH(NOLOCK) ON I.COMCD=M.COMCD AND I.MATNR=M.MATNR "
                + "where I.MANDT= '" + MANDT + "' AND I.COMCD='" + COMCD + "' and I.WERKS= '" + WERKS + "' and I.LGORT= '" + LGORT + "'";

                if (strLocat != "")
                {
                    strSQL += " and I.LOCAT= '" + strLocat + "'";
                }
                if (strIsmrg != "")
                {
                    if (strIsmrg == "Y")
                    {
                        strSQL += " and I.MRGID <> ''";
                    }
                    else
                    {
                        strSQL += " and I.MRGID = ''";
                    }
                }
                DataTable dtData = new DataTable();
                try
                {
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL);
                    ControlSqlAccess.CloseConnection();
                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QueryStorageDetailData()";
                }
                return dtData;
            }

            #endregion

            #region 查询QWMS+ASRS库存比对数据
            //========================================================================================
            /// <summary>
            /// 查询QWMS+ASRS库存比对数据
            /// </summary> 
            /// 
            public DataTable QueryASRSContrastData(string strWerks, string strLgort)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryASRSContrastData";
