            //========================================================================================
            /// <summary>
            /// 查询PCBA退库入库数据
            /// </summary> 
            /// 
            public DataTable QueryStorageData_PCBA(string strWerks, string strLgort, string strRefID, string strBxID, string strSn, string strMatnr, string strSnStatus, string strUmlgo, string strDateFrom, string strDateTo)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryStorageData_PCBA";
                this.ControlMethodParm = "(" + strWerks + "," + strLgort + "," + strRefID + "," + strBxID + "," + strSn + "," + strMatnr + "," + strSnStatus + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                StringBuilder sbSQL = new StringBuilder();
                DataTable dtData = new DataTable();
                try
                {
                    ControlHandleDB();
                    sbSQL = sbSQL.Append(" SELECT *  FROM [dbo].[View_QueryStorageData_PCBA]  WHERE MANDT='" + MANDT + "' AND COMCD='" + COMCD + "'   ");
                    if (!string.IsNullOrEmpty(strWerks))
                    {
                        sbSQL.Append(" AND  WERKS='" + strWerks + "' ");
                    }
                    if (!string.IsNullOrEmpty(strLgort))
                    {
                        sbSQL.Append(" AND  LGORT='" + strLgort + "' ");
                    }
                    if (!string.IsNullOrEmpty(strRefID))
                    {
                        sbSQL.Append(" AND  MBLNR='" + strRefID + "' ");
                    }
                    if (!string.IsNullOrEmpty(strBxID))
                    {
                        sbSQL.Append(" AND BOXID='" + strBxID + "' ");
                    }
                    if (!string.IsNullOrEmpty(strSn))
                    {
                        sbSQL.Append(" AND  SERNO='" + strSn + "' ");
                    }
                    if (!string.IsNullOrEmpty(strMatnr))
                    {
                        sbSQL.Append(" AND  MATNR+CHARG  LIKE '" + strMatnr + "%' ");
                    }
                    if (!string.IsNullOrEmpty(strSnStatus))
                    {
                        sbSQL.Append(" AND  SNStatus='" + strSnStatus + "' ");
                    }
                    if (!string.IsNullOrEmpty(strUmlgo))
                    {
                        sbSQL.Append(" AND  UMLGO ='" + strUmlgo + "' ");
                    }
                    if (!string.IsNullOrEmpty(strDateFrom) && !string.IsNullOrEmpty(strDateTo))
                    {
                        sbSQL.Append(" AND  StatusTim BETWEEN '" + strDateFrom + "' AND '" + strDateTo + "' ");
                    }

                    dtData = ControlSqlAccess.GetDataTable(sbSQL.ToString());
                    ControlSqlAccess.CloseConnection();

                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
