            public DataTable QueryScrapPackingData(string strWerks, string strLgort, string strMatnr, string strPN, string strCharg, string strPacking)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryScrapPackingData";
                this.ControlMethodParm = "(" + strWerks + "," + strLgort + "," + strMatnr + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {

                    //string strSQL1 = "SELECT WERKS,LGORT,MATNR,CHARG,SUM(MENGE) AS PACKING "
                    //    + "FROM dbo.WHITM " + "WHERE WERKS='" + strWerks + "' AND LGORT='" + strLgort + "' AND MATNR='" + strMatnr + "'"
                    //    + "GROUP BY WERKS,LGORT,MATNR,CHARG";
                    string strSQL1 = "SELECT DISTINCT I.WERKS AS WERKS,I.LGORT AS LGORT,I.MATNR AS MATNR,I.CHARG AS CHARG,I.INSMK AS INSMK,M.DECITEM AS DECITEM "
                                   + "FROM WHITM AS I WITH(NOLOCK) LEFT JOIN MATDIC AS M ON I.COMCD=M.COMCD AND I.MATNR=M.MATNR "
                                   + "WHERE I.WERKS='" + strWerks + "' AND I.LGORT='" + strLgort + "' AND I.MATNR='" + strMatnr + "'AND I.CHARG='" + strCharg + "' ";
                    string strSQL2 = "SELECT LOCAT,SUM(MENGE) AS MENGE,INDAT FROM dbo.WHITM WITH(NOLOCK) WHERE MANDT='" + MANDT + "' AND COMCD='" + COMCD + "' AND WERKS='" + strWerks + "' AND LGORT='" + strLgort + "' AND MATNR='" + strMatnr + "'AND CHARG='" + strCharg + "' "
                                   + "GROUP BY LOCAT,INDAT ORDER BY INDAT";

                    DataTable dtData1 = new DataTable();
                    DataTable dtData2 = new DataTable();
                    DataTable dtData = new DataTable();
                    ControlHandleDB();
                    dtData.Columns.Add("WERKS");
                    dtData.Columns.Add("LGORT");
                    dtData.Columns.Add("MATNR");
                    dtData.Columns.Add("CHARG");
                    dtData.Columns.Add("PACKINGQTY");
                    dtData.Columns.Add("INSMK");
                    dtData.Columns.Add("LOCAT");
                    dtData.Columns.Add("MENGE");
                    dtData.Columns.Add("INDAT");
                    dtData.Columns.Add("DCITEM");
                    dtData.Columns.Add("PACKINGNO");

                    dtData1 = ControlSqlAccess.GetDataTable(strSQL1);
                    DataRow dr = null;
                    foreach (DataRow row in dtData1.Rows)
                    {
                        dr = dtData.NewRow();
                        dr[0] = row["WERKS"];
                        dr[1] = row["LGORT"];
                        dr[2] = row["MATNR"];
                        dr[3] = row["CHARG"];
                        dr[4] = strPacking;
                        dr[5] = row["INSMK"];
                        dr[9] = row["DECITEM"];
                        dr[10] = strPN;
                    }
                    dtData2 = ControlSqlAccess.GetDataTable(strSQL2);
                    //dtData.Merge(dtData2);
                    foreach (DataRow row in dtData2.Rows)
                    {
                        dr[6] = row["LOCAT"];
                        dr[7] = row["MENGE"];
                        dr[8] = row["INDAT"];
                        dtData.Rows.Add(dr);
                        dr = dtData.NewRow();
                    }

                    ControlSqlAccess.CloseConnection();

                    return dtData;
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
