            #region 查询IQC打印数据

            public DataTable GetIQCReturnData(string strWerk, string strLgort, string strGRno, string strDateFrom, string strDateTo, bool blPrintAgain, string strType)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "GetIQCReturnData";
                this.ControlMethodParm = "(" + strWerk + strLgort + strGRno + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtData = new DataTable();
                StringBuilder sbSql = new StringBuilder();
                try
                {
                    if (strType == "合并")
                    {
                        sbSql.AppendFormat(" EXEC [SP_Combine_IQC_BadPN] '" + strWerk + "','" + strLgort + "','" + strGRno + "','" + strDateFrom + "','" + strDateTo + "' ");
                        ControlHandleDB();
                        dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                        ControlSqlAccess.CloseConnection();
                        if (dtData.Rows.Count == 0)
                        {
                            return new DataTable();
                        }
                    }
                    sbSql = new StringBuilder();


                    sbSql.AppendFormat(" SELECT 'false' AS cSelect,MBLNR,BOXID,MATNR,CHARG,LIFNR,MENGE,BUDAT,REFID,USNAM,KDMAT,DELNO,DEITM ");
                    sbSql.AppendFormat(" FROM WHTIC WITH(NOLOCK) WHERE MTYPE IN ('SAP_IQC','OA_IQC') AND OTQTY=0 AND FLAGE IS NULL AND WERKS='{0}' AND LGORT='{1}' ", strWerk, strLgort);
                    if (strGRno != "")
                    {
                        if (strGRno.Substring(0, 1) == "B")
                        {
                            sbSql.AppendFormat(" AND LEFT(MBLNR,15)=LEFT('{0}',15) ", strGRno);
                        }
                        else if (strGRno.Substring(0, 1) == "A")
                        {
                            sbSql.AppendFormat(" AND LEFT(MBLNR,13)=LEFT('{0}',13) ", strGRno);
                        }
                        else
                        {
                            sbSql.AppendFormat(" AND LEFT(MBLNR,10)=LEFT('{0}',10) ", strGRno);
                        }
                    }
                    if (strDateFrom != "" && strDateTo != "")
                    {
                        sbSql.AppendFormat(" AND CRDAT BETWEEN '{0} 00:00:00' AND '{1} 23:59:59' ", strDateFrom, strDateTo);
                    }
                    if (blPrintAgain)
                    {
                        sbSql.AppendFormat(" AND ADFLG IS NOT NULL  ");
                    }
                    else
                    {
                        sbSql.AppendFormat(" AND ADFLG IS NULL ");
                    }
                    sbSql.AppendFormat(" ORDER BY MBLNR,ZEILE ");

                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return dtData;
            }
