            #region
            public DataTable QueryDateCodeTimeData(string strInsmk, string strStartMatnr, string strEndMatnr, string strVendor, string strType1, string strStartDate, string strComparsion, string strType2, string strEndDate, string strStartLocat, string strEndLocat, string strLocked)
            {
                DataTable dtResult = new DataTable();
                StringBuilder sbSql = new StringBuilder();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                // sbSql.AppendFormat(" SELECT DISTINCT (DATEDIFF(DAY,VEDAT,GETDATE())) AS 'DCDAY',WHITM.* FROM WHITM  inner join WHCTRL on WHITM.WERKS = WHCTRL.CTRLNM  and WHITM.WERKS IN (Select CTRLNM from WHCTRL where WHCTRL.MANDT= '" + MANDT + "' and WHCTRL.COMCD ='" + COMCD + "'and WHCTRL.SOLDTO='QWMS' and WHCTRL.CTRLID='StorageIn_Type' AND WHCTRL.REMAK='Diff DACOD Diff Locat'AND WHCTRL.CTRLN3='1')AND  WHITM.LGORT IN (Select CTRLC1 from WHCTRL where  WHCTRL.MANDT= '" + MANDT + "' and WHCTRL.COMCD ='" + COMCD + "'and WHCTRL.SOLDTO='QWMS' and WHCTRL.CTRLID='StorageIn_Type' AND WHCTRL.REMAK='Diff DACOD Diff Locat'AND WHCTRL.CTRLN3='1' AND CTRLNM='"+WERKS+"') AND WHITM.WERKS='" + WERKS + "'");   
                // 料号有效期存储期
                //sbSql.AppendFormat(@" SELECT DISTINCT CONVERT(varchar(8),DATEADD(MONTH,
                //                       (CASE WHEN SUBSTRING(MATNR,1,2) IN('DA','SA') THEN 12 
                //                       WHEN (SUBSTRING(MATNR,1,1) IN('A','B','C','D','L','N','T','S') OR SUBSTRING(MATNR,1,2) IN('3R')) AND SUBSTRING(MATNR,1,2) NOT IN('DA') AND SUBSTRING(MATNR,1,2) NOT IN('SA') THEN 48
                //                       WHEN MATNR IN('3NV72CATEB0','3NV72CATEC0') THEN 12
                //                       ELSE 72 END ),VEDAT), 112) AS MSDate, (DATEDIFF(DAY,VEDAT,GETDATE())) AS 'DCDAY',WHITM.* 
                //                  FROM WHITM  inner join WHCTRL on WHITM.WERKS = WHCTRL.CTRLNM  and WHITM.WERKS IN (Select CTRLNM from WHCTRL where WHCTRL.MANDT= '" + MANDT + "' and WHCTRL.COMCD ='" + COMCD + "'and WHCTRL.SOLDTO='QWMS' and WHCTRL.CTRLID='StorageIn_Type' AND WHCTRL.REMAK='Diff DACOD Diff Locat'AND WHCTRL.CTRLN3='1')AND  WHITM.LGORT IN (Select CTRLC1 from WHCTRL where  WHCTRL.MANDT= '" + MANDT + "' and WHCTRL.COMCD ='" + COMCD + "'and WHCTRL.SOLDTO='QWMS' and WHCTRL.CTRLID='StorageIn_Type' AND WHCTRL.REMAK='Diff DACOD Diff Locat'AND WHCTRL.CTRLN3='1' AND CTRLNM='" + WERKS + "') AND WHITM.WERKS='" + WERKS + "'");

                sbSql.AppendFormat(@"SELECT WERKS,LGORT,SUBSTRING(LOCAT,1,8) AS LOCAT,INSMK,MATNR,LIFNR,MENGE,INDAT,VEDAT,DACOD,LOCOD,CHARG,DCDAY,RMAK1,(CASE WHEN DATEDIFF(DAY,EXPDAT,MAXEXP)>=0 THEN EXPDAT ELSE MAXEXP END) AS ExpiryDate,MAXEXP,TASKID,LOCKED FROM  
                                      View_DCQuery with(nolock) where MANDT= '{0}' AND  COMCD ='{1}' AND WERKS='{2}'", MANDT, COMCD, WERKS);
                //仓别
                if (strLgort != "")
                {
                    sbSql.AppendFormat(" AND LGORT = '" + strLgort + "'");
                }
                //库别
                if (strInsmk != "")
                {
                    sbSql.AppendFormat(" AND INSMK = '" + strInsmk + "'");
                }
                //版本
                if (strVendor != "")
                {
                    sbSql.AppendFormat(" AND LIFNR = '" + strVendor + "'");
                }
                //料号区间
                if (strStartMatnr != "" && strEndMatnr != "")
                {
                    sbSql.AppendFormat(" AND MATNR between  '{0}' and '{1}'", strStartMatnr, strEndMatnr);
                }
                else if (strStartMatnr == "" && strEndMatnr != "")
                {
                    sbSql.AppendFormat(" AND MATNR = '" + strEndMatnr + "'");
                }
                else if (strStartMatnr != "" && strEndMatnr == "")
                {
                    sbSql.AppendFormat(" AND MATNR = '" + strStartMatnr + "'");
                }
                //储位区间
                if (strStartLocat != "" && strEndLocat != "")
                {
                    sbSql.AppendFormat(" AND LOCAT between  '{0}' and '{1}'", strStartLocat, strEndLocat);
                }
                else if (strStartLocat == "" && strEndLocat != "")
                {
                    sbSql.AppendFormat(" AND LOCAT = '" + strEndLocat + "'");
                }
                else if (strStartLocat != "" && strEndMatnr == "")
                {
                    sbSql.AppendFormat(" AND LOCAT = '" + strStartLocat + "'");
                }
                //加锁设定
                if (strLocked != "")
                {
                    sbSql.AppendFormat(" AND LOCKED = '" + strLocked + "'");
                }
                //开始的选择 符号的选择
                if (strType1 != "" && strStartDate != "")
                {
                    if (strComparsion != "" && strType2 != "" && strEndDate != "")
                    {
                        sbSql.AppendFormat(" and (Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", VEDAT), 112) " + strComparsion + " Convert(varchar(8), getdate(), 112) " + strType2 + " convert(varchar(8), dateadd(day ," + strEndDate + ", VEDAT), 112))");
                    }
                    else
                    {
                        sbSql.AppendFormat(" and (Convert(varchar(8), getdate(), 112) " + strType1 + " convert(varchar(8), dateadd(day," + strStartDate + ", VEDAT), 112))");
                    }
                }
                sbSql.AppendFormat("ORDER BY LOCAT");
                ControlHandleDB();
                DataTable dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                ControlSqlAccess.CloseConnection();
                return dtData;
