            /// <param name="strToDate">终止日期</param>
            /// <returns></returns>
            public DataTable GetPalletStock(string strPallet, string strWerks, string strLgort, string strMachine, string strFromDate, string strToDate, string strType)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "GetPalletStock";
                this.ControlMethodParm = "(" + strPallet + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                DataTable dtResult = new DataTable();
                StringBuilder sbSql = new StringBuilder();
                sbSql.AppendFormat("SELECT WERKS,LGORT,LOCAT,MBLNR,MATNR,CHARG,INSMK,LIFNR,EBELN,MENGE,RMAK1,CRDAT FROM WHITM WITH(NOLOCK) WHERE MANDT='218' AND COMCD='{0}'  ", COMCD);
