                {
                    sbSql.AppendFormat(" AND WERKS='{0}'", strWerks);
                }
                if (!string.IsNullOrEmpty(strLgort))
                {
                    sbSql.AppendFormat(" AND LGORT='{0}'", strLgort);
                }
                if (!string.IsNullOrEmpty(strPallet))
                {
                    sbSql.AppendFormat(" AND MBLNR IN ('{0}')", strPallet);
                }
                if (!string.IsNullOrEmpty(strMachine))
                {
                    sbSql.AppendFormat(" AND MATNR LIKE '{0}%'", strMachine);
                }
                if (strType.Equals("ALL"))
                {
                    sbSql.Append(" AND LEN(MBLNR)>22");
                }
                if (!string.IsNullOrEmpty(strFromDate) && !string.IsNullOrEmpty(strToDate))
                {
                    sbSql.AppendFormat(" AND CRDAT BETWEEN DATEADD(DAY,0,'{0}') AND DATEADD(DAY,+1,'{1}')", strFromDate, strToDate);
                }
                sbSql.Append(" ORDER BY WERKS,LGORT,LOCAT,MATNR,CHARG");
