            /// <param name="strApplyno">调拨车单号</param>
            /// <returns></returns>

            public DataTable QueryApplynoSchedule(string strApplyno)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryApplynoSchedule";
                this.ControlMethodParm = "('" + strApplyno + "')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    ClaHttpHelper claheepHelper = new ClaHttpHelper();
                    var Data = new
                    {
                        strApplyno
                    };
                    //{"status":"Y","results":"[{\"TransferNo\":\"CS122108160002\",\"DispatchNo\":\"PS2108160050\",\"Status\":\"5\"}]"}
                    string strData = JsonConvert.SerializeObject(strApplyno);
                    string strUrl = "http://172.16.2.120:81/SDS.TRANSFER.API/API/Query/QueryStatus";
                    string strResult = claheepHelper.HttpPostByHttpWebRequest(strUrl, strData);
                    DataTable dtApplyno = new DataTable();
                    JObject jo = JObject.Parse(strResult);
                    string strresult = jo["result"].ToString();
                    if (strresult.Equals("Y"))
                    {
                        string strdate = jo["data"].ToString();
                        dtApplyno = JsonConvert.DeserializeObject<DataTable>(strdate);
                    }
                    else
                    {
                        string strmessage = jo["message"].ToString();
                        if (!dtApplyno.Columns.Contains("message"))
                            dtApplyno.Columns.Add("message", typeof(string));
                        dtApplyno.Rows[0]["message"] = strmessage;
                    }
                    //string strRESULT1 = Convert.ToString(strResult);                 
                    //if (strRESULT1.Equals("Y"))
                    //{
                    //    string strTxt = strRESULT1.ToUpper().Replace("：", ":");
                    //    string[] str = strTxt.Split(':');
                    //    string str1 = str[str.Length - 1].ToString();
                    //}
                    return dtApplyno;
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

            }
