            public DataTable QuerySimulationGrrno_DateCode(string strGrpid, string strWerks, string strLgort)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QuerySimulationGrrno_DateCode";
                this.ControlMethodParm = "(" + strGrpid + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtStorage = new DataTable();
                DataTable dtData = new DataTable();
                DataRow drRow;
                //取得出庫單資料
                dtStorage = QueryOnLineInData_Grrno(strGrpid, "OTAUT", strWerks, strLgort);

                dtData = dtStorage.Clone();
                for (int j = 0; j < dtStorage.Rows.Count; j++)
                {
                    drRow = dtData.NewRow();
                    drRow["GRRNO"] = dtStorage.Rows[j]["GRRNO"].ToString();
                    drRow["ITEMNUM"] = dtStorage.Rows[j]["ITEMNUM"].ToString();
                    drRow["MANDT"] = dtStorage.Rows[j]["MANDT"].ToString();
                    drRow["COMCD"] = dtStorage.Rows[j]["COMCD"].ToString();
                    drRow["WERKS"] = dtStorage.Rows[j]["WERKS"].ToString();
                    drRow["LOCAT"] = dtStorage.Rows[j]["LOCAT"].ToString();
                    drRow["LGORT"] = dtStorage.Rows[j]["LGORT"].ToString();
                    drRow["MBLNR"] = dtStorage.Rows[j]["MBLNR"].ToString();
                    drRow["MATNR"] = dtStorage.Rows[j]["MATNR"].ToString();
                    drRow["INSMK"] = dtStorage.Rows[j]["INSMK"].ToString();
                    drRow["CHARG"] = dtStorage.Rows[j]["CHARG"].ToString();
                    drRow["LIFNR"] = dtStorage.Rows[j]["LIFNR"].ToString();
                    drRow["VEDAT"] = dtStorage.Rows[j]["VEDAT"].ToString();
                    drRow["KDMAT"] = dtStorage.Rows[j]["KDMAT"].ToString();
                    drRow["INDAT"] = dtStorage.Rows[j]["INDAT"].ToString();
                    drRow["BKQTY"] = dtStorage.Rows[j]["BKQTY"].ToString();
                    drRow["ALQTY"] = dtStorage.Rows[j]["ALQTY"].ToString();
                    drRow["RNDQTY"] = dtStorage.Rows[j]["RNDQTY"].ToString();
                    drRow["BLACE"] = dtStorage.Rows[j]["BLACE"].ToString();
                    drRow["DACOD"] = dtStorage.Rows[j]["DACOD"].ToString();
                    drRow["LOCOD"] = dtStorage.Rows[j]["LOCOD"].ToString();
                    drRow["INSPT"] = dtStorage.Rows[j]["INSPT"].ToString();
                    drRow["BARCODE"] = dtStorage.Rows[j]["BARCODE"].ToString();
                    drRow["PRTYP"] = dtStorage.Rows[j]["PRTYP"].ToString();
                    drRow["NEW_BARCODE"] = dtStorage.Rows[j]["NEW_BARCODE"].ToString();
                    drRow["GRPID"] = dtStorage.Rows[j]["GRPID"].ToString();
                    drRow["KOSTL"] = dtStorage.Rows[j]["KOSTL"].ToString();
                    dtData.Rows.Add(drRow);
                }

                return dtData;
            }

