                    //sbSql.AppendFormat(" CASE WHEN CONVERT(VARCHAR,GETDATE(),112) <= D.EXPDAT THEN 0 WHEN CONVERT(VARCHAR,GETDATE(),112) > D.EXPDAT AND CONVERT(VARCHAR,GETDATE(),112) <= D.MAXEXP THEN 1 WHEN CONVERT(VARCHAR,GETDATE(),112) > D.MAXEXP THEN 2 END AS EXPTP ");
                    //sbSql.AppendFormat(" from View_DCQuery_IQC AS D WITH(NOLOCK) LEFT JOIN WHIQC AS I WITH(NOLOCK) ON D.MANDT = I.MANDT AND D.COMCD = I.COMCD AND D.TASKID = I.TASKID");
                    //sbSql.AppendFormat(" where D.MANDT= '{0}' AND D.COMCD = '{1}' AND D.WERKS = '{2}' AND D.LGORT= '{3}' AND ISNULL(I.RESULT,'') NOT IN ('OK','NG','REJECT','WAIVE') ", MANDT, COMCD, strWerks, strLgort);
