                    //sbSql.AppendFormat(" group by D.TASKID,D.MANDT,D.WERKS,D.LGORT,D.MATNR,D.INSMK,D.LIFNR,D.INDAT,D.DACOD,D.VEDAT,D.EXPDAT,D.MAXEXP,I.RESULT,I.RMAK1,I.CHKQTY,I.CHKNAM,I.APPNO,I.MRBNO order by D.MAXEXP desc");


                    sbSql.AppendLine("SELECT D.MANDT, D.WERKS, D.LGORT, D.INSMK, D.MATNR, D.LIFNR, D.INDAT, SUM(D.MENGE) AS MENGE, D.DACOD, D.VEDAT, D.EXPDAT, D.MAXEXP, D.QMMAX, ")
                        .AppendLine("COUNT(*) AS TOTAL, I.TASKID, ISNULL(I.RESULT, '') AS RESULT, I.RMAK1 AS REASON, I.CHKQTY, I.CHKNAM, I.APPNO, I.MRBNO, ")
                        .AppendLine("CASE WHEN CONVERT(VARCHAR, GETDATE(), 112) < D .EXPDAT THEN 0 WHEN CONVERT(VARCHAR, GETDATE(), 112) >= D .EXPDAT AND ")
                        .AppendLine("CONVERT(VARCHAR, GETDATE(), 112) < D .MAXEXP THEN 1 WHEN CONVERT(VARCHAR, GETDATE(), 112) >= D .MAXEXP THEN 2 END AS EXPTP, Q.REQDAT")
                        .AppendLine("FROM View_DCQuery_IQC AS D WITH (NOLOCK) LEFT OUTER JOIN")
                        .AppendLine("I2REQ AS Q ON D.MANDT = Q.MANDT AND D.COMCD = Q.COMCD AND D.WERKS = Q.WERKS AND D.MATNR = Q.MATNR LEFT OUTER JOIN")
                        .AppendLine("WHIQC AS I WITH (NOLOCK) ON D.MANDT = I.MANDT AND D.COMCD = I.COMCD  AND D.WERKS = I.WERKS AND D.LGORT = I.LGORT AND D.TASKID = I.TASKID")
                        .AppendLine(string.Format("WHERE (D.MANDT = '{0}') AND (D.COMCD = '{1}') AND (D.WERKS = '{2}') AND (D.LGORT = '{3}') AND (ISNULL(I.RESULT, '') NOT IN ('NG1', 'NG2', 'REJECT'))", MANDT, COMCD, strWerks, strLgort));//NOT IN ('OK', 'NG1', 'NG2', 'REJECT', 'WAIVE')

                    if (!string.IsNullOrEmpty(strInspectResult))
                    {
                        sbSql.AppendLine(string.Format(" AND ISNULL(I.RESULT,'')='{0}'", strInspectResult));
                    }
                    if (!string.IsNullOrEmpty(strInspectNo))
                    {
                        sbSql.AppendLine(string.Format(" AND ISNULL(D.TASKID,'')='{0}'", strInspectNo));
                    }
                    if (!string.IsNullOrEmpty(strMatnr))
                    {
                        sbSql.AppendLine(string.Format(" AND ISNULL(D.MATNR,'')='{0}'", strMatnr));
                    }

                    sbSql.AppendLine(" AND D.EXPDAT <= CONVERT(VARCHAR, GETDATE(), 112)");
                    sbSql.AppendLine(" AND D.QMMAX > CONVERT(VARCHAR, GETDATE(), 112)");


                    sbSql.AppendLine("GROUP BY D.MANDT, D.WERKS, D.LGORT, D.MATNR, D.INSMK, D.LIFNR, D.INDAT, D.DACOD, D.VEDAT, D.EXPDAT, D.MAXEXP, D.QMMAX, I.TASKID, I.RESULT, I.RMAK1, I.CHKQTY, I.CHKNAM, I.APPNO, I.MRBNO, Q.REQDAT")
                        .AppendLine("ORDER BY IIF(ISNULL(Q.REQDAT, '') = '', '99991231', Q.REQDAT) ASC");

                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();
                    return dtData;
                }
                catch (CommonObjectsException ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
