            #region 保存检验单号及检验信息到WHIQC
            public bool SaveInspectInfo(DataTable dtData, DataTable dtDataDetail, DataTable dtDataInspect, string strExpdat_Keyin, string strNsmno, string strMrbno, string strInspectResult)
            {
                this.ControlMethodName = "SaveInspectInfo";
                this.ControlMethodParm = "('" + dtData + "','" + dtDataDetail + "','" + dtDataInspect + "')";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }
                try
                {
                    DataWhiqc objWhiqc = new DataWhiqc(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    ArrayList arySQL = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();
                    bool bolReturn = false;
                    string strSQL = "";
                    string strExpdat_After = string.Empty;
                    string strMaxexp_After = string.Empty;


                    #region Insert WHIQC
                    for (int i = 0; i < dtData.Rows.Count; i++)
                    {

                        alColumns.Clear();
                        alConditions.Clear();
                        objWhiqc.ResetField();

                        objWhiqc.Mandt = dtData.Rows[i]["MANDT"].ToString();
                        objWhiqc.Comcd = UserData.CompanyCode;
                        objWhiqc.Taskid = dtDataInspect.Rows[0]["TASKID"].ToString();
                        objWhiqc.Werks = dtData.Rows[i]["WERKS"].ToString();
                        objWhiqc.Lgort = dtData.Rows[i]["LGORT"].ToString();
                        objWhiqc.Insmk = dtData.Rows[i]["INSMK"].ToString();
                        objWhiqc.Matnr = dtData.Rows[i]["MATNR"].ToString();
                        objWhiqc.Lifnr = dtData.Rows[i]["LIFNR"].ToString();
                        objWhiqc.Menge = dtData.Rows[i]["MENGE"].ToString();
                        objWhiqc.Dacod = dtData.Rows[i]["DACOD"].ToString();
                        objWhiqc.Vedat = dtData.Rows[i]["VEDAT"].ToString();
                        objWhiqc.Expdat = dtData.Rows[i]["EXPDAT"].ToString();
                        objWhiqc.Maxexp = dtData.Rows[i]["MAXEXP"].ToString();

                        #region Mark Jason code 20230822
                        ////保存期<=最大保存期，则最大保存期不改
                        ////保存期 > 最大保存期，则最大保存期要改成等于保存期

                        //DateTime dtTimeNow = DateTime.ParseExact(DateTime.Now.ToString("yyyyMMdd"), "yyyyMMdd", System.Globalization.CultureInfo.CurrentCulture);
                        //DateTime dtTimeExpdat = DateTime.ParseExact(strExpdat, "yyyyMMdd", System.Globalization.CultureInfo.CurrentCulture);
                        //DateTime dtTimeMaxexp = DateTime.ParseExact(strMaxexp, "yyyyMMdd", System.Globalization.CultureInfo.CurrentCulture);

                        ////保存期<=最大保存期，则最大保存期不改
                        //if (DateTime.Compare(dtTimeExpdat, dtTimeMaxexp) <= 0 && DateTime.Compare(dtTimeNow, dtTimeMaxexp) < 0)
                        //{
                        //    dtData.Rows[i]["Type"] = "Y（Normal）";
                        //}
                        ////红区，大于最大保存期
                        //if (DateTime.Compare(dtTimeNow, dtTimeMaxexp) >= 0)
                        //{
                        //    dtData.Rows[i]["Type"] = "R（Strict）";
                        //}

                        //if (dtData.Rows[i]["Type"].ToString() == "R（Strict）" && strInspectResult == "NC REVIEW")
                        //{
                        //    objWhiqc.Expdat_after = strExpdat;
                        //}
                        //else
                        //{
                        //    objWhiqc.Expdat_after = strMaxexp;
                        //}

                        #endregion

                        #region Brian Add 20230822
                        string strEXPTP = dtData.Rows[i]["EXPTP"].ToString();

                        #region 计算有效期和最大保存日期

                        //if (strEXPTP == "0")
                        //{
                        //    strExpdat_After = dtData.Rows[i]["EXPDAT"].ToString();
                        //    strMaxexp_After = dtData.Rows[i]["MAXEXP"].ToString();

                        //}
                        if (strEXPTP == "1")
                        {
                            //黄区OK和WAIVE的部分，延展有效期到最大保存日期
                            if (strInspectResult == "OK" || strInspectResult == "WAIVE")
                            {
                                strExpdat_After = dtData.Rows[i]["MAXEXP"].ToString();
                                strMaxexp_After = dtData.Rows[i]["MAXEXP"].ToString();
                            }
                        }
                        else if (strEXPTP == "2")
                        {
                            //红区OK和WAIVE的部分，采用IQC维护的有效期更新有效期和最大保存日期
                            if (strInspectResult == "OK" || strInspectResult == "WAIVE")
                            {
                                strExpdat_After = strExpdat_Keyin;
                                strMaxexp_After = strExpdat_Keyin;
                            }
                        }
                        objWhiqc.Expdat_after = strExpdat_After;
                        objWhiqc.Maxexp_after = strMaxexp_After;

                        #endregion

                        #region 计算Flag

                        string strQCFLG = string.Empty;
                        switch (strInspectResult)
                        {
                            case "OK":
                                strQCFLG = strEXPTP + "1";
                                break;
                            case "WAIVE":
                                strQCFLG = strEXPTP + "2";
                                break;
                        }

                        if (strQCFLG != "")
                        {
                            System.Text.RegularExpressions.Regex rx = new System.Text.RegularExpressions.Regex("^[0-2]{2}$");
                            if (!rx.IsMatch(strQCFLG))
                            {
                                throw new Exception("Unkown Flag, Please Check!");
                            }
                        }
                        objWhiqc.Qcflg = strQCFLG;

                        #endregion

                        #endregion

                        objWhiqc.Chkqty = dtDataInspect.Rows[0]["CHKQTY"].ToString();
                        objWhiqc.Result = dtDataInspect.Rows[0]["RESULT"].ToString();
                        objWhiqc.Appno = strNsmno;
                        objWhiqc.Mrbno = strMrbno;
                        objWhiqc.Exptp = strEXPTP;
                        objWhiqc.Chknam = dtDataInspect.Rows[0]["CHKNAM"].ToString();
                        objWhiqc.Chktim = "GetDate()";
                        objWhiqc.Rmak1 = dtDataInspect.Rows[0]["REASON"].ToString();
                        objWhiqc.Rmak2 = "";
                        objWhiqc.Rmak3 = "";
                        objWhiqc.Rmak4 = "";
                        objWhiqc.Rmak5 = "";
                        objWhiqc.Crnam = UserData.UserId;
                        objWhiqc.Crdat = "GetDate()";
                        objWhiqc.Monam = UserData.UserId;
                        objWhiqc.Modat = "GetDate()";

                        strSQL = objWhiqc.EntityGetInsertSql();
                        arySQL.Add(strSQL);
                    }
                    #endregion

                    #region Update WHITM
                    for (int i = 0; i < dtDataDetail.Rows.Count; i++)
                    {
                        sbSql.Append("Update WHITM set  ");
                        sbSql.AppendFormat(" TASKID='{0}' ", dtDataInspect.Rows[0]["TASKID"].ToString());
                        if (strExpdat_After != "") sbSql.AppendFormat(" ,ExpiryDate='{0}'", strExpdat_After);
                        if (strMaxexp_After != "") sbSql.AppendFormat(" ,MAXEXP='{0}'", strMaxexp_After);

                        sbSql.AppendFormat(" Where MANDT='{0}' ", dtDataDetail.Rows[i]["MANDT"].ToString());
                        sbSql.AppendFormat(" and COMCD='{0}' ", dtDataDetail.Rows[i]["COMCD"].ToString());
                        sbSql.AppendFormat(" and WERKS='{0}' ", dtDataDetail.Rows[i]["WERKS"].ToString());
                        sbSql.AppendFormat(" and LGORT='{0}' ", dtDataDetail.Rows[i]["LGORT"].ToString());
                        sbSql.AppendFormat(" and LOCAT='{0}' ", dtDataDetail.Rows[i]["LOCAT"].ToString());
                        sbSql.AppendFormat(" and MATNR='{0}' ", dtDataDetail.Rows[i]["MATNR"].ToString());
                        sbSql.AppendFormat(" and LIFNR='{0}' ", dtDataDetail.Rows[i]["LIFNR"].ToString());
                        sbSql.AppendFormat(" and DACOD='{0}' ", dtDataDetail.Rows[i]["DACOD"].ToString());
                        arySQL.Add(sbSql.ToString());
                    }
                    #endregion

                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                    return bolReturn;
                }
                catch (CommonObjectsException ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
            #endregion

            #region 保存检验单号及检验信息到WHIQC
            public bool CreateReInspectInfo(
                string strWerks,
