                    objWhiqc.Vedat = strVedat;
                    objWhiqc.Menge = strMenge;
                    objWhiqc.Chkqty = strChkQty;
                    objWhiqc.Result = string.Empty;
                    objWhiqc.Expdat = strExpdat;
                    objWhiqc.Maxexp = strMaxexp;
                    objWhiqc.QMEXP = strQmexp;
                    objWhiqc.Appno = string.Empty;
                    objWhiqc.Mrbno = string.Empty;
                    objWhiqc.Qcflg = string.Empty;
                    objWhiqc.Exptp = strExptp;
                    objWhiqc.Chknam = strChknam;
                    objWhiqc.Chktim = "GetDate()";
                    objWhiqc.Rmak1 = string.Empty;
                    objWhiqc.Rmak2 = string.Empty;
                    objWhiqc.Rmak3 = string.Empty;
                    objWhiqc.Rmak4 = string.Empty;
                    objWhiqc.Rmak5 = string.Empty;
                    objWhiqc.Crnam = UserData.UserId;
                    objWhiqc.Crdat = "GetDate()";
                    objWhiqc.Monam = UserData.UserId;
                    objWhiqc.Modat = "GetDate()";
                    objWhiqc.ENGID = strEngID;

                    strSQL = objWhiqc.EntityGetInsertSql();
                    arySQL.Add(strSQL);

                    #region Update WHITM
                    for (int i = 0; i < dtDataDetail.Rows.Count; i++)
                    {
                        sbSql.Clear();

                        sbSql.Append("Update WHITM set  ");
                        sbSql.AppendFormat(" TASKID='{0}' ", strTaskid);

                        sbSql.AppendFormat(" Where MANDT='{0}' ", dtDataDetail.Rows[i]["MANDT"].ToString());
                        sbSql.AppendFormat(" and COMCD='{0}' ", dtDataDetail.Rows[i]["COMCD"].ToString());
                        sbSql.AppendFormat(" and WERKS='{0}' ", dtDataDetail.Rows[i]["WERKS"].ToString());
                        sbSql.AppendFormat(" and LGORT='{0}' ", dtDataDetail.Rows[i]["LGORT"].ToString());
                        sbSql.AppendFormat(" and LOCAT='{0}' ", dtDataDetail.Rows[i]["LOCAT"].ToString());
                        sbSql.AppendFormat(" and MATNR='{0}' ", dtDataDetail.Rows[i]["MATNR"].ToString());
                        sbSql.AppendFormat(" and LIFNR='{0}' ", dtDataDetail.Rows[i]["LIFNR"].ToString());
                        sbSql.AppendFormat(" and DACOD='{0}' ", dtDataDetail.Rows[i]["DACOD"].ToString());
                        sbSql.AppendFormat(" and VEDAT='{0}' ", dtDataDetail.Rows[i]["VEDAT"].ToString());
                        sbSql.AppendFormat(" and LOCAT LIKE 'DY%' ");
                        sbSql.AppendFormat(" and (ISNULL(ExpiryDate,'')='' OR ExpiryDate <= CONVERT(VARCHAR, GETDATE(), 112))  ");
                        //sbSql.AppendFormat(" and TASKID='' ");

                        arySQL.Add(sbSql.ToString());
                    }
                    #endregion

                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                    return bolReturn;
                }
                catch (CommonObjectsException ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
            #endregion


            #region 保存检验单号及检验信息到WHIQC
            public bool CreateReInspectInfo(
                string strWerks,
                string strLgort,
                string strInsmk,
                string strMatnr,
                string strLifnr,
                string strDacod,
                string strVedat,
                string strMenge,
                string strChkQty,
                string strResult,
                string strExpdat,
                string strMaxexp,
                string strExpdat_Keyin,
                string strNsmno,
                string strMrbno,
                string strExptp,
                string strChknam,
                string strReason,
                string strNG_EE,
                string strNG_ME,
                DataTable dtDataDetail,
                out string strTaskid)
            {
                this.ControlMethodName = "SaveInspectInfo";
                this.ControlMethodParm = "('" + dtDataDetail + "')";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }
                try
                {
                    strTaskid = string.Empty;

                    DataWhiqc objWhiqc = new DataWhiqc(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    ArrayList arySQL = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();

                    bool bolReturn = false;

                    string strSQL = "";
                    string strExpdat_After = string.Empty;
                    string strMaxexp_After = string.Empty;

                    //针对选择行单据生成检验单号
                    //产生检验单号By厂区作区分
                    string strHeader = "R7" + DateTime.Now.ToString("yyyyMMdd");
                    string strSerno = GetInspectNo_IQC();
                    strTaskid = strHeader + (int.Parse(strSerno)).ToString("00000"); //检验单号

                    objWhiqc.ResetField();

                    objWhiqc.Mandt = UserData.Client;
                    objWhiqc.Comcd = UserData.CompanyCode;
                    objWhiqc.Taskid = strTaskid;
                    objWhiqc.Werks = strWerks;
                    objWhiqc.Lgort = strLgort;
                    objWhiqc.Insmk = strInsmk;
                    objWhiqc.Matnr = strMatnr;
                    objWhiqc.Lifnr = strLifnr;
                    objWhiqc.Dacod = strDacod;
                    objWhiqc.Vedat = strVedat;
                    objWhiqc.Menge = strMenge;
                    objWhiqc.Chkqty = strChkQty;
                    objWhiqc.Result = strResult;
                    objWhiqc.Expdat = strExpdat;
                    objWhiqc.Maxexp = strMaxexp;

                    #region Brian Add 20230822

                    #region 计算有效期和最大保存日期

                    //if (strEXPTP == "0")
                    //{
                    //    strExpdat_After = dtData.Rows[i]["EXPDAT"].ToString();
                    //    strMaxexp_After = dtData.Rows[i]["MAXEXP"].ToString();
                    //}
                    if (strExptp == "1")
                    {
                        //黄区OK和WAIVE的部分，延展有效期到最大保存日期
                        if (strResult == "OK" || strResult == "WAIVE")
                        {
                            strExpdat_After = strMaxexp;
                            strMaxexp_After = strMaxexp;
                        }
                    }
                    else if (strExptp == "2")
                    {
                        //红区OK和WAIVE的部分，采用IQC维护的有效期更新有效期和最大保存日期
                        if (strResult == "OK" || strResult == "WAIVE")
                        {
                            strExpdat_After = strExpdat_Keyin;
                            strMaxexp_After = strExpdat_Keyin;
                        }
                    }
                    objWhiqc.Expdat_after = strExpdat_After;
                    objWhiqc.Maxexp_after = strMaxexp_After;

                    #endregion

                    #region 计算Flag

                    string strQcflg = string.Empty;
                    switch (strResult)
                    {
                        case "OK":
                            strQcflg = strExptp + "1";
                            break;
                        case "WAIVE":
                            strQcflg = strExptp + "2";
                            break;
                    }

                    if (strQcflg != "")
                    {
                        System.Text.RegularExpressions.Regex rx = new System.Text.RegularExpressions.Regex("^[0-2]{2}$");
                        if (!rx.IsMatch(strQcflg))
                        {
                            throw new Exception("Unkown Flag, Please Check!");
                        }
                    }
                    objWhiqc.Qcflg = strQcflg;

                    #endregion

                    #endregion

                    objWhiqc.Appno = strNsmno;
                    objWhiqc.Mrbno = strMrbno;
                    objWhiqc.Exptp = strExptp;
                    objWhiqc.Chknam = strChknam;
                    objWhiqc.Chktim = "GetDate()";
                    objWhiqc.Rmak1 = strReason;
                    objWhiqc.Rmak2 = strNG_EE;
                    objWhiqc.Rmak3 = strNG_ME;
                    objWhiqc.Rmak4 = string.Empty;
                    objWhiqc.Rmak5 = string.Empty;
                    objWhiqc.Crnam = UserData.UserId;
                    objWhiqc.Crdat = "GetDate()";
                    objWhiqc.Monam = UserData.UserId;
                    objWhiqc.Modat = "GetDate()";

                    strSQL = objWhiqc.EntityGetInsertSql();
                    arySQL.Add(strSQL);

                    #region Update WHITM
                    for (int i = 0; i < dtDataDetail.Rows.Count; i++)
                    {
                        sbSql.Clear();

                        sbSql.Append("Update WHITM set  ");
                        sbSql.AppendFormat(" TASKID='{0}' ", strTaskid);
                        if (strExpdat_After != "") sbSql.AppendFormat(" ,ExpiryDate='{0}'", strExpdat_After);
                        if (strMaxexp_After != "") sbSql.AppendFormat(" ,MAXEXP='{0}'", strMaxexp_After);

                        sbSql.AppendFormat(" Where MANDT='{0}' ", dtDataDetail.Rows[i]["MANDT"].ToString());
                        sbSql.AppendFormat(" and COMCD='{0}' ", dtDataDetail.Rows[i]["COMCD"].ToString());
                        sbSql.AppendFormat(" and WERKS='{0}' ", dtDataDetail.Rows[i]["WERKS"].ToString());
                        sbSql.AppendFormat(" and LGORT='{0}' ", dtDataDetail.Rows[i]["LGORT"].ToString());
                        sbSql.AppendFormat(" and LOCAT='{0}' ", dtDataDetail.Rows[i]["LOCAT"].ToString());
                        sbSql.AppendFormat(" and MATNR='{0}' ", dtDataDetail.Rows[i]["MATNR"].ToString());
                        sbSql.AppendFormat(" and LIFNR='{0}' ", dtDataDetail.Rows[i]["LIFNR"].ToString());
                        sbSql.AppendFormat(" and DACOD='{0}' ", dtDataDetail.Rows[i]["DACOD"].ToString());

                        arySQL.Add(sbSql.ToString());
                    }
                    #endregion

                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                    return bolReturn;
                }
                catch (CommonObjectsException ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
            #endregion


            #region 更新检验结果到WHIQC
            public bool UpdateReInspectInfo(
                string strTaskid,
                string strWerks,
                string strLgort,
                string strChkQty,
                string strResult,
                string strExpdat,
                string strMaxexp,
                string strQmexp,
                string strNsmno,
                string strMrbno,
                string strExptp,
                string strChknam,
                string strReason,
                string strMaterialType,
                string strNGSymptom,
                string strTempid,
                string strEngID,
                string strGetCrdat)
            {
                this.ControlMethodName = "UpdateInspectInfo";
                this.ControlMethodParm = "('" + strTaskid + ",''" + strWerks + ",''" + strLgort + ",''" + strChkQty + ",''" + strResult + ",''" + strExpdat + ",''" + strMaxexp
                    + ",''" + strQmexp + ",''" + strNsmno + ",''" + strMrbno + ",''" + strExptp + ",''" + strChknam + ",''" + strReason + ",''" + strMaterialType + ",''" + strNGSymptom + ",''" + strTempid + ",''" + strEngID + ",''" + strGetCrdat + "')";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }
                try
                {
                    DataWhiqc objWhiqc = new DataWhiqc(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    ArrayList arySQL = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();
                    bool bolReturn = false;
                    string strExpdat_After = string.Empty;
                    string strMaxexp_After = string.Empty;

                    #region Update WHIQC

                    sbSql.Append("Update WHIQC set  ");
                    sbSql.AppendFormat("  CHKQTY='{0}',CHKNAM=N'{1}',CHKTIM=GETDATE(),", strChkQty, strChknam);
                    sbSql.AppendFormat("  RESULT='{0}',RMAK1=N'{1}',", strResult, strReason);
                    sbSql.AppendFormat("  MTYPE=N'{0}',NGDES=N'{1}', ", strMaterialType, strNGSymptom);
                    sbSql.AppendFormat("  APPNO='{0}',MRBNO='{1}', ", strNsmno, strMrbno);
                    sbSql.AppendFormat("  ENGID='{0}', ", strEngID);
                    //sbSql.AppendFormat("  EXPDAT_AFTER='{0}',MAXEXP_AFTER='{1}',", strExpdat_After, strMaxexp_After);
                    if (!string.IsNullOrEmpty(strTempid))
                    {
                        sbSql.AppendFormat("  TEMPID='{0}', SNDTIM=GETDATE(),", strTempid);
                    }
                    sbSql.AppendFormat("  MONAM='{0}', MODAT=GETDATE()", UserData.UserId);
                    sbSql.AppendFormat(" Where MANDT='{0}' ", UserData.Client);
                    sbSql.AppendFormat(" and COMCD='{0}' ", UserData.CompanyCode);
                    sbSql.AppendFormat(" and WERKS='{0}' ", strWerks);
                    sbSql.AppendFormat(" and LGORT='{0}' ", strLgort);
                    sbSql.AppendFormat(" and TASKID='{0}' ", strTaskid);
                    arySQL.Add(sbSql.ToString());

                    #endregion

                    if (strResult == "OK" || strResult == "WAIVE")
                    {
                        #region Brian Add 20230822

                        #region 计算有效期和最大保存日期

                        //if (strExptp == "0")
                        //{
                        //    strExpdat_After = strExpdat;
                        //    strMaxexp_After = strMaxexp;
                        //}
                        //else 
                        if (strExptp == "1")        //黄区OK和WAIVE的部分，延展有效期到最大保存日期
                        {
                            strExpdat_After = strMaxexp;
                            strMaxexp_After = strMaxexp;
                        }
                        else if (strExptp == "2")   //红区OK和WAIVE的部分，采用IQC维护的有效期更新有效期和最大保存日期
                        {
                            strExpdat_After = strQmexp.Trim();
                            strMaxexp_After = strQmexp.Trim();
                        }

                        #endregion

                        #region 计算Flag

                        string strQcflg = string.Empty;
                        switch (strResult)
                        {
                            case "OK":
                                strQcflg = strExptp + "1";
                                break;
                            case "WAIVE":
                                strQcflg = strExptp + "2";
                                break;
                        }

                        if (strQcflg != "")
                        {
                            System.Text.RegularExpressions.Regex rx = new System.Text.RegularExpressions.Regex("^[0-2]{2}$");
                            if (!rx.IsMatch(strQcflg))
                            {
                                throw new Exception("Unkown Flag, Please Check!");
                            }
                        }

                        #endregion

                        #endregion

                        #region Update WHIQC

                        sbSql.Append("Update WHIQC set  ");
                        sbSql.AppendFormat("  QCFLG='{0}',", strQcflg);
                        sbSql.AppendFormat("  EXPDAT_AFTER='{0}',MAXEXP_AFTER='{1}'", strExpdat_After, strMaxexp_After);
                        sbSql.AppendFormat(" Where MANDT='{0}' ", UserData.Client);
                        sbSql.AppendFormat(" and COMCD='{0}' ", UserData.CompanyCode);
                        sbSql.AppendFormat(" and WERKS='{0}' ", strWerks);
                        sbSql.AppendFormat(" and LGORT='{0}' ", strLgort);
                        sbSql.AppendFormat(" and TASKID='{0}' ", strTaskid);
                        arySQL.Add(sbSql.ToString());

                        #endregion  
                        
                        #region Insert WHLOG 针对加锁的部分，插入解锁日志

                        sbSql.AppendLine("INSERT INTO WHLOG")
                            .AppendLine("(MANDT, COMCD, WERKS, LGORT, CGCLS, OLOCA, NLOCA, MATNR, CHARG, LIFNR, TRNTP, MBLNR, OMBLN, EBELN, MENGE, INSMK, MRGID, CRNAM,")
                            .AppendLine("CRDAT, RMAK1, INDAT, SERNO, DACOD, LOCOD, VEDAT, EXPDAT, TASKID, MAXEXP)")
                            .AppendLine("SELECT MANDT, COMCD, WERKS, LGORT, 'L-' AS CGCLS, LOCAT, '' AS NLOCA, MATNR, CHARG, LIFNR, '' AS TRNTP, MBLNR, '' AS OMBLNR, EBELN, MENGE,")
                            .AppendLine("INSMK, MRGID, 'System' AS CRNAM, GETDATE() AS CRDAT, RMAK1, INDAT, '' AS SERNO, DACOD, LOCOD, VEDAT, ExpiryDate, TASKID, MAXEXP")
                            .AppendLine("FROM WHITM")
                            .AppendFormat(" Where MANDT='{0}' ", UserData.Client)
                            .AppendFormat(" and COMCD='{0}' ", UserData.CompanyCode)
                            .AppendFormat(" and WERKS='{0}' ", strWerks)
                            .AppendFormat(" and LGORT='{0}' ", strLgort)
                            .AppendFormat(" and TASKID='{0}' ", strTaskid)
                            .AppendFormat(" and LOCKED='Y' ");

                        arySQL.Add(sbSql.ToString());

                        #endregion

                        #region Update WHITM 延展有效期，并解锁

                        sbSql.AppendFormat("Update WHITM set ExpiryDate='{0}' ,MAXEXP='{1}' ,LOCKED='' ,LKDAT=NULL", strExpdat_After, strMaxexp_After)
                            .AppendFormat(" Where MANDT='{0}' ", UserData.Client)
                            .AppendFormat(" and COMCD='{0}' ", UserData.CompanyCode)
                            .AppendFormat(" and WERKS='{0}' ", strWerks)
                            .AppendFormat(" and LGORT='{0}' ", strLgort)
                            .AppendFormat(" and TASKID='{0}' ", strTaskid);

                        arySQL.Add(sbSql.ToString());

                        arySQL.RemoveRange(0, 3);
                        #endregion

                    }

                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                    return bolReturn;
                }
                catch (CommonObjectsException ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
            #endregion





            #region 更新检验结果到WHIQC
            public bool UpdateInspectInfo(DataTable dtData, DataTable dtDataDetail, DataTable dtDataInspect, string strExpdat_Keyin, string strNsmno, string strMrbno, string strResult, string strReason)
            {
                this.ControlMethodName = "UpdateInspectInfo";
                this.ControlMethodParm = "('" + dtDataInspect + "')";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }
                try
                {
                    DataWhiqc objWhiqc = new DataWhiqc(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    ArrayList arySQL = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();
                    bool bolReturn = false;
                    string strExpdat_After = string.Empty;
                    string strMaxexp_After = string.Empty;

                    #region Update WHIQC
                    for (int i = 0; i < dtDataInspect.Rows.Count; i++)
                    {
                        #region Brian Add 20230822

                        string strEXPTP = dtData.Rows[i]["EXPTP"].ToString();

                        #region 计算有效期和最大保存日期

                        if (strEXPTP == "0")
                        {
                            strExpdat_After = dtData.Rows[i]["EXPDAT"].ToString().Trim();
                            strMaxexp_After = dtData.Rows[i]["MAXEXP"].ToString().Trim();

                        }
                        else if (strEXPTP == "1")
                        {
                            //黄区OK和WAIVE的部分，延展有效期到最大保存日期
                            if (strResult == "OK" || strResult == "WAIVE")
                            {
                                strExpdat_After = dtData.Rows[i]["MAXEXP"].ToString().Trim();
                                strMaxexp_After = dtData.Rows[i]["MAXEXP"].ToString().Trim();
                            }
                        }
                        else if (strEXPTP == "2")
                        {
                            //红区OK和WAIVE的部分，采用IQC维护的有效期更新有效期和最大保存日期
                            if (strResult == "OK" || strResult == "WAIVE")
                            {
                                strExpdat_After = strExpdat_Keyin.Trim();
                                strMaxexp_After = strExpdat_Keyin.Trim();
                            }
                        }
                        #endregion

                        #region 计算Flag

                        string strQCFLG = string.Empty;
                        switch (strResult)
                        {
                            case "OK":
                                strQCFLG = strEXPTP + "1";
                                break;
                            case "WAIVE":
                                strQCFLG = strEXPTP + "2";
                                break;
                        }

                        if (strQCFLG != "")
                        {
                            System.Text.RegularExpressions.Regex rx = new System.Text.RegularExpressions.Regex("^[0-2]{2}$");
                            if (!rx.IsMatch(strQCFLG))
                            {
                                throw new Exception("Unkown Flag, Please Check!");
                            }
                        }
                        #endregion

                        #endregion


                        sbSql.Append("Update WHIQC set  ");
                        sbSql.AppendFormat("  RESULT='{0}',RMAK1=N'{1}',QCFLG='{2}',", strResult, strReason, strQCFLG);
                        sbSql.AppendFormat("  APPNO='{0}',MRBNO='{1}', ", strNsmno, strMrbno);
                        sbSql.AppendFormat("  EXPDAT_AFTER='{0}',MAXEXP_AFTER='{1}' ", strExpdat_After, strMaxexp_After);
                        sbSql.AppendFormat(" Where MANDT='{0}' ", dtDataInspect.Rows[i]["MANDT"].ToString());
                        sbSql.AppendFormat(" and WERKS='{0}' ", dtDataInspect.Rows[i]["WERKS"].ToString());
                        sbSql.AppendFormat(" and LGORT='{0}' ", dtDataInspect.Rows[i]["LGORT"].ToString());
                        sbSql.AppendFormat(" and TASKID='{0}' ", dtDataInspect.Rows[i]["TASKID"].ToString());
                        arySQL.Add(sbSql.ToString());
                    }
                    #endregion

                    #region Update WHITM
                    for (int i = 0; i < dtDataDetail.Rows.Count; i++)
                    {
                        sbSql.Append("Update WHITM set  ");
                        sbSql.AppendFormat(" TASKID='{0}' ", dtDataDetail.Rows[i]["TASKID"].ToString());
                        if (strExpdat_After != "") sbSql.AppendFormat(" ,ExpiryDate='{0}'", strExpdat_After);
                        if (strMaxexp_After != "") sbSql.AppendFormat(" ,MAXEXP='{0}'", strMaxexp_After);

                        sbSql.AppendFormat(" Where MANDT='{0}' ", dtDataDetail.Rows[i]["MANDT"].ToString());
                        sbSql.AppendFormat(" and COMCD='{0}' ", dtDataDetail.Rows[i]["COMCD"].ToString());
                        sbSql.AppendFormat(" and WERKS='{0}' ", dtDataDetail.Rows[i]["WERKS"].ToString());
                        sbSql.AppendFormat(" and LGORT='{0}' ", dtDataDetail.Rows[i]["LGORT"].ToString());
                        sbSql.AppendFormat(" and LOCAT='{0}' ", dtDataDetail.Rows[i]["LOCAT"].ToString());
                        sbSql.AppendFormat(" and MATNR='{0}' ", dtDataDetail.Rows[i]["MATNR"].ToString());
                        sbSql.AppendFormat(" and LIFNR='{0}' ", dtDataDetail.Rows[i]["LIFNR"].ToString());
                        sbSql.AppendFormat(" and DACOD='{0}' ", dtDataDetail.Rows[i]["DACOD"].ToString());
                        arySQL.Add(sbSql.ToString());
                    }
                    #endregion

                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                    return bolReturn;
                }
                catch (CommonObjectsException ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
            #endregion

            #region 查询检验已完成单据
            public DataTable QueryIQCTaskID(string strTaskID)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryIQCTaskID";
                this.ControlMethodParm = "(" + strTaskID + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    //                    ArrayList alColumns = new ArrayList();
                    //                    ArrayList alConditions = new ArrayList();
                    //                    DataWhiqc objWhiqc = new DataWhiqc(UserData);

                    //                    alColumns.Add("*");
                    //                    alColumns.Add(@"CASE 
                    //                    		                            WHEN CONVERT(VARCHAR, GETDATE(), 112) <= IIF(EXPDAT_AFTER = '', EXPDAT, EXPDAT_AFTER)
                    //                    			                            THEN 0
                    //                    		                            WHEN CONVERT(VARCHAR, GETDATE(), 112) > IIF(EXPDAT_AFTER = '', EXPDAT, EXPDAT_AFTER)
                    //                    			                            AND CONVERT(VARCHAR, GETDATE(), 112) <= IIF(MAXEXP_AFTER = '', MAXEXP, MAXEXP_AFTER)
                    //                    			                            THEN 1
                    //                    		                            WHEN CONVERT(VARCHAR, GETDATE(), 112) > IIF(MAXEXP_AFTER = '', MAXEXP, MAXEXP_AFTER)
                    //                    			                            THEN 2
                    //                    		                            END AS EXPTP_AFTER");
                    //                    alConditions.Add(string.Format("MANDT='{0}'", UserData.Client));
                    //                    alConditions.Add(string.Format("COMCD='{0}'", UserData.CompanyCode));
                    //                    alConditions.Add(string.Format("TASKID='{0}'", strTaskID));

                    //                    return objWhiqc.EntityQuery(alColumns, alConditions, true, true);

                    StringBuilder sbSQL = new StringBuilder();

                    sbSQL.AppendLine(@"SELECT A.MANDT, A.COMCD, A.TASKID, A.WERKS, A.LGORT, A.INSMK, A.MATNR, A.LIFNR, A.MENGE, A.DACOD, A.VEDAT, A.EXPDAT, A.EXPDAT_AFTER,")
                        .AppendLine("A.MAXEXP, A.MAXEXP_AFTER, A.QMEXP, A.CHKQTY, A.RESULT, A.CHKNAM, A.CHKTIM, A.QCFLG, A.APPNO, A.MRBNO,")
                        .AppendLine("IIF(B.TASKID IS NULL, EXPTP, CASE WHEN CONVERT(VARCHAR, GETDATE(), 112) < B.EXPDAT THEN 0 WHEN CONVERT(VARCHAR, GETDATE(), 112) >= B.EXPDAT AND")
                        .AppendLine("CONVERT(VARCHAR, GETDATE(), 112) < B.MAXEXP THEN 1 WHEN CONVERT(VARCHAR, GETDATE(), 112) >= B.MAXEXP THEN 2 END) AS EXPTP,")
