            #region 查询检验已完成单据
            public DataTable QueryIQCTaskID(string strWerks, string strLgort, string strResult, string strTaskID, string strMatnr, string strStartDate, string strEndDate, string strStatus, bool bolNotPrint, string strMtype)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryIQCTaskID";
                this.ControlMethodParm = "(" + strWerks + "," + strLgort + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataTable dtData = new DataTable();
                try
                {
                    ControlHandleDB();
                    StringBuilder sbSQL = new StringBuilder();

                    sbSQL.Append(@"SELECT I.TASKID,I.WERKS,I.CRDAT AS INPUTDATE,I.MATNR,P.MAKTX AS DESCRI,I.LIFNR,REPLACE(I.PRTID,'0', '') AS PRTID,I.MENGE,I.SampleQty,CASE WHEN (CONVERT(INT, REPLACE(I.PRTID,'0', '')) * I.SampleQty)>I.MENGE THEN I.MENGE ELSE (CONVERT(INT, REPLACE(I.PRTID,'0', '')) * I.SampleQty) END AS TotalQty,I.VEDAT AS MANUDATE,I.RESULT,I.CHKTIM,I.CHKNAM,I.EXPDAT,I.EXPDAT_AFTER,I.MAXEXP,I.MAXEXP_AFTER,I.QMEXP,(CASE WHEN I.RESULT IN ('OK', 'REJECT', 'WAIVE') THEN 'CLOSED' WHEN I.RESULT IN ('NG1', 'NG2') THEN 'ONGOING' ELSE 'OPEN' END) AS Status,I.APPNO AS NSMNO,I.NGDES,I.RMAK1 AS Remark,I.RMAK2 AS NSMResult,I.RMAK3 AS NSMReason,CASE I.EXPTP WHEN '0' THEN 'G' WHEN '1' THEN 'Y' WHEN '2' THEN 'R' END AS Type,I.EngID
                                   FROM (SELECT *,(CASE WHEN MENGE>32 AND MENGE<=170 THEN 32 WHEN MENGE>=171 AND MENGE<=288 THEN 32 WHEN MENGE>=289 AND MENGE<=544 THEN 32 WHEN MENGE>=545 AND MENGE<=960 THEN 40 WHEN MENGE>=961 AND MENGE<=1632 THEN 48 WHEN MENGE>=1633 AND MENGE<=3072 THEN 64 WHEN MENGE>=3073 AND MENGE<=5440 THEN 80 WHEN MENGE>=5441 AND MENGE<=9216 THEN 80 WHEN MENGE>=9217 AND MENGE<=17408 THEN 80 WHEN MENGE>=17409 AND MENGE<=30720 THEN 80 WHEN MENGE>=30721 THEN 80 ELSE MENGE END) AS SampleQty FROM WHIQC WITH(NOLOCK)) AS I LEFT JOIN WHPAT AS P WITH(NOLOCK) ON I.MATNR=P.MATNR where 1=1"); //  AND ISNULL(I.RESULT,'') IN ('OK','REJECT','WAIVE')
                    if (!string.IsNullOrEmpty(strWerks))
                    {
                        sbSQL.AppendFormat(" AND I.WERKS = '{0}'", strWerks);
                    }
                    if (!string.IsNullOrEmpty(strLgort))
                    {
                        sbSQL.AppendFormat(" AND I.LGORT = '{0}'", strLgort);
                    }
                    if (!string.IsNullOrEmpty(strTaskID))
                    {
                        sbSQL.AppendFormat(" AND I.TASKID = '{0}'", strTaskID);
                    }
                    if (!string.IsNullOrEmpty(strMatnr))
                    {
                        sbSQL.AppendFormat(" AND I.MATNR = '{0}'", strMatnr);
                    }
                    if (!string.IsNullOrEmpty(strResult))
                    {
                        sbSQL.AppendFormat(" AND I.RESULT = '{0}'", strResult);
                    }
                    switch (strStatus)
                    {
                        case "OPEN":
                            sbSQL.Append(" AND ISNULL(I.RESULT,'') IN ('','NC REVIEW')");
                            break;
                        case "ONGOING":
                            sbSQL.Append(" AND ISNULL(I.RESULT,'') IN ('NG1','NG2')");
                            break;
                        case "CLOSED":
                            sbSQL.Append(" AND ISNULL(I.RESULT,'') IN ('OK','REJECT','WAIVE')");
                            break;
                    }
                    if (bolNotPrint)
                    {
                        sbSQL.AppendFormat(" AND CONVERT(INT, IIF(ISNULL(I.PRTID, '') = '', 0, I.PRTID)) = 0");
                    }
                    if (strMtype != "")
                    {
                        if (strMtype == "EE")
                        {
                            sbSQL.AppendFormat(" AND Mtype='EE'");
                        }
                        else if (strMtype == "ME")
                        {
                            sbSQL.AppendFormat(" AND Mtype='ME'");
                        }
                    }

                    sbSQL.AppendFormat(" and CONVERT(VARCHAR(8), I.CRDAT, 112) BETWEEN '{0}' AND '{1}'", strStartDate, strEndDate);

                    dtData = ControlSqlAccess.GetDataTable(sbSQL.ToString());
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return dtData;
            }
            #endregion

