            public DataTable GetTwwStockData(string strWerks, string gstrLgort, List<string> lsLocat)
            {

                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QuerySimulationGrrno_DateCode";
                this.ControlMethodParm = "(" + strWerks + "," + gstrLgort + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                DataWhitm objWhitm = new DataWhitm(this.UserData);
                // 创建查询列名
                ArrayList alCols = new ArrayList();
                // 创建查询条件
                ArrayList alCondition = new ArrayList();
                // 添加列名
                alCols.Add("*");
                // 添加条件
                alCondition.Add(" WERKS = '" + strWerks + "'");
                alCondition.Add(" LGORT = '" + gstrLgort + "'");
                // lsLocat, 为item添加单引号,使用逗号隔开
                alCondition.Add(" LOCAT IN (" + lsLocat.Aggregate(string.Empty, (current, item) => current + ("'" + item + "',")).TrimEnd(',') + ")");
                // 执行查询
                return objWhitm.EntityQuery(alCols, alCondition, false);
            }
