            public DataTable GetNGSymptom(string strType, string strResult)
            {
                try
                {
                    DataTable dtResult = new DataTable();

                    DataWhctrl objWhctrl = new DataWhctrl(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alCondictions = new ArrayList();

                    alColumns.Clear();
                    alColumns.Add("CTRLC1");
                    alColumns.Add("CTRLN1");

                    alCondictions.Clear();
                    alCondictions.Add(string.Format("(MANDT='{0}')", UserData.Client));
                    alCondictions.Add("(SOLDTO='QWMS')");
                    alCondictions.Add(string.Format("(CTRLID='NGSymptom_{0}')", strType));

                    if (strResult == "NG1" || strResult == "NG2" || strResult == "OK")
                        alCondictions.Add(string.Format("(CTRLC2='{0}' OR CTRLC2='')", strResult));


                    alCondictions.Add("(COMCD='" + COMCD.ToString() + "')");

                    string strsql = objWhctrl.EntityGetQuerySql(alColumns, alCondictions, true, true);

                    dtResult = objWhctrl.EntityQuery(alColumns, alCondictions, true, true);

